INSERT INTO spells (id, name, school, subschool, descriptor, level, type, class_lists, casting_time, range, target, area, effect, duration, saving_throw, spell_resistance, description, material, arcane_focus, divine_focus, costly_components)
VALUES
  ('abeyance', 'Abeyance', 'abjuration', NULL, NULL, 2, 'divine', 'cleric 2, inquisitor 2, paladin 2', '1 minute', 'touch', 'creature touched', NULL, NULL, '24 hours', 'Will negates (harmless)', 'yes (harmless)', 'Abeyance suppresses the effects of a single curse on a creature. It does not restore any damage or drain that might have been caused by the curse. Abeyance cannot suppress curses that cannot be removed by remove curse, but it can suppress curses such as lycanthropy that require remove curse along with additional measures. An individual curse can be suppressed only once by abeyance, even if cast by a different caster.', 'a flask of holy water worth 25 gp', NULL, true, true),
  ('abjuring_step', 'Abjuring Step', 'abjuration', 'force', NULL, 1, 'arcane', 'alchemist 1, bard 1, magus 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level or until discharged', NULL, NULL, 'This spell creates a subtle and complicated force effect that is most effective when used by a still or slow-moving spellcaster or formula user. While you are subject to this spell, you can take two 5-foot steps each round and still cast spells and use spell-like abilities without provoke attacks of opportunity.', 'a rabbit’s foot', NULL, false, false),
  ('ablative_barrier', 'Ablative Barrier', 'conjuration', 'creation', 'force', 2, 'arcane', 'alchemist 2, bloodrager 2, magus 2, occultist 2, psychic 3, sorcerer/wizard 3, summoner 2, unchained summoner 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level or until discharged', 'Will negates (harmless)', 'no', 'Invisible layers of solid force surround and protect the target, granting that target a +2 armor bonus to AC. Additionally, the first 5 points of lethal damage the target takes from each attack are converted into nonlethal damage. Against attacks that already deal nonlethal damage, the target gains DR 5/—. Once this spell has converted 5 points of damage to nonlethal damage per caster level (maximum 50 points), the spell is discharged.', 'a piece of metal cut from a shield', NULL, false, false),
  ('ablative_sphere', 'Ablative Sphere', 'abjuration', NULL, NULL, 3, 'arcane', 'sorcerer/wizard 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute per level (D)', NULL, NULL, 'An immobile, crystalline, web-like globe surrounds you. When the ablative sphere winks into existence, it provides you with improved cover (see below). The barrier does not impede a spell’s line of sight or effect.', 'a crystalline sphere worth 10 gp', NULL, false, true),
  ('aboleth_s_lung', 'Aboleth’s Lung', 'transmutation', NULL, NULL, 2, 'divine', 'cleric 2, druid 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'living creatures touched', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'The targets are able to breathe water, freely. However, they can no longer breathe air.', 'piece of seaweed', NULL, true, false),
  ('absolution', 'Absolution', 'abjuration', NULL, NULL, 4, 'divine', 'cleric 4, paladin 4', '1 round', 'touch', 'living creature touched', NULL, NULL, 'instantaneous', 'none', 'no', 'You purge impure thoughts from the target’s mind and fill him with exultant relief at the forgiveness of his sins.', 'a vial of holy water', NULL, true, false),
  ('absorb_rune', 'Absorb Rune', 'abjuration', NULL, NULL, 4, 'divine', 'bard 4, cleric 4, magus 4, occultist 4, sorcerer/wizard 4', '1 standard action', 'touch', 'one spell effect', NULL, NULL, 'instantaneous plus 1 minute/level (see text)', 'Will negates (harmless)', 'yes (harmless)', 'This spell allows you to lay your hand upon a magical glyph, symbol, or other magical spell effect (referred to in this spell description as a rune) and attempt to absorb the essence of its effect. To absorb a rune, you must be aware of the rune’s existence (but need not know the details of what it actually does) and then succeed at a caster level check (DC = 10 + the caster level of the spell affect being absorbed) as you touch the rune in question. If you fail this caster level check, the magical rune is not triggered unless you fail the roll by 5 or more.', 'a white silk glove worth 25 gp', NULL, false, true),
  ('absorb_toxicity', 'Absorb Toxicity', 'necromancy', NULL, NULL, 3, 'divine', 'alchemist 3, druid 4, sorcerer/wizard 5, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level or until discharged', 'see text', 'no', 'You absorb the toxicity of your surroundings, becoming toxic as a result.', 'a thorn from a poisonous plant', NULL, false, false),
  ('absorbing_barrier', 'Absorbing Barrier', 'abjuration', NULL, NULL, 4, 'arcane', 'alchemist 4, sorcerer/wizard 4, summoner 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '40-ft.-radius sphere; see text (S)', NULL, '1 hour/level or until discharged', 'none (harmless)', 'no (harmless)', 'You ward all creatures and objects in the area from ranged weapons. The spell’s area of effect is often a sphere, although you can shape it to be smaller than the maximum area or to exclude certain adjacent areas or objects (for example, if you are warding a specific structure, or if you are roughly warding the front lines of a battlefield). This spell’s area is also up to 40 feet in height, so flying creatures benefit as long as they are in this area of effect.', NULL, 'a jagged scrap of metal', false, false),
  ('absorbing_inhalation', 'Absorbing Inhalation', 'transmutation', NULL, 'air', 4, 'divine', 'alchemist 4, bloodrager 4, druid 4, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one cloud-like effect, up to one 10-ft. cube/level', NULL, NULL, '1 round/level; see text', 'see text', 'no', 'You grant your lungs inhuman strength and capacity, allowing you to harmlessly and completely inhale one gas, fog, smoke, mist, or similar cloud-like effect. If the targeted cloud is a magical effect, you must succeed at a caster level check (DC 11 + the effect’s caster level) to inhale it. Inhaling the cloud removes it from the area, leaving normal air in its place. If the cloud is too large for you to affect with a single casting of this spell, you may instead inhale a portion of the cloud, but you must inhale the portion of the cloud closest to you. This spell has no effect on gaseous creatures. It can only affect an instantaneous-duration cloud (such as a breath weapon) if you ready an action to cast the spell in response.', NULL, NULL, false, false),
  ('absorbing_touch', 'Absorbing Touch', 'transmutation', NULL, NULL, 3, 'arcane', 'alchemist 3', '1 standard action', 'touch', NULL, NULL, NULL, '1 day/level (D)', 'Fortitude negates (object)', 'no', 'You absorb the next object your hand touches into your body. If you are already holding an object, you can attempt to absorb it; otherwise, you may touch an object as a standard action separate from casting the spell. You can absorb any nonmagical, nonliving object weighing no more than 1 pound per caster level. A container and its contents count as a single object. Objects in the possession of another creature receive a Fortitude Saving Throw to prevent absorption. You may continue to attempt to absorb objects until one is absorbed.', NULL, NULL, false, false),
  ('abstemiousness', 'Abstemiousness', 'transmutation', NULL, NULL, 1, 'divine', 'bard 1, cleric/oracle 1, druid 1, witch 1', '1 standard action', 'touch', 'a handful of berries, grains, nuts, or rice', NULL, NULL, '1 hour', 'Fort negates (harmless)', 'yes (harmless)', 'This spell magically enhances a handful of simple food, imbuing it with enough nutrition to satisfy a Medium or smaller creature for a full day. The spell does not create food, and thus will not alone prevent someone from starving, but it can extend even limited reserves for lengthy periods.', NULL, NULL, false, false),
  ('absurdity', 'Absurdity', 'illusion', 'phantasm', 'emotion, mind-affecting', 2, 'arcane', 'bard 2, medium 2, mesmerist 2, psychic 2, spiritualist 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'up to one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 minute/level (D)', 'Will negates', 'no', 'Your targets perceive intimidation and threats as laughably absurd.', NULL, NULL, false, false),
  ('abundant_ammunition', 'Abundant Ammunition', 'conjuration', 'summoning', NULL, 1, 'divine', 'bard 1, cleric 1, psychic 1, ranger 1, sorcerer/wizard 1', '1 standard action', NULL, 'one container touched', NULL, NULL, '1 minute/level', 'none', 'no', 'When cast on a container such as a quiver or a pouch that contains nonmagical ammunition or shuriken (including masterwork ammunition or shuriken, but not special materials, alchemical attributes, or nonmagical treatments on the ammunition) at the start of each round this spell replaces any ammunition taken from the container the round before. The ammunition taken from the container the round before vanishes. If, after casting this spell, you cast a spell that enhances projectiles, such as align weapon or greater magic weapon, on the same container, all projectiles this spell conjures are affected by that spell.', 'a single piece of ammunition', NULL, true, false),
  ('abyssal_vermin', 'Abyssal Vermin', 'transmutation', NULL, NULL, 2, 'divine', 'antipaladin 2, arcanist 4, cleric/oracle 4, crimson assassin 4, sorcerer/wizard 4, warpriest 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one vermin or vermin swarm', NULL, NULL, '1 minute/level', 'Fort negates (see text)', 'yes', 'You infuse the target with power from the Abyss, granting it the fiendish creature simple template. The swarm gains DR 5/good if it has at least 5 Hit Dice, or DR 10/good it if has at least 11 HD. It gains cold resistance 5 and fire resistance 5 if it has at least 5 HD, or cold resistance 10 and fire resistance 10 if it has at least 11 HD. It gains spell resistance equal to its CR + 6.', NULL, NULL, false, false),
  ('accelerate_poison', 'Accelerate Poison', 'transmutation', NULL, 'poison', 2, 'divine', 'druid 2, ranger 2, sorcerer/wizard 2; Elemental School water 2', '1 standard action', 'touch', NULL, NULL, NULL, 'instantaneous', 'Fortitude negates', 'yes', 'You hasten the onset of poison in the target. If the poison normally has an onset time, its effects begin immediately. If the poison has no onset time, its frequency is doubled, requiring two saving throws and inflicting damage twice per round or minute, though its duration is halved. Accelerate poison does not change the cure condition for the poison. If the target is affected by more than one poison, you may choose which is affected if you administered the poison; otherwise, randomly determine which poison is affected.', 'a thorn', NULL, false, false),
  ('accept_affliction', 'Accept Affliction', 'conjuration', 'healing', 'good', 3, 'divine', 'bard 3, cleric 3, druid 3, paladin 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Fort negates (harmless)', 'yes (harmless)', 'The caster can transfer the effects of afflictions such as curses, diseases, and poisons from the target creature to himself. This spell can also transfer the blinded, deafened, fatigued, nauseated, shaken, and sickened conditions. All aspects of the transferred afflictions (save DCs, remaining duration, removal conditions, and so on) remain the same, but affect the caster instead of the original target. After transferring the affliction or condition, the caster is free to cure it in any way he can.', 'a dove’s heart', NULL, true, false),
  ('accursed_glare', 'Accursed Glare', 'necromancy', NULL, 'curse', 3, 'divine', 'antipaladin 3, sorcerer/wizard 3, witch 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 day/level', 'Will negates', 'yes', 'You channel a fell curse through your glare. If the target fails its saving throw, it begins to obsessively second guess its actions and attract bad luck. Whenever the target attempts an attack roll or saving throw while the curse lasts, it must roll twice and take the lower result. While you cast this spell, an ally within range of the subject can attempt an Intimidate check as a move action (DC = save DC of this spell); on a success, the ally adds its own glare to yours, granting you a +2 bonus on your caster level check to overcome spell resistance (if any). Multiple allies can attempt Intimidate checks; this bonus stacks.', NULL, NULL, false, false),
  ('acid_arrow', 'Acid Arrow', 'conjuration', 'creation', 'acid', 2, 'arcane', 'bloodrager 2, magus 2, sorcerer/wizard 2; Elemental School earth 2', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'one arrow of acid', '1 round + 1 round per three levels', 'none', 'no', 'An arrow of acid springs from your hand and speeds to its target. You must succeed on a ranged touch attack to hit your target. The arrow deals 2d4 points of acid damage with no splash damage. For every three caster levels you possess, the acid, unless neutralized, lasts for another round (to a maximum of 6 additional rounds at 18th level), dealing another 2d4 points of damage in each round.', 'rhubarb leaf and an adder’s stomach', 'a dart', false, false),
  ('acid_fog', 'Acid Fog', 'conjuration', 'creation', 'acid', 6, 'arcane', 'magus 6, sorcerer/wizard 6, unchained summoner 6; Elemental School earth 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'fog spreads in 20-ft. radius, 20 ft. high', '1 round/level', 'none', 'no', 'Acid fog creates a billowing mass of misty vapors like the solid fog spell. In addition to slowing down creatures and obscuring sight, this spell’s vapors are highly acidic. Each round on your turn, starting when you cast the spell, the fog deals 2d6 points of acid damage to each creature and object within it.', 'powdered peas and an animal hoof', NULL, false, false),
  ('acid_maw', 'Acid Maw', 'transmutation', NULL, 'acid', 1, 'divine', 'druid 1, ranger 1', '1 standard action', 'close (25 ft. + 2 ft./level)', 'your animal companion', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes', 'Your animal companion’s bite attack deals an additional 1d4 points of acid damage, and the acid deals another 1d4 points of acid damage to the target on the next round. The acid continues to deal damage for 1 additional round per 4 caster levels (to a maximum of 6 total rounds at caster level 20th). This ongoing acid damage doesn’t stack from multiple attacks, but the duration resets if a newer bite would cause the ongoing damage to last longer than the duration remaining from a previous one.', NULL, NULL, true, false),
  ('acid_pit', 'Acid Pit', 'conjuration  acid', NULL, 'creation', 4, 'arcane', 'sorcerer/wizard 4, summoner/unchained summoner 4; Elemental School earth 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '10-ft.-by-10-ft. hole, 10 ft. deep/2 levels', '1 round + 1 round/level', 'Reflex negates; see text', 'no', 'This spell functions as create pit, except that it places a 5-foot deep pool of acid at the bottom of the pit. The pit has a maximum depth of 100 feet. Creatures who fall into the pit take falling damage as normal (the acid counts as a yielding surface), plus 2d6 points of acid damage per round spent in contact with the acid. In addition, exposed items carried by a creature in the pit may be harmed. Refer to Table: Items Affected by Magical Attacks (also copied here for convenience).', 'drop of acid', 'Fine shovel worth 10 gp', false, true),
  ('acid_splash', 'Acid Splash', 'conjuration', 'creation', 'acid', 0, 'divine', 'inquisitor 0, magus 0, sorcerer/wizard 0, summoner/unchained summoner 0; Elemental School earth 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one missile of acid', 'instantaneous', 'none', 'no', 'You fire a small orb of acid at the target. You must succeed on a ranged touch attack to hit your target. The orb deals 1d3 points of acid damage. This acid disappears after 1 round.', NULL, NULL, false, false),
  ('acidic_spray', 'Acidic Spray', 'conjuration', 'creation', 'acid', 5, 'arcane', 'magus 5, sorcerer/wizard 5', '1 standard action', '60 ft.', NULL, NULL, '60-ft. line', 'instantaneous', 'Reflex partial (see text)', 'yes', 'A spray of acid erupts from your outstretched hand, dealing 1d6 points of acid damage per caster level (maximum 15d6) to each creature within its area (Reflex half). This acid continues to burn for 1 round, dealing 1d6 points of acid damage per two caster levels (maximum 7d6) to any creature that failed its saving throw against the spell (a second Reflex save on the creature’s turn negates this additional damage).', 'a vial of acid worth 10 gp', NULL, false, true),
  ('acute_senses', 'Acute Senses', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, bard 2, inquisitor 2, psychic 2, ranger 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes', 'The target gains a +10 enhancement bonus on Perception checks. The bonus increases to +20 at caster level 8th, and +30 (the maximum) at caster level 16th.', 'a glass lens', NULL, false, false),
  ('adhesive_blood', 'Adhesive Blood', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, bloodrager 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', 'Reflex negates (see text)', 'no', 'Your blood thickens to becomes a glue-like substance upon contact with air. A piercing or slashing weapon that deals hit point damage to you is stuck fast unless the wielder succeeds at a Reflex save. A creature can pry off a stuck weapon on its turn as a standard action with a successful Strength check against the spell’s DC. Strong alcohol or universal solvent dissolves the adhesive. The glue breaks down 5 rounds after you die, or when the duration ends. This glue has no effect while underwater or in environments that lack air.', NULL, NULL, false, false),
  ('adhesive_spittle', 'Adhesive Spittle', 'conjuration', 'creation', NULL, 1, 'arcane', 'alchemist 1, psychic 1,  sorcerer/wizard 1, witch 1', '1 standard action', '15 ft.', 'one creature', NULL, NULL, '1 round/level or until discharged (see text)', 'Reflex partial', 'no', 'Once during this spell’s duration, you can spit a viscous liquid as a standard action. This liquid functions as a tanglefoot bag, except you do not have to make a successful attack roll to hit your target. The DCs to counteract this adhesive (to avoid being stuck to the floor, to fly, to break the adhesive, or to cast a spell) use the spell’s DC rather than a tanglefoot bag’s normal DCs. The adhesive persists for 2d4 rounds after you spit it.', NULL, NULL, false, false),
  ('adjustable_disguise', 'Adjustable Disguise', 'illusion', 'glamer', NULL, 3, 'divine', 'alchemist 3, antipaladin 3, bard 3, inquisitor 3, mesmerist 3, occultist 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'This spell functions as disguise self, except as a swift action you can alter the disguise (within the limitations of disguise self). For example, you could make yourself look like a young human city guard, then an old elven wizard of the opposite gender, then a halfling thief, and so on. You can change the disguise a number of times equal to your caster level.', NULL, NULL, false, false),
  ('adjustable_polymorph', 'Adjustable Polymorph', 'transmutation', 'polymorph', NULL, 4, 'divine', 'alchemist 4, bard 4, magus 4, shaman 4, sorcerer/wizard 4, summoner/unchained summoner 4, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'This spell functions as alter self, except you can as a swift action alter the disguise (within the limitations of alter self). For example, you could transform yourself into a halfling, then a lizardfolk, then an elf, and so on. You can change your form a number of times equal to your caster level.', 'a small piece of doppelganger flesh', NULL, false, false),
  ('admonishing_ray_3_5e', 'Admonishing Ray (3.5E)', 'evocation', NULL, 'force', 2, 'divine', 'cleric/oracle 2, sorcerer/wizard 2', '1 standard action', 'close (25 f. + 5 f./2 levels)', NULL, NULL, 'one or more rays', 'instantaneous', 'none', 'yes', 'You blast your enemies with rays of nonlethal force. You may fire one ray, plus one additional ray for every four levels you possess beyond 3rd (to a maximum of three rays at 11th level). Each ray requires a ranged touch attack to hit and deals 4d6 points of nonlethal damage. This is a force effect. The rays may be fired at the same or different targets, but all rays must be fired simultaneously and aimed at targets within 30 feet of each other.', NULL, NULL, false, false),
  ('adoration', 'Adoration', 'enchantment', NULL, NULL, 1, 'arcane', 'bard 1, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes', 'The target of this spell is the subject of adoration by those whom it tries to affect with Diplomacy or during performance combat. If the target is out of combat, it receives a +2 morale bonus on all Diplomacy checks it makes to influence creatures. If the creature is engaged in performance combat the target gains a +2 morale bonus on all performance combat checks.', NULL, NULL, false, false),
  ('adroit_retrieval', 'Adroit Retrieval', 'transmutation', NULL, NULL, 3, 'arcane', 'occultist 3, sorcerer/wizard 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'You instill the target with the ability to withdraw small items from her pockets or packs with supernatural swiftness. When the target retrieves an item stored on itself, it can retrieve the item either as a move action without provoking attacks of opportunity, or as a swift action that provokes attacks of opportunity. This effect functions only when the target attempts to retrieve a stored item that weighs less than 1 pound per caster level (maximum 15 pounds).', NULL, NULL, false, false),
  ('advanced_scurvy', 'Advanced Scurvy', 'necromancy', NULL, 'disease, evil', 1, 'divine', 'cleric 1, druid 1', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous', 'Fort negates', 'yes', 'The subject contracts an advanced form of scurvy. He becomes constantly fatigued, suffers from bone pain (–1 penalty on Strength- and Dexterity-based checks), wounds easily (add +1 point of damage to any bleed effects affecting the target), experiences loose teeth, and is slow to heal (natural healing occurs at half the normal rate). Scurvy can be treated magically or can be overcome with proper nutrition; eating the right foods ends the fatigue and bone pain within 1–2 days and provides a full cure 2d6 days after that.---', NULL, NULL, false, false),
  ('aerial_tracks', 'Aerial Tracks', 'divination', NULL, 'air', 3, 'divine', 'druid 4, inquisitor 4, ranger 3, shaman 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'circle centered on you, with a radius of 100 feet + 10 feet per level', NULL, '1 hour/level', 'none', 'no', 'You cause the air in the area to ripple where creatures have flown through it up to 1 day ago per caster level. These aerial ripples are tinged by glowing wisps, providing enough illumination to follow the tracks without penalties due to poor lighting. The area moves with you, allowing you to follow the tracks through the air over long distances provided you can fly or follow the route along the ground within range to read the aerial tracks. Other creatures can also follow the trail as long as they move with you. The base DC of Survival checks to track creatures through the air with this spell is the same as tracking creatures across soft ground.', NULL, NULL, false, false),
  ('age_resistance', 'Age Resistance', 'transmutation', NULL, NULL, 4, 'divine', 'alchemist 4, druid 6, sorcerer/wizard 6, witch 6', '1 standard action', 'personal', 'you', NULL, NULL, '24 hours', NULL, NULL, 'You ignore the physical detriments of being middle-aged. This spell does not cause you to look younger, nor does it prevent you from dying of old age, but as long as the spell is in effect, you ignore the –1 penalties to Strength, Dexterity, and Constitution that accrue once you become middle-aged. You retain the age-related bonuses to Intelligence, Wisdom, and Charisma while under the effects of this spell. Additional penalties that you accrue upon becoming old or venerable apply in full.', NULL, NULL, false, false),
  ('aggravate_affliction', 'Aggravate Affliction', 'necromancy', NULL, NULL, 3, 'divine', 'cleric 3, druid 3, sorcerer/wizard 4, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'see text', 'yes', 'All recurring afflictions (those with a frequency, including curses, diseases, and poison) possessed by the targeted creature immediately trigger, requiring an immediate saving throw (as described in the affliction) to avoid suffering their effects. A successful saving throw does not count toward ending the affliction, and this extra save does not change the timing of the next save against the affliction. Afflictions without a frequency are unaffected by this spell.', NULL, NULL, false, false),
  ('aggressive_thundercloud', 'Aggressive Thundercloud', 'evocation', NULL, 'electricity', 2, 'divine', 'druid 2, magus 2, sorcerer/wizard 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '5-ft.-diameter sphere', '1 round/level', 'Reflex negates', 'yes', 'A crackling, spherical storm cloud flies in whichever direction you point and deals electricity damage to those it strikes. It has a fly speed of 20 feet with perfect maneuverability. If it enters a space that contains a creature, the storm stops moving for the round and deals 3d6 points of electricity damage to that creature, though a successful Reflex save negates that damage. It provides concealment (20% miss chance) to anything within it, and its flickering light illuminates the same area a candle would.', 'a piece of a tree struck by lightning', NULL, true, false),
  ('agonize', 'Agonize', 'evocation', NULL, 'evil, pain', 3, 'divine', 'cleric/oracle 3, sorcerer/wizard 4, summoner 3, unchained summoner 4; Subdomain kyton (evil, law) 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one conjured outsider or elemental (see text)', NULL, NULL, '1 round', 'Fortitude negates', 'yes', 'You afflict a creature you have conjured via planar ally (or a similar spell) with bolts of vicious energy. These foul energies inflict terrible pain upon the conjured creature, torturing it to make it more pliant to your will. The targeted creature must make a Fortitude save or take a -1 penalty for every 2 levels you possess (maximum -10) on all saves and checks made against you for the next hour. In addition, creatures that demand payment for their services reduce the payment by 20% for every 4 levels you possess (maximum 60% reduction). However, beings tortured by this spell quickly come to resent you, making them more likely to try to pervert your orders to malicious ends or try to seek retribution after their release. This spell has no effect on creatures that are immune to nonlethal damage.', NULL, NULL, false, false),
  ('agonizing_rebuke', 'Agonizing Rebuke', 'illusion )', 'phantasm', 'emotion, mind-affecting, pain', 2, 'divine', 'antipaladin 2, cleric 3, inquisitor 3, mesmerist 3, psychic 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 level)', 'one living creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'With a word and a gesture, you instill such apprehension about attacking you in your target that doing so causes it mental distress and pain. Each time the target makes an attack against you, targets you with a harmful spell, or otherwise takes an action that would harm you, it takes 2d6 points of nonlethal damage.', NULL, NULL, false, false),
  ('aid', 'Aid', 'enchantment', 'compulsion', 'mind-affecting', 2, 'divine', 'alchemist 2, cleric/oracle 2, inquisitor 2, shaman 2; Domain luck 2; Subdomain tactics 2', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 min./level', 'none', 'yes (harmless)', 'Aid grants the target a +1 morale bonus on attack rolls and saves against fear effects, plus temporary hit points equal to 1d8 + caster level (to a maximum of 1d8+10 temporary hit points at caster level 10th).', NULL, NULL, true, false),
  ('air_breathing', 'Air Breathing', 'transmutation', NULL, NULL, 3, 'divine', 'alchemist 3, bloodrager 3, cleric 3, druid 3, magus 3, psychic 3, shaman 3, sorcerer/wizard 3, summoner 3', '1 standard action', 'touch', 'living aquatic creatures touched', NULL, NULL, '2 hours/level; see text', 'Will negates (harmless)', 'yes (harmless)', 'The transmuted creatures can breathe air freely.', 'flower or piece of grass', NULL, true, false),
  ('air_bubble', 'Air Bubble', 'conjuration', 'creation', NULL, 1, 'divine', 'cleric 1, druid 1, psychic 1, ranger 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one creature or one object no larger than a Large two-handed weapon', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'Air bubble creates a small pocket of breathable air that surrounds the touched creature’s head or the touched object. The air bubble allows the creature touched to breathe underwater or in similar airless environments, or protects the object touched from water damage. A firearm within an air bubble can be loaded—assuming the black powder comes from a powder horn, a cartridge, or some other airtight protective device—and fired. When shooting such a firearm underwater, the shot still takes the standard –2 penalty on attack rolls for every 5 feet of water the bullet passes through, in addition to normal penalties due to range. If a firearm within the air bubble explodes, the explosion occurs normally.', 'a small bladder filled with air', NULL, true, false),
  ('air_geyser', 'Air Geyser', 'evocation', NULL, 'air', 3, 'divine', 'bloodrager 3, druid 3, magus 3, shaman 4, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature or object up to Large size', NULL, NULL, 'instantaneous', 'Reflex partial (see text)', 'yes', 'You create a powerful blast of air capable of flinging an opponent upward. If the target fails its Reflex save, the force of the air deals 2d6 points of bludgeoning damage and hurls the target upward a number of feet equal to 5 × your caster level. If a solid object (such as a ceiling) is encountered, the target strikes the object in the same manner as it would during a normal fall. After this blast of air ceases, the target falls down (unless it was flying), taking falling damage as normal. A successful save means the target takes half damage from the air blast but is not moved by it.', NULL, NULL, false, false),
  ('air_of_authority', 'Air of Authority', 'illusion', 'glamer', NULL, 3, 'arcane', 'bard 3, medium 3, mesmerist 3, psychic 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'You gain an unmistakable air of authority, which clouds creatures’ minds and causes them to believe that you are their direct superior. Each creature with whom you attempt to leverage your newfound authority receives a Will save to disbelieve the illusion. Otherwise, it treats you as it would its direct superior. Creatures with different direct superiors see you in different ways, which can potentially lead to conflicts that allow additional saving throws (for instance, if a cook sees you as the head chef, he might be quite perplexed to see the vizier treating you as if you were the king).', NULL, NULL, false, false),
  ('air_step', 'Air Step', 'transmutation', NULL, 'air', 2, 'divine', 'alchemist 2, bard 2, cleric 2, druid 2, ranger 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'This spell functions as air walk, except you can rise no higher than 1 foot off the ground, you cannot pass over liquid, and the air you walk on is less stable than solid ground. When walking on air, you ignore difficult terrain that is less than 1 foot high, you do not trigger effects based on weight (such as a pressure plate), and any creature trying to track you through areas you crossed with this spell takes a –10 penalty on its Perception or Survival check to do so. However, because of the instability of the air you walk on, your speed is reduced by 10 feet (to a minimum of 5 feet) and you take a –4 penalty on Acrobatics, Climb, and Ride checks.', 'a goose feather', NULL, false, false),
  ('air_walk', 'Air Walk', 'transmutation', NULL, 'air', 4, 'divine', 'alchemist 4, cleric/oracle 4, druid 4; Domain air 4', '1 standard action', 'touch', 'creature (Gargantuan or smaller) touched', NULL, NULL, '10 min./level', 'none', 'yes (harmless)', 'The subject can tread on air as if walking on solid ground. Moving upward is similar to walking up a hill. The maximum upward or downward angle possible is 45 degrees, at a rate equal to half the air walker’s normal speed.', NULL, NULL, true, false),
  ('akashic_communion', 'Akashic Communion', 'divination', NULL, NULL, 3, 'divine', 'bard 3, medium 3, mesmerist 4, occultist 3, psychic 3, shaman 3, sorcerer/wizard 4, spiritualist 4, witch 3', '10 minutes', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'You attempt to obtain a glimpse of some specific event from the Akashic Record, the extraplanar repository of all experiences that have ever occurred. This allows you to attempt one Knowledge skill check of your choice per 3 caster levels you have, each with a +10 insight bonus. You are treated as trained in any Knowledge skills used for these checks, and can use this spell to reroll a Knowledge skill check you have already failed. The GM rolls these Knowledge checks in secret, as the Akashic Record is incredibly remote, and impressions gleaned from the distant repository are sometimes skewed when received. On a natural 1, the resulting answer is wildly inaccurate.', 'a square of reflective silver worth 100 gp', NULL, true, true),
  ('akashic_form', 'Akashic Form', 'necromancy', NULL, NULL, 9, 'arcane', 'psychic 9', '1 hour', 'personal', 'you', NULL, NULL, '24 hours', 'no', 'no', 'You create a perfect record of your physical body in the Akashic Record at the time the spell is cast. This record includes your current hit point total, physical ability scores (Strength, Dexterity, and Constitution), and any conditional modifiers or conditions such as ability damage to physical ability scores, disease, negative levels, and poison. If at any point within the duration of the spell you are reduced to fewer than 0 hit points or are slain by a death effect that is not mind-affecting, you can immediately let your current physical body die and assume the record of your physical body on your next turn.', NULL, NULL, false, false),
  ('alacrity', 'Alacrity', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, bard 2, magus 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'This spell’s energy quickens your steps, allowing fancy footwork.', 'ginger root shavings', NULL, false, false),
  ('alarm', 'Alarm', 'abjuration', NULL, NULL, 1, 'divine', 'bard 1, inquisitor 1, ranger 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1; Subdomain ambush 1, home 1; Bloodline destined 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '20-ft.-radius emanation centered on a point in space', NULL, '2 hours/level (D)', 'none', 'no', 'Alarm creates a subtle ward on an area you select. Once the spell effect is in place, it thereafter sounds a mental or audible alarm each time a creature of Tiny or larger size enters the warded area or touches it. A creature that speaks the password (determined by you at the time of casting) does not set off the alarm. You decide at the time of casting whether the alarm will be mental or audible in nature.', NULL, NULL, true, false),
  ('alchemical_allocation', 'Alchemical Allocation', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 round', NULL, NULL, 'This extract causes a pale aura to emanate from your mouth.', NULL, NULL, false, false),
  ('alchemical_tinkering', 'Alchemical Tinkering', 'transmutation', NULL, NULL, 1, 'divine', 'cleric 2, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'firearm or alchemical item touched', NULL, NULL, '1 minute/level', 'Fort negates (object)', 'yes', 'You transform one alchemical item or firearm into another alchemical item or firearm of the same or lesser cost. Magic Items are unaffected by this spell. At the end of the spell’s duration, alchemical items used while transformed are destroyed and do not return to a usable state and firearms transformed revert back to their original type.', NULL, NULL, false, false),
  ('align_weapon', 'Align Weapon', 'transmutation', NULL, 'see text', 2, 'divine', 'cleric/oracle 2, inquisitor 2; Domain chaos 2, evil 2, good 2, law 2; Subdomain demodand (chaos, evil) 2', '1 standard action', 'touch', 'weapon touched or 50 projectiles (all of which must be together at the time of casting)', NULL, NULL, '1 min./level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'Align weapon makes a weapon chaotic, evil, good, or lawful, as you choose. A weapon that is aligned can bypass the damage reduction of certain creatures. This spell has no effect on a weapon that already has an alignment.', NULL, NULL, true, false),
  ('allegro', 'Allegro', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D) or until discharged', NULL, NULL, 'This spell allows you to act more swiftly while maintaining a bardic performance. You must already be maintaining a bardic performance before you can cast allegro. You gain the benefits of the spell haste for as long as you maintain that bardic performance. If you cease maintaining the bardic performance or it is interrupted, this spell’s duration ends. As an immediate action while you are maintaining a bardic performance, you can dismiss allegro to reroll a Reflex save or Dexterity-based skill check. You must choose to reroll before the result of the original roll is known. You must take the result of the reroll, even if it’s worse than the original roll. Allegro dispels and is dispelled by slow.', NULL, NULL, false, false),
  ('alleviate_addiction', 'Alleviate Addiction', 'conjuration', 'healing', NULL, 1, 'divine', 'alchemist 1, cleric 1, druid 1, paladin 1, ranger 1, shaman 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Fort negates; (harmless)', 'yes (harmless)', 'The subject ignores the effects of addictions. The subject can naturally recover from damage dealt by the drug if she is under the effects of this spell for the entire duration of her rest.', NULL, NULL, true, false),
  ('alleviate_corruption', 'Alleviate Corruption', 'abjuration', NULL, NULL, 6, 'divine', 'cleric 6, psychic 6, shaman 6, spiritualist 6, witch 6', '1 minute', 'touch', 'one creature other than yourself', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'You combat the rising corruption in another creature or advance the long-term process of exorcising it entirely. This spell has two purposes, and you choose which application to use at the time of casting.', 'rare herbs, incense, and jewels worth 500 gp/the target’s character level or HD', NULL, false, true),
  ('allfood', 'Allfood', 'transmutation', NULL, NULL, 2, 'divine', 'ranger 2', '1 standard action', 'touch', NULL, NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'You can transform one object, weighing up to 5 lbs. per caster level, into an edible substance that any living creature can chew, swallow, and safely digest. This allfood always has a bland taste and slightly gooey consistency when chewed regardless of its original nature.', 'a pinch of salt and pepper', NULL, false, false),
  ('allied_cloak', 'Allied Cloak', 'abjuration', NULL, NULL, 2, 'arcane', 'bard 3, bloodrager 3, magus 3, occultist 2, sorcerer/wizard 3, summoner 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'none', 'no', 'You cause a cloak, shawl, poncho, or other outer garment you are wearing to animate to aid and defend you. The cloak provides a +2 shield bonus to your AC. In addition, once each round during your turn, you can take a free action to direct your cloak to use the aid another action to assist your skill check, attack roll, or AC. The cloak has an attack bonus or a total skill bonus equal to your caster level plus your key spellcasting ability score modifier (Charisma for bards, Intelligence for wizards, and so on). If another creature dons the cloak during the duration, the cloak provides its protection and aid to the wearer, but it still uses the same bonus on the aid another actions as if you were the wearer. The cloak cannot take any other type of action.', NULL, 'cloak or outer garment', false, false),
  ('alluring_light', 'Alluring Light', 'enchantment', 'compulsion', NULL, 1, 'arcane', 'bard 1, witch 1', '1 standard action', '30 ft.', NULL, '30-ft.-radius emanation centered on you', NULL, 'instantaneous', 'Will negates (see text)', 'yes', 'You glow with a soft radiance that calls out to all who see it. Each enemy that fails its save is drawn to you and must use its move action to approach you at the beginning of each of its turns for 1 round per caster level. An affected target must move toward you in the most direct path it can, though it can step around obstacles or other creatures. This spell can’t force a creature to walk into an area that might obviously harm or kill it (such as into a pit, over a patch of floor studded with caltrops, or through a wall of fire). An affected creature that loses sight of you is not compelled to move toward you, although if it later regains vision of you while still affected by this spell, it must again move toward you. Any hostile action against an affected creature (such an attack of opportunity due to its movement) cancels the spell’s effect against that creature. Your initial flash of light also increases the light level within the spell’s area by one step, up to normal light (darkness becomes dim light, and dim light becomes normal light) for 1 round per caster level.', NULL, NULL, false, false),
  ('alluring_spores', 'Alluring Spores', 'conjuration', 'creation', NULL, 2, 'divine', 'druid 2, hunter 2, shaman 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius spread', NULL, '1 minute/level', 'Fort negates', 'yes', 'This spell creates a burst of spores that weaken the mind.', 'a clump of pollen', NULL, true, false),
  ('ally_across_time', 'Ally Across Time', 'conjuration', 'summoning', NULL, 1, 'divine', 'arcanist 2, bard 2, cleric/oracle 2, hunter 1, inquisitor 2, medium 1, psychic 2, ranger 1, skald 2, sorcerer/wizard 2, warpriest 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one 5-ft. cube of temporal possibility/2 levels', '1 round/level', 'none', 'no', 'You create one or more 5-foot cubes of temporal possibility where your timeline overlaps with those of your parallel existences. As a free action, you can summon a duplicate of yourself (not including any animal companions, familiars, intelligent items, or other creatures) from an alternate timeline in one of the cubes you can see, which lasts until the end of your turn. This duplicate has your statistics (though its hit points equal your caster level), threatens all squares adjacent to it, and has any teamwork feats you have. Although the duplicate appears with all of the equipment you currently carry, it cannot use any of its equipment and all its equipment disappears when the duplicate does. This duplicate cannot voluntarily move from the space in which it’s summoned. During its brief existence, a duplicate can use the aid another action once to assist you, but it cannot take any other type of action. Once a duplicate disappears, the cube of temporal possibility it occupied dissipates.', NULL, NULL, false, false),
  ('alpha_instinct', 'Alpha Instinct', 'enchantment', 'charm', 'mind-affecting', 2, 'divine', 'bard 3, druid 2, medium 2, mesmerist 3, ranger 2, shaman 2', '10 minutes', 'personal', 'you', NULL, NULL, '1 hour/level (D)', NULL, NULL, 'Animals perceive you as a social superior. the starting attitude of animals you interact with improves by one step, and you gain a +2 morale bonus on Handle Animal checks. Helpful animals provide simple assistance (such as using the aid another action on skill checks they understand) as long as the spell lasts, but they flee from attacks and do not support you in combat. At one point during the spell’s duration, you can issue a nonverbal command to helpful animals within 60 feet to forage for you; the animal or animals immediately head out into the wilderness to do just that. After 1 hour, the animals return to the location where you issued the command to make you an offering of edible food sufficient for one meal for you and a number of others equal to your caster level.', 'a bit of musk from an alpha wolf or another socially dominant animal', NULL, false, false),
  ('alter_musical_instrument', 'Alter Musical Instrument', 'illusion', 'figment', NULL, 1, 'arcane', 'bard 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one musical instrument', NULL, NULL, '1 hour/level (D)', 'Fort negates (object)', 'yes (object)', 'You alter an instrument so it sounds like a different kind of instrument you are familiar with. The change could be minor (such as making a lute sound like a guitar) or major (making a keyboard sound like drums). All other aspects of the instrument—such as volume, pitch, and how it is played—are unchanged. For example, a piccolo made to sound like an organ is no louder than a normal piccolo, can produce only high notes in the piccolo range, and is a wind instrument.', NULL, 'an instrument', false, false),
  ('alter_river', 'Alter River', 'transmutation', NULL, 'water', 4, 'divine', 'cleric 4, druid 4, sorcerer/ wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'area of river up to 5 ft. wide/2 levels and 10 ft. long/level', NULL, NULL, '1 minute/level (D)', 'none', 'no', 'You alter the flow of water in a natural freshwater channel such as a river, stream, or waterfall. The first version of this spell alters the speed of a river’s flow. The second diverts the course of the targeted river.', 'silt from a dry riverbed', NULL, false, false),
  ('alter_self', 'Alter Self', 'transmutation', 'polymorph', NULL, 2, 'divine', 'alchemist 2, bard 2, magus 2, psychic 2, shaman 2, sorcerer/wizard 2, summoner/unchained summoner 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', NULL, NULL, 'When you cast this spell, you can assume the form of any Small or Medium creature of the humanoid type. If the form you assume has any of the following abilities, you gain the listed ability: darkvision 60 feet, low-light vision, scent, and swim 30 feet.', 'a piece of the creature whose form you plan to assume', NULL, false, false),
  ('alter_summoned_monster', 'Alter Summoned Monster', 'conjuration', 'summoning', NULL, 2, 'divine', 'antipaladin 2, bard 2, cleric 2, druid 2, ranger 2, sorcerer/wizard 2, summoner 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./ 2 levels)', 'one summoned creature', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You swap a creature summoned by a conjuration (summoning) spell for a creature you could summon with a summon monster or summon nature’s ally spell. The new creature must be an option from a spell of the same level or lower as the spell that summoned the target. The new creature cannot be summoned into an environment that cannot support it. The target can attempt a Will saving throw to negate this effect, but if the target is under your control, it receives no saving throw. Alter summoned monster does not alter the duration of the spell that summoned the target, nor does it affect any additional creatures summoned by the same spell as the target. The new creature has the same conditions and amount of damage as the target creature, and remains affected by all curses, diseases, poisons, and penalties that affected the target, but no other spells or effects carry over. Alter summoned monster is a spell of the same alignment type or types as the creature for which you exchange the target. An eidolon can’t be targeted by this spell.', NULL, NULL, false, false),
  ('alter_winds', 'Alter Winds', 'transmutation', NULL, 'air', 1, 'divine', 'druid 1, sorcerer/wizard 1; Elemental School air 1, wood 1; Mystery wind 1', '1 minute', 'touch', NULL, NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'You subtly enhance or diminish the effects of natural winds within the spell’s area, which is an immobile emanation around a point touched by you as the spell is cast. Within the area, natural (but not magical) wind effects are either increased or decreased by one step in intensity. The maximum wind force you can affect with this spell is based on your caster level, as shown on the table below. Alter winds has no effect on magical wind effects.', NULL, NULL, false, false),
  ('amnesia', 'Amnesia', 'enchantment', 'compulsion', 'mind-affecting', 3, 'arcane', 'arcanist 4, bard 4, medium 3, mesmerist 4, psychic 4, skald 4, sorcerer/wizard 4', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You cause the target to lose most of its memories; its skills, its past, and even its name become mysteries to it. While the target can build new memories, it has trouble accessing those gained before falling victim to the spell. The target can still speak and read any languages it knows and perform basic tasks, but it loses all class abilities, feats, and skill ranks gained before being affected by amnesia. It retains its base attack bonus, saving throws bonuses, Combat Maneuver Bonus, Combat Maneuver Defense, total experience points, Hit Dice, and hit points. If the target gains a character level while suffering from amnesia, it can use any abilities gained by that class level normally. If the class level it gained was from a class in which it already has levels, it gains the abilities of a 1st-level character of that class, even though it is technically of a higher level in that class.', NULL, NULL, false, false),
  ('amplify_elixir', 'Amplify Elixir', 'transmutation', NULL, NULL, 3, 'arcane', 'alchemist 3', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', NULL, NULL, 'This extract greatly enhances the effects of any potion or elixir you consume. For the duration of this extract, any potion or elixir you consume is treated as if it were empowered. Increase all variable numeric effects of the potion or elixir by half. If the potion or elixir does not have any variable numeric effects, it is instead treated as if it were extended (double the duration of the potion or elixir). If the potion or elixir does not have any variable numeric effects, or has an instantaneous duration, amplify elixir has no effect. Amplify elixir affects oils that target you, but it has no effect on oils that target your equipment.', NULL, NULL, false, false),
  ('amplify_stench', 'Amplify Stench', 'transmutation', NULL, NULL, 2, 'divine', 'cleric 2, druid 2, oracle 2, psychic 2, shaman 2, sorcerer/wizard 2', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'You amplify your natural stench special ability—its save DC increases by 2, and creatures that fail their saving throws against your stench become nauseated rather than sickened. If your stench ability normally causes a creature to become nauseated (such as with the foul stench ability), the radius of your stench doubles instead. This spell has no effect if you don’t possess the stench special ability.---', NULL, NULL, false, false),
  ('analyze_aura', 'Analyze Aura', 'divination', NULL, NULL, 2, 'arcane', 'medium 2, mesmerist 3, occultist 2, psychic 3, spiritualist 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature or object', NULL, NULL, 'concentration, up to 1 round/level', 'none', 'no', 'You peer into the aura of one target creature or object, gaining valuable information about its condition and nature. Each round, choose one of the target’s four auras. This spell functions similarly to the read aura occult skill unlock, but doesn’t require checks and returns results on all the target’s auras in an instant.', NULL, NULL, false, false),
  ('analyze_dweomer', 'Analyze Dweomer', 'divination', NULL, NULL, 6, 'arcane', 'alchemist 6, bard 6, sorcerer/wizard 6, witch 6; Domain [subdomain] Magic [arcane] 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level (D)', 'none or Will negates, see text', 'no', 'You can observe magical auras. Each round, you may examine a single creature or object that you can see as a free action. In the case of a magic item, you learn its functions (including any curse effects), how to activate its functions (if appropriate), and how many charges are left (if it uses charges). In the case of an object or creature with active spells cast upon it, you learn each spell, its effect, and its caster level.', NULL, 'a ruby and gold lens worth 1,500 gp', false, true),
  ('ancestral_communion', 'Ancestral Communion', 'divination', NULL, NULL, 2, 'divine', 'bard 2, cleric/oracle 2', '1 minute', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You contact the spirits of your ancestors and use their great wisdom to bolster your own knowledge. Consulting with the spirits is a full-round action. If you consult with the spirits before making a Knowledge check, you gain a +4 insight bonus on the check. If you have already failed at a Knowledge check, you may consult with your ancestors and make another attempt. The insight bonus on these checks increases to +6 at caster level 7th and +8 at caster level 11th. You may consult with the spirits for this purpose as often as you like while the spell remains in effect. Only you can hear the spirits speak to you.', NULL, NULL, true, false),
  ('ancestral_gift', 'Ancestral Gift', 'conjuration', 'summoning', NULL, 4, 'divine', 'bard 4, cleric/oracle 4', '1 standard action', 'personal', NULL, NULL, 'magical weapon', '10 minutes/level', NULL, NULL, 'A ghostly manifestation of one of your ancestors appears before you bearing a weapon of your choice in its hands. The weapon may be any simple, martial, or dwarven weapon. It has a +1 enhancement bonus and one weapon special ability (your choice) from Magic Weapons with a price equivalent to a +1 bonus (if the weapon is a double weapon, the ability and the enhancement bonus only apply to one end, or the weapon can have a +1 enhancement bonus on both ends but no other magical abilities).', NULL, NULL, true, false),
  ('ancestral_memory', 'Ancestral Memory', 'divination', NULL, NULL, 4, 'divine', 'alchemist 5, cleric/oracle 5, druid 4, shaman 5', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', NULL, NULL, 'When you cast this spell, you open your mind to the vast experiences of your ancestors in the hope of learning something pertinent about your current situation. The chance of successfully finding an ancestral memory that is pertinent is equal to 70% + your caster level. Failure indicates you merely gain a +5 insight bonus on all Intelligence-based skill checks for the duration of the spell.', NULL, NULL, false, false),
  ('ancestral_regression', 'Ancestral Regression', 'transmutation', 'polymorph', NULL, 2, 'divine', 'alchemist 2, antipaladin 3, cleric 2, psychic 2, sorcerer/wizard 3, witch 2', '1 standard action', 'touch', 'willing drow touched', NULL, NULL, '24 hours (D)', 'Will negates (harmless)', 'yes (harmless)', 'The target drow transforms into a surface elf. The drow loses her darkvision and light-blindness racial traits and gains the low-light vision racial trait in their place. The alignment and personality of the drow are not affected by the transformation, but the spell conceals her alignment as an undetectable alignment spell. The spell grants the target a +10 bonus on Disguise checks to pass as an elf, though she appears to be an elven analog of herself and can be recognized as such by other drow who know her.', NULL, NULL, false, false),
  ('anchored_step', 'Anchored Step', 'transmutation', NULL, NULL, 3, 'divine', 'alchemist 3, druid 3, psychic 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'Powerful tendrils grow out of the bottom of your feet or footwear, partially anchoring you to the ground and making it more difficult for others to move you against your will. These tendrils dig into any surface, but leave no trace of your passing. You gain a +10 bonus to your CMD against bull rush, overrun, pull, push, reposition, and trip combat maneuvers, as well as any other effect that would move you from your current position (such as being swallowed whole) or knock you prone. The tendrils slow your movement, however; your speed is reduced by 10 feet (to a minimum of 5 feet). This spell has no effect if you are moving without touching the ground (climbing, flying, swimming, and so on).', 'a bit of oak root', NULL, false, false),
  ('angelic_aspect', 'Angelic Aspect', 'transmutation', NULL, 'good', 2, 'divine', 'cleric 2, paladin 2, sorcerer/wizard 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', 'none', 'no', 'You take on an aspect of an angelic being, including some of its physical characteristics.', NULL, NULL, false, false),
  ('animal_ambassador', 'Animal Ambassador', 'enchantment', 'compulsion', 'mind-affecting', 3, 'divine', 'bard 4, druid 4, ranger 3, shaman 4', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', 'one Medium or smaller animal', NULL, NULL, '1 day/level or until message is delivered', 'none (see text)', 'no', 'You compel a single animal to travel to a spot you designate and deliver a message to a creature you identify. This spell is similar to animal messenger, but can affect larger animals. In addition, the target animal is temporarily awakened to sentience (as the awaken spell) for the duration of this spell, and it can use its increased mental acuity to come up with creative solutions to overcome obstacles to delivering its message. The awakened target animal speaks any one language you know. In addition, you can imbue the animal with up to 5 ranks in any of the following skills: Bluff, Diplomacy, Knowledge (local), Knowledge (nobility), Linguistics, or Sense Motive. It treats any of these skills that are class skills for you as class skills. The number of ranks you imbue in any of these skills can’t exceed the target animal’s Hit Dice nor the number of ranks you possess in that skill.', 'a morsel of food the animal likes', NULL, false, false),
  ('animal_aspect', 'Animal Aspect', 'transmutation', 'polymorph', NULL, 2, 'divine', 'alchemist 2, bloodrager 2, druid 2, magus 2, psychic 2, ranger 2, sorcerer/wizard 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', 'none', 'yes (harmless)', 'You gain some of the beneficial qualities of an animal. Your base form is largely unchanged and your size is unaltered, but some of your body parts are altered. Armor or gear you are wearing adjusts to your new shape for the duration of the spell. When you cast animal aspect, choose one of the following animals to gain the associated benefits. You can only have one animal aspect or greater animal aspect spell active on you at a time.', 'a part of the animal', NULL, true, false),
  ('animal_growth', 'Animal Growth', 'transmutation', NULL, NULL, 4, 'divine', 'druid 5, ranger 4, shaman 5, sorcerer/wizard 5; Domain scalykind 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one animal (Gargantuan or smaller)', NULL, NULL, '1 min./level', 'Fortitude negates', 'yes', 'The target animal grows to twice its normal size and eight times its normal weight. This alteration changes the animal’s size category to the next largest, grants it a +8 size bonus to Strength and a +4 size bonus to Constitution (and thus an extra 2 hit points per HD), and imposes a -2 size penalty to Dexterity. The creature’s existing natural armor bonus increases by 2. The size change also affects the animal’s modifier to AC, attack rolls, and its base damage. The animal’s space and reach change as appropriate to the new size, but its speed does not change. If insufficient room is available for the desired growth, the creature attains the maximum possible size and may make a Strength check (using its increased Strength) to burst any enclosures in the process. If it fails, it is constrained without harm by the materials enclosing it–the spell cannot be used to crush a creature by increasing its size.', NULL, NULL, false, false),
  ('animal_messenger', 'Animal Messenger', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'bard 2, druid 2, psychic 2, ranger 1, shaman 2', '1 minute', 'close (25 ft. + 5 ft./2 levels)', 'one tiny animal', NULL, NULL, '1 day/level', 'none; see text', 'yes', 'You compel a Tiny animal to go to a spot you designate. The most common use for this spell is to get an animal to carry a message to your allies. The animal cannot be one tamed or trained by someone else, including such creatures as familiars and animal companions.', 'a morsel of food the animal likes', NULL, false, false),
  ('animal_purpose_training', 'Animal Purpose Training', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'antipaladin 1, bard 2, druid 2, inquisitor 1, paladin 1, psychic 1, ranger 1, shaman 2, witch 1', '1 minute', 'close (25 ft. + 5 ft./2 levels)', 'one indifferent or friendly animal', NULL, NULL, '1 hour/level', 'none', 'yes', 'You instill the target animal with a general purpose (see the Handle Animal skill), which can be any purpose except combat training—fighting, guarding, heavy labor, hunting, performance, or riding. This purpose supersedes the animal’s previous trained purpose and any tricks it knows. When the spell ends, the animal reverts to its previous trained purpose and known tricks.', 'a swatch of black cloth', NULL, false, false),
  ('animal_shapes', 'Animal Shapes', 'transmutation', 'polymorph', NULL, 7, 'divine', 'druid 8, shaman 8; Domain animal 7, scalykind 8; Mystery nature 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 hour/level (D)', 'none, see text', 'yes (harmless)', 'As beast shape III, except you change the form of up to one willing creature per caster level into an animal of your choice; the spell has no effect on unwilling creatures. All creatures must take the same kind of animal form. Recipients remain in the animal form until the spell expires or until you dismiss it for all recipients. In addition, an individual subject may choose to resume its normal form as a full-round action; doing so ends the spell for that subject alone.', NULL, NULL, true, false),
  ('animal_trance', 'Animal Trance', 'enchantment', 'compulsion', 'mind-affecting, sonic', 2, 'divine', 'bard 2, druid 2, psychic 2; Domain scalykind 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'concentration', 'Will negates', 'yes', 'Your swaying motions and music (or singing, or chanting) compel animals and magical beasts to do nothing but watch you. Only a creature with an Intelligence score of 1 or 2 can be fascinated by this spell. Roll 2d6 to determine the total number of HD worth of creatures that you fascinate. The closest targets are selected first until no more targets within range can be affected.', NULL, NULL, false, false),
  ('animate_dead', 'Animate Dead', 'necromancy', NULL, 'evil', 3, 'divine', 'antipaladin 3, cleric/oracle 3, shaman 3, sorcerer/wizard 4; Domain death 3; Subdomain souls 3; Mystery bones 3', '1 standard action', 'touch', NULL, NULL, NULL, 'instantaneous', 'none', 'no', 'This spell turns corpses into undead skeletons or zombies that obey your spoken commands.', 'an onyx gem worth at least 25 gp per Hit Die of the undead', NULL, false, true),
  ('animate_objects', 'Animate Objects', 'transmutation', NULL, NULL, 6, 'divine', 'bard 6, cleric/oracle 6, witch 6; Domain chaos 6; Subdomain flotsam 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'none', 'no', 'You imbue inanimate objects with mobility and a semblance of life. Each such animated object then immediately attacks whomever or whatever you initially designate.', NULL, NULL, false, false),
  ('animate_plants', 'Animate Plants', 'transmutation', NULL, NULL, 7, 'divine', 'druid 7, shaman 7; Domain plant 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level or 1 hour/level; see text', 'none', 'no', 'You imbue inanimate plants with mobility and a semblance of life. Each animated plant then immediately attacks whomever or whatever you initially designate as though it were an animated object of the appropriate size category. You may animate one Large or smaller plant, or a number of larger plants as follows: a Huge plant counts as two Large or smaller plants, a Gargantuan plant as four, and a Colossal plant as eight. You can change the designated target or targets as a move action, as if directing an active spell.', NULL, NULL, false, false),
  ('animate_rope', 'Animate Rope', 'transmutation', NULL, NULL, 1, 'arcane', 'bard 1, psychic 1, sorcerer/wizard 1; Domain artifice 1; Elemental School wood 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one rope-like object, length up to 50 ft. + 5 ft./level; see text', NULL, NULL, '1 round/level', 'none', 'no', 'You can animate a nonliving rope-like object. The maximum length assumes a rope with a 1-inch diameter. Reduce the maximum length by 50% for every additional inch of thickness, and increase it by 50% for each reduction of the rope’s diameter by half.', NULL, NULL, false, false),
  ('animus_mine', 'Animus Mine', 'abjuration', NULL, 'mind-affecting', 2, 'arcane', 'mesmerist 2, psychic 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 hour/level or until discharged', 'Will negates (harmless)', 'no', 'You implant a mental mine within your psyche that triggers against anyone attempting to manipulate your thoughts.', NULL, NULL, false, false),
  ('anonymous_interaction', 'Anonymous Interaction', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'bard 2, psychic 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, 'permanent (see text)', 'Will negates', 'yes', 'You cause the targets to forget all but the most general information about you. If they saw you or interacted with you, they still remember your presence and your general shape (such as humanoid), as well as the gist of your interactions with them (such as “She was asking about the queen“), but they don’t remember specifically what you said, details of your appearance, or any identifying information about you. This spell targets any memories of you in the minute preceding its casting, but is otherwise permanent.', NULL, NULL, false, false),
  ('ant_haul', 'Ant Haul', 'transmutation', NULL, NULL, 1, 'divine', 'alchemist 1, cleric/oracle 1, druid 1, psychic 1, ranger 1, sorcerer/wizard 1, summoner/unchained summoner 1', '1 standard action', 'touch', NULL, NULL, NULL, '2 hours/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'The target’s carrying capacity triples. This does not affect the creature’s actual Strength in any way, merely the amount of material it can carry while benefiting from this spell. It also has no effect on encumbrance due to armor. If the creature wears armor it still takes the normal penalties for doing so regardless of how much weight the spell allows it to carry.', 'a small pulley', NULL, true, false),
  ('anthropomorphic_animal', 'Anthropomorphic Animal', 'transmutation', 'polymorph', NULL, 3, 'divine', 'druid 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'animal touched', NULL, NULL, '1 hour/level', 'Fortitude negates', 'yes', 'You transform the touched animal into a bipedal hybrid of its original form with a humanoid form, similar to how a lycanthrope’s hybrid form is a mix of a humanoid and animal form. The animal‘s size, type, and ability scores do not change. It loses its natural attacks except for bite (if it had one as an animal), all types of movement other than its land speed, and special attacks that rely on its natural attacks. One pair of its limbs is able to manipulate objects and weapons as well as human hands do; limbless animals like snakes temporarily grow a pair of arms. The creature’s Intelligence increases to 3, and it gains the ability to speak one language you know. It is not considered proficient in any manufactured weapons. It can attack with unarmed strikes, dealing unarmed strike damage for a creature of its size (unless it has a bite attack, which is a natural attack).', 'a humanoid thumb bone', NULL, false, false),
  ('anti_incorporeal_shell', 'Anti-Incorporeal Shell', 'abjuration', NULL, NULL, 4, 'divine', 'cleric 4, shaman 4, witch 4', '1 round', '10 ft.', NULL, '10-ft.-radius emanation centered on you', NULL, '1 minute/level (D)', 'none', 'yes', 'You bring into being a mobile, hemispherical energy field that incorporeal creatures cannot enter.', NULL, NULL, true, false),
  ('anti_summoning_shield', 'Anti-Summoning Shield', 'abjuration', NULL, NULL, 2, 'divine', 'bard 2, inquisitor 3, sorcerer/wizard 2, summoner 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '50-ft.-radius', NULL, '1 minute/level (D)', 'Will negates', 'yes', 'Within the area of effect, this spell impedes the use of spells of the summoning subschool and other effects that summon creatures.', NULL, NULL, false, false),
  ('anticipate_peril', 'Anticipate Peril', 'divination', NULL, NULL, 1, 'divine', 'alchemist 1, bard 1, psychic 1, ranger 1, sorcerer/ wizard 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level or until activated', 'Will negates', 'yes', 'A creature affected by anticipate peril gains a preternatural sense of danger. The first time during this spell’s duration that the target has to make an initiative check, the creature adds an insight bonus on that initiative check equal to the spell’s caster level (maximum +5). Once this bonus applies, the effects of the spell end.', NULL, NULL, false, false),
  ('anticipate_thoughts', 'Anticipate Thoughts', 'divination', NULL, 'mind-affecting', 2, 'divine', 'bard 2, inquisitor 2, magus 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will partial', 'yes', 'This spell taps into the target’s mind so you get an impression of the actions it will take. You gain a +2 insight bonus to AC against the target’s attacks. If the target fails its Will save, you also see how the target will react to your attacks, and the bonus applies on your attack rolls and damage rolls against the target. These bonuses apply only while the target is within range of the spell, though if it goes out of range, the bonuses return once it’s back in range. Whenever the target misses you with an attack, the spell’s bonuses increase by 1 until the spell ends (to a maximum of +5).', NULL, NULL, false, false),
  ('antilife_shell', 'Antilife Shell', 'abjuration', NULL, NULL, 6, 'divine', 'cleric/oracle 6, druid 6, shaman 6; Domain animal 6; Subdomain souls 6', '1 round', '10 ft.', NULL, '10-ft.-radius emanation, centered on you', NULL, '1 min./level (D)', 'none', 'yes', 'You bring into being a mobile, hemispherical energy field that prevents the entrance of most types of living creatures.', NULL, NULL, true, false),
  ('antimagic_field', 'Antimagic Field', 'abjuration', NULL, NULL, 6, 'divine', 'cleric/oracle 8, sorcerer/wizard 6; Domain magic 6, protection 6; Mystery dragon 6, spellscar 6', '1 standard action', '10 ft.', NULL, '10-ft.-radius emanation, centered on you', NULL, '10 min./level (D)', 'none', 'see text', 'An invisible barrier surrounds you and moves with you. The space within this barrier is impervious to most magical effects, including spells, spell-like abilities, and supernatural abilities. Likewise, it prevents the functioning of any magic items or spells within its confines.', 'pinch of powdered iron or iron filings', NULL, true, false),
  ('antipathy', 'Antipathy', 'enchantment', 'compulsion', 'emotion, mind-affecting', 6, 'divine', 'druid 9, sorcerer/wizard 8, summoner 6, witch 8', '1 hour', 'close (25 ft. + 5 ft./2 levels)', 'one location (up to a 10-ft. cube/level) or one object', NULL, NULL, '2 hours/level (D)', 'Will partial', 'yes', 'You cause an object or location to emanate magical vibrations that repel either a specific kind of intelligent creature or creatures of a particular alignment, as defined by you. The kind of creature to be affected must be named specifically. A creature subtype is not specific enough. Likewise, the specific alignment to be repelled must be named.', 'a lump of alum soaked in vinegar', NULL, true, false),
  ('antiplant_shell', 'Antiplant Shell', 'abjuration', NULL, NULL, 4, 'divine', 'druid 4', '1 standard action', '10 ft.', NULL, '10-ft.-radius emanation, centered on you', NULL, '1 min./level (D)', 'none', 'yes', 'The antiplant shell spell creates an invisible, mobile barrier that keeps all creatures within the shell protected from attacks by plant creatures or animated plants. As with many abjuration spells, forcing the barrier against creatures that the spell keeps at bay strains and collapses the field.', NULL, NULL, true, false),
  ('antitech_field', 'Antitech Field', 'abjuration', NULL, NULL, 6, 'divine', 'druid 6, sorcerer/wizard 7', '1 standard action', '10 ft.', '10-ft.-radius emanation centered on you', NULL, NULL, '1 minute/level (D)', 'Fortitude partial (see text)', 'yes', 'You bring into being a mobile, hemispherical energy field that prevents technological objects, signals, and creatures from entering.', 'pinch of rust', NULL, true, false),
  ('antithetical_constraint', 'Antithetical Constraint', 'enchantment', 'compulsion', 'mind-affecting', 4, 'arcane', 'bard 4, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You constrain the target such that the target automatically misses with all attacks made against creatures that are not of the opposite alignment of it. For example, a lawful evil target would automatically fail at all attacks except those made against chaotic good creatures, and a neutral good target would automatically fail at all attacks except those made against neutral evil creatures. For the purposes of antithetical constraint, creatures that are chaotic evil, chaotic good, lawful evil, or lawful good are all considered to have the opposite alignment of a target whose alignment is neutral with no other alignment components. This restriction doesn’t apply to effects that do not require attack rolls, such as magic missile.', NULL, NULL, false, false),
  ('antitoxin_touch', 'Antitoxin Touch', 'abjuration', NULL, NULL, 1, 'divine', 'alchemist 1, druid 1, ranger 1, shaman 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Fort negates (harmless)', 'yes (harmless)', 'The target’s skin secretes a small amount of venom-resistant oils for the spell’s duration. The target cannot accidentally poison itself while applying poison. Additionally, the target does not risk exposure to a creature’s poison when attempting to milk venom.', 'a small drop of antitoxin', NULL, false, false),
  ('anywhere_but_here', 'Anywhere But Here', 'conjuration', 'teleportation', NULL, 4, 'arcane', 'magus 4, psychic 4, sorcerer/wizard 4, summoner 4, witch 4', '1 standard action', 'touch', 'you and up to four willing creatures, none of whom can be on their home plane', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'no', 'This spell functions similarly to plane shift, but instead of transporting the targets to a destination near an intended location on a specific plane, anywhere but here transports affected creatures to a random plane. A creature can be affected by anywhere but here only if it is currently not on its home plane (although targets can, by chance, end up traveling to their home plane as a result of this spell). Subjects always appear in a location that is not inherently harmful, but the exact destination is otherwise random. The specific plane is determined by the table below; the location on the destination plane where the transported creatures arrive is completely subject to the GM’s whim.', NULL, NULL, false, false),
  ('apathy', 'Apathy', 'enchantment', 'compulsion', 'emotion, mind-affecting', 4, 'arcane', 'bard 4, mesmerist 4, psychic 5, sorcerer/ wizard 5, witch 5', '1 standard action', 'long (400 ft. + 40 ft./level)', 'one creature', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'You cause a creature to temporarily lose interest in a passion or pursuit, taking the heat off your trail to facilitate a getaway, the finalization of a scheme, or the elimination of incriminating evidence. When casting the spell, you designate a subject or activity about which the target becomes indifferent. While under the effects of apathy, the target takes a –5 penalty on all skill checks and ability checks to investigate, pursue, or otherwise advance its goals in relation to the designated subject. In most cases, however, the target does not attempt such checks if they can be avoided, as it simply has no interest in putting effort into the endeavor.', 'a shiny bead', NULL, false, false),
  ('ape_walk', 'Ape Walk', 'transmutation', NULL, NULL, 2, 'divine', 'druid 3, ranger 2, sorcerer/wizard 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes (harmless)', 'The subject can climb as well as an ape or monkey, gaining a climb speed of 30 feet and a +8 racial bonus on Climb skill checks. The affected creature must have her hands free to climb in this manner. In addition, as long as she has 10 feet of space in which to make a running start, the subject can make a long jump of up to 10 feet without making an Acrobatics check (an Acrobatics check is still required to jump longer distances).', 'an ape or monkey paw', NULL, false, false),
  ('aphasia', 'Aphasia', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1, mesmerist 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft.+ 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates (see text)', 'yes', 'You render the target unable to understand any language, including spoken language, written language, sign language, gestures attempting to mimic a crude language, or even truespeech and telepathy. The affected creature is unable to communicate, use command words, cast spells with verbal components, or use any other abilities that requires language.', NULL, NULL, false, false),
  ('apparent_master_3_5e', 'Apparent Master(3.5E)', 'enchantment', NULL, NULL, 4, 'arcane', 'bard 4, sorcerer/wizard 5', '1 standard action', 'Close (25 ft. +5 ft./2 levels)', 'One construct; see text', NULL, NULL, '1 hour/level', 'Will negates', 'Yes', 'This charm makes a construct regard you as its master. The spell only affects mindless constructs that are attuned to the commands of a master, such as animated objects, golems, retrievers, and shield guardians. All constructs with Intelligence scores, even those that explicitly follow the commands of their creator, such as an homunculus, are unaffected. If the construct is currently being threatened or attacked by you or your allies it receives a +5 bonus on its saving throw.', NULL, NULL, false, false),
  ('apparent_treachery', 'Apparent Treachery', 'enchantment', 'compulsion', 'mind-affecting', 3, 'divine', 'bard 3, inquisitor 3, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You shroud a number of creatures in an aura of suspicion and fill them with extreme paranoia regarding their allies. Affected targets believe their companions are behaving erratically, nervously, and seemingly with an eye towards betrayal.', NULL, NULL, false, false),
  ('appearance_of_life', 'Appearance of Life', 'illusion', 'glamer', 'evil', 2, 'divine', 'cleric/oracle 3, medium 2, mesmerist 3, psychic 3, sorcerer/wizard 3, spiritualist 3, witch 3', '1 round', 'long (400 ft. + 40 ft./caster level)', 'one or more undead creatures', NULL, NULL, '10 minutes/level (D)', 'Will disbelief or Will negates (see text)', 'no', 'The illusion makes undead creatures of Medium size or smaller appear as if they were living humanoid creatures. You can target a number of undead creatures whose total number of Hit Dice is no greater than twice your caster level. When you create the illusion, you choose the races, genders, and attire for the undead creatures. Additionally, the illusion makes the undead creatures’ movements appear lifelike (two shuffling zombies could be made to appear as two strolling lovers). The illusion doesn’t create smell, sound, texture, or temperature. Undead with Intelligence scores can attempt a saving throw to negate the effect of the spell, but mindless undead do not. Any creatures interacting with the illusion receive a saving throw to disbelieve the illusion.', 'one Tiny or larger living creature', NULL, false, false),
  ('apport_animal', 'Apport Animal', 'conjuration', 'teleportation', NULL, 3, 'divine', 'druid 3, medium 3, mesmerist 3, psychic 3, ranger 3, sorcerer/wizard 3, summoner 3, witch 3', NULL, NULL, 'one touched animal of Tiny or smaller size', NULL, NULL, NULL, 'Will negates', 'yes', 'This spell functions like apport object except the target is an animal. Only normal, non-magical creatures of the animal type can be teleported.', NULL, NULL, false, false),
  ('apport_object', 'Apport Object', 'conjuration', 'teleportation', NULL, 2, 'arcane', 'bard 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'one touched object of up to 1 lb. and 1 cu. ft.', NULL, NULL, 'instantaneous or 1 hour/level', 'Will negates (object)', 'yes (object)', 'This spell allows you to instantaneously transport a small nonliving object from one location to another. There are two ways to use the spell: sending allows you to immediately send an object held in your hands to a nearby location, while receiving permits you to cast the spell ahead of time on an object and summon it to your location at a later time.', NULL, NULL, false, false),
  ('aquatic_cavalry', 'Aquatic Cavalry', 'conjuration', 'summoning', NULL, 2, 'divine', 'antipaladin 2, druid 2, paladin 2, ranger 2, shaman 2, summoner 2', '1 round', 'medium (100 ft. + 10 ft./level) Effects 1 hippocampus plus 1 hippocampus/3 caster levels', NULL, NULL, NULL, '1 hour/level (D)', 'none', 'no', 'You summon a school of hippocampi (one plus one per 3 caster levels, to a maximum of six at 15th level) to serve as combat-trained mounts. the hippocampi avoid combat if possible but defend themselves if attacked. If any hippocampus attacks, the remaining duration of the spell changes from 1 hour per level to 1 round per level (so if a full 4 hours remained, the hippocampi last for only 4 more rounds).', NULL, NULL, true, false),
  ('aquatic_trail', 'Aquatic Trail', 'divination', NULL, 'water', 2, 'divine', 'druid 3, hunter 2, inquisitor 3, ranger 2, shaman 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'circle centered on you, with a radius of 100 feet + 10 feet per level', NULL, '1 hour/level', 'none', 'no', 'You use divination magic to enhance the underwater trails in the area around you, allowing you to track creatures through the water as if across soft ground as long as they passed through the area less than 1 week ago (this lets you notice trails that are much older than normal underwater trails). The spell’s area moves with you, so you can follow the trail through the water over long distances. Other creatures can also follow the trail as long as they move with you. Because of the plethora of sea creatures in the higher zones, it’s possible that the trail that most interests you will be covered by the trails of other aquatic creatures.', NULL, NULL, false, false),
  ('aqueous_orb', 'Aqueous Orb', 'conjuration', 'creation', 'water', 3, 'divine', 'bloodrager 3, druid 3, magus 3, sorcerer/wizard 3, summoner/unchained summoner 3; Bloodline aquatic 3; Elemental School water 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '10-ft.-diameter sphere', '1 round/level', 'Reflex negates', 'no', 'You create a rolling sphere of churning water that can engulf those it strikes. The aqueous orb can move up to 30 feet per round, rolling over barriers less than 10 feet tall. It automatically quenches any non-magical fires and functions as dispel magic against magical fires as long as those fires are size Large or less.', 'a drop of water and a glass bead', NULL, false, false),
  ('arbitrament', 'Arbitrament', 'evocation', NULL, 'sonic', 6, 'divine', 'cleric 7, inquisitor 6', '1 standard action', '40 ft.', 'non-neutral creatures in a 40-ft.-radius spread centered on you', NULL, NULL, 'instantaneous', 'Will partial, see text', 'yes', 'All chaotic evil, chaotic good, lawful evil, and lawful good creatures within the area of this spell suffer the following conditions, based on their Hit Dice.', NULL, NULL, false, false),
  ('arboreal_hammer', 'Arboreal Hammer', 'transmutation', NULL, NULL, 4, 'divine', 'druid 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one Huge or larger tree', NULL, NULL, '1 round/level (D)', 'none', 'no', 'This spell animates a tree’s branch and directs it against your foes. At caster level 10th or lower, you can target a Huge tree. At caster level 11th-15th, you can target a Gargantuan tree, and at caster level 16th or higher you can target a Colossal tree. The animated branch makes slam attacks with a Strength score equal to 10 + your caster level. The branch strikes once per round with an attack bonus equal to your caster level + the branch’s Strength modifier, adjusted by the appropriate size modifier (+2 for Huge, +4 for Gargantuan, +8 for Colossal). A Huge tree’s slam deals 2d6 points of damage, a Gargantuan tree’s slam deals 3d6 points of damage, and a Colossal tree’s slam deals 4d6 points of damage; the tree adds 1-1/2 times its Strength modifier to this damage. A Huge tree has reach 15 feet, a Gargantuan has reach 20 feet, and a Colossal has reach 30 feet. The tree attacks the creature you designate when you cast the spell, and is unable to move. You can direct the tree against a new target as a move action. The tree does not gain a bonus for flanking, nor can it help another combatant flank. It cannot attack a foe you cannot see.', NULL, NULL, true, false),
  ('arcana_theft', 'Arcana Theft', 'abjuration', NULL, NULL, 4, 'arcane', 'magus 4', '1 standard action', NULL, 'creature touched', NULL, NULL, 'instantaneous', 'none', 'yes', 'This spell functions as a targeted dispel magic spell, except it only affects creatures and it requires a melee touch attack. If the melee touch attack is successful and the spell successfully dispels one spell affecting the target, that spell is instead transferred to you, treating you as the original target. You do not receive a new saving throw or spell resistance check against this spell and must accept its affects even if they are not beneficial. This does not alter the spell’s duration; for example, if the spell only has 4 rounds of duration remaining when it is stolen, it only affects you for 4 rounds. If the spell or effect has a duration of permanent, its duration continues for 1 hour per caster level of the original caster, after which it ends. The stolen spell does not revert to the original target.', NULL, NULL, false, false),
  ('arcane_cannon', 'Arcane Cannon', 'transmutation', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one magically animated cannon', '1 round/level', 'none', 'no', 'Your focus becomes a Medium arcane cannon that appears in an unoccupied square within the spell’s range. If no unoccupied square is within range, the spell fails. The cannon comes into existence loaded. Each round thereafter, the cannon can either fire or load. A cannon must be loaded to fire. You do not need to supply ammunition for the cannon. On your turn, you can spend a move action to direct the cannon to wheel itself to a new location, moving the cannon up to 20 feet. If the arcane cannon ever leaves your line of sight, it winks out of existence, and the spell’s duration ends. The cannon has a range increment of 50 feet. It targets touch attack in the first range increment, and it has no misfire chance. The cannon acts as a weapon with the conductive special weapon ability, which you can use to channel your spell-like or supernatural abilities as long as you are within the range of arcane cannon. The cannon’s attack bonus is equal to your caster level + your Intelligence bonus or your Charisma bonus (for wizards or sorcerers, respectively) with an additional +1 per four caster levels (maximum +5 at 20th level). On a hit, the cannon deals 4d10 damage. The arcane cannon attacks have a critical modifier of ×4.', NULL, 'an ornate miniature cannon forged with a drop of your blood that costs 5,000 gp', false, true),
  ('arcane_concordance', 'Arcane Concordance', 'evocation', NULL, NULL, 3, 'arcane', 'bard 3', '1 standard action', 'personal', NULL, '10-ft.-radius emanation centered on you Targets you', NULL, '1 round/level', 'none', 'no', 'A shimmering, blue and gold radiance surrounds you, enhancing arcane spells cast by your allies within its area. Any arcane spell cast by a creature within the area gains a +1 enhancement bonus to the DC of any saving throws against the spell, and can be cast as if one of the following metamagic feats was applied to it (without increasing the spell level or Casting Time): Enlarge Spell, Extend Spell, Silent Spell, or Still Spell (you choose the metamagic feat when you cast arcane concordance).', 'a spent wand', NULL, false, false),
  ('arcane_disruption', 'Arcane Disruption', 'enchantment', 'compulsion', 'curse, mind-affecting', 2, 'arcane', 'bard 2, bloodrager 2, magus 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'This spell makes it difficult for the subject to cast arcane spells, use spell-like abilities, and use some abilities granted by arcane spellcasting classes. The subject must succeed at a concentration check (DC = 10 + 1/2 its caster level) in order to cast an arcane spell, use any spell-like ability (even those that come from a divine source), use arcane spell completion or spell trigger magic items, or use any of the following class features that come from an arcane spellcasting class: arcane school powers, arcanist exploits, bardic performances, magus arcana, or witch hexes. Spells, spell-like abilities, or class features that take a free, swift, or immediate action aren’t affected by this spell, nor are mythic spells or mythic powers.', 'a pinch of pepper', NULL, false, false),
  ('arcane_eye', 'Arcane Eye', 'divination', 'scrying', NULL, 4, 'arcane', 'alchemist 4, sorcerer/wizard 4, witch 4; Subdomain arcane 4', '10 minutes', 'unlimited', NULL, NULL, 'magical sensor', '1 min./level (D)', 'none', 'no', 'You create an invisible magical sensor that sends you visual information. You can create the arcane eye at any point you can see, but it can then travel outside your line of sight without hindrance. An arcane eye travels at 30 feet per round (300 feet per minute) if viewing an area ahead as a human would (primarily looking at the floor) or 10 feet per round (100 feet per minute) if examining the ceiling and walls as well as the floor ahead. It sees exactly as you would see if you were there. The eye can travel in any direction as long as the spell lasts. Solid barriers block its passage, but it can pass through a hole or space as small as 1 inch in diameter. The eye can’t enter another plane of existence, even through a gate or similar magical portal. You must concentrate to use an arcane eye. If you do not concentrate, the eye is inert until you again concentrate.', 'a bit of bat fur', NULL, false, false),
  ('arcane_lock', 'Arcane Lock', 'abjuration', NULL, NULL, 1, 'arcane', 'sorcerer/wizard 2; Subdomain wards 1', '1 standard action', 'touch', 'door, chest, or portal touched, up to 30 sq. ft./level in size', NULL, NULL, 'permanent', 'none', 'no', 'An arcane lock spell cast upon a door, chest, or portal magically locks it. You can freely pass your own arcane lock without affecting it. If the locked object has a lock, the DC to open that lock increases by 10 while it remains attached to the object. If the object does not have a lock, this spell creates one that can only be opened with a DC 20 Disable Device skill check. A door or object secured with this spell can be opened only by breaking in or with a successful dispel magic or knock spell. Add 10 to the normal DC to break open a door or portal affected by this spell. A knock spell does not remove an arcane lock; it only suppresses the effect for 10 minutes.', 'gold dust worth 25 gp', NULL, false, true),
  ('arcane_mark', 'Arcane Mark', 'universal', NULL, NULL, 0, 'divine', 'magus 0, psychic 0, shaman 0, sorcerer/wizard 0, summoner/unchained summoner 0, witch 0', '1 standard action', 'touch', NULL, NULL, 'one personal rune or mark, all of which must fit within 1 sq. ft.', 'permanent', 'none', 'no', 'This spell allows you to inscribe your personal rune or mark, which can consist of no more than six characters. The writing can be visible or invisible. An arcane mark spell enables you to etch the rune upon any substance without harm to the material upon which it is placed. If an invisible mark is made, a detect magic spell causes it to glow and be visible, though not necessarily understandable.', NULL, NULL, false, false),
  ('arcane_pocket', 'Arcane Pocket', 'conjuration', 'creation', NULL, 1, 'arcane', 'sorcerer/wizard 1', '1 standard action', 'touch', NULL, NULL, 'extradimensional space up to 1 cu. ft./level', '1 hour/level', 'none', 'no', 'With a touch, you conjure an extradimensional space inside a pouch or pocket. The pocket acts as a bag of holding, except it can hold only 10 pounds per caster level. Regardless of what is placed into the pocket, it weighs 3 pounds. Unlike a bag of holding, the pocket created by this ability cannot be overloaded or ruptured—any additional material simply spills out of the top—nor does it have any special interaction with other kinds of extradimensional spaces.', NULL, 'a pocket and a silver button', false, false),
  ('arcane_reinforcement', 'Arcane Reinforcement', 'transmutation', NULL, NULL, 3, 'arcane', 'sorcerer/wizard 3', '1 round', 'personal', 'you', NULL, NULL, 'concentration (up to 8 hours)', NULL, NULL, 'You cast this spell as you begin crafting an item using a Craft skill, and add your Spellcraft ranks to Craft checks made to create that item. As part of concentrating on the spell, you must continue chanting the verbal components, pausing at most for a few seconds at a time to speak, chew, and so on. If the crafting takes more than 1 day to complete, you must cast the spell each day to gain its benefit.', NULL, NULL, false, false),
  ('arcane_sight', 'Arcane Sight', 'divination', NULL, NULL, 3, 'divine', 'alchemist 3, inquisitor 3, magus 3, occultist 3, psychic 3, sorcerer/wizard 3, witch 3; Elemental School void 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', NULL, NULL, 'This spell makes your eyes glow blue and allows you to see magical auras within 120 feet of you. The effect is similar to that of a detect magic spell, but arcane sight does not require concentration and discerns aura location and power more quickly.', NULL, NULL, false, false),
  ('archon_s_aura', 'Archon’s Aura', 'evocation', NULL, 'good, lawful', 3, 'divine', 'cleric/oracle 3, paladin 3', '1 standard action', '20 ft.', NULL, '20-ft. radius centered on you duration 1 minute/level', NULL, NULL, 'Will negates; Spell resistance yes', NULL, 'You gain a powerful aura, similar to an archon’s aura of menace. Any hostile creature within a 20-foot radius of you must make a Will save to resist the effects of this aura. If the creature fails, it takes a –2 penalty on attack rolls and saving throws and to Armor Class for the duration of this spell, or until it successfully hits you with an attack. A creature that has resisted or broken the effect cannot be affected again by this particular casting of archon’s aura.', NULL, NULL, false, false),
  ('archon_s_trumpet', 'Archon’s Trumpet', 'evocation', NULL, 'good, sonic', 4, 'divine', 'bard 5, cleric 7, paladin 4, sorcerer/wizard 7', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Fort negates', 'yes', 'Upon hearing a booming report, as if from a trumpet archon’s mighty horn, all creatures in the area of the burst are paralyzed for 1d4 rounds.', NULL, NULL, false, false),
  ('ardor_s_onslaught', 'Ardor’s Onslaught', 'evocation', NULL, NULL, 4, 'divine', 'cleric 4, inquisitor 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius burst', NULL, 'instantaneous or 1d6 rounds; see text', 'Will partial, see text', 'yes', 'You unleash the power of zealous conviction to smite your enemies with a burst of pulsing metallic energy.', NULL, NULL, false, false),
  ('arid_refuge', 'Arid Refuge', 'conjuration', 'creation', NULL, 5, 'arcane', 'bard 5, sorcerer/wizard 5, witch 5', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '20-ft.-square structure', '2 hours/level (D)', 'none', 'no', 'You conjure a small stone building on any relatively flat nonliving surface at least 20 feet square that can support its weight (such as the ocean floor or an underwater ridge). The outline of a door is marked on one wall of your choice or on the roof. You and anyone you designate as the spell is cast can pass through the door, which is actually an opaque membrane of force that keeps the surrounding atmosphere from entering the structure.', 'a chip of stone wrapped in cloth', NULL, false, false),
  ('aristocrat_s_nightmare', 'Aristocrat’s Nightmare', 'transmutation', NULL, 'curse', 2, 'divine', 'alchemist 2, bard 2, cleric 3, inquisitor 2, investigator 2, magus 2, occultist 2, sorcerer/wizard 3, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level (see text)', 'Will negates', 'yes', 'You temporarily curse a creature so its touch lessens the value of coins it touches. While under the effects of this curse, whenever the target touches a coin of higher value than copper piece, that coin changes into a copper piece. The change takes place over the course of the following minute, allowing the target to interact with multiple coins before the effect of the curse becomes apparent. The affected coins are permanently transmuted from their previous material (typically gold or silver) into copper coins, though remove curse (which can affect up to 50 coins with a single casting) or a similar spell can restore them to their previous material.', 'a copper piece', NULL, false, false),
  ('armor_lock', 'Armor Lock', 'transmutation', NULL, NULL, 2, 'arcane', 'magus 2, sorcerer/wizard 3, witch 3', NULL, 'medium (100 ft. + 10 ft./level)', 'one armored creature', NULL, NULL, '1 round/level (D)', 'Reflex partial; see text', 'yes', 'Upon pointing at an armored foe, you cause all of the joints of the target’s armor to stiffen as otherworldly chains wrap around the target.', NULL, NULL, false, false),
  ('armor_of_darkness_3_5e', 'Armor of Darkness [3.5E]', 'abjuration', NULL, 'darkness', 4, 'arcane', 'darkness 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes', 'This spell envelops the target in shadows that can, if you desire, conceal the creature’s features.', NULL, NULL, true, false),
  ('army_across_time', 'Army Across Time', 'conjuration', 'summoning', NULL, 3, 'divine', 'arcanist 5, bard 4, cleric/oracle 5, hunter 3, inquisitor 4, medium 3, psychic 5, ranger 3, skald 4, sorcerer/wizard 5, warpriest 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'five 5-ft. cubes of temporal possibility plus one additional cube/level', '1 round/level', 'none', 'no', 'This spell functions as ally across time as noted above with two exceptions.', NULL, NULL, false, false),
  ('arrow_eruption', 'Arrow Eruption', 'conjuration', 'creation', NULL, 2, 'divine', 'ranger 2, sorcerer/wizard 2', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, '30-ft.-radius burst', NULL, 'instantaneous', 'none', 'yes', 'You create exact duplicates of the arrow or crossbow bolt you used to kill a creature in the previous round and launch one at enemy creatures within a 30-foot radius of the corpse. You can target one creature per caster level (maximum 15) within range of the burst and must make a single attack roll and apply it to each arrow. These duplicate arrows possess all the intrinsic magical properties of the arrow that killed the original creature as well as those passed on to it by your bow. They also enjoy the full benefit of any bonuses or modifiers you applied to the attack from other magical items, feats, and class or racial features. However, this spell cannot reproduce any spells or other limited-use magical effects that you used to enhance that particular attack. This includes such effects as the true strike spell, as well as any area spell you might have placed on the arrow by means of the arcane archer’s imbue arrow class feature.', 'arrow or crossbow bolt', NULL, false, false),
  ('arrow_of_law', 'Arrow of Law', 'evocation', NULL, 'lawful', 2, 'divine', 'cleric/oracle 2, paladin 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'arrow-shaped projectile of lawful energy', 'instantaneous (1 round); see text', 'Will partial (see text); Spell resistance yes', NULL, 'You fire a shimmering arrow of pure order from your holy symbol at any one target in range as a ranged touch attack. A chaotic creature struck by an arrow of law takes 1d8 points of damage per two caster levels (maximum 5d8). A chaotic outsider instead takes 1d6 points of damage per caster level (maximum 10d6) and is dazed for 1 round. A successful Will save reduces the damage to half and negates the daze effect. This spell deals only half damage to creatures that are neither chaotic nor lawful, and they are not dazed. The arrow has no effect on lawful creatures.', NULL, NULL, true, false),
  ('artificer_s_curse', 'Artificer’s Curse', 'transmutation', NULL, NULL, 6, 'divine', 'bard 6, cleric 7, inquisitor 6, occultist 6, shaman 7, sorcerer/wizard 7, witch 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 magical item', NULL, NULL, '1 minute/level (D)', 'Will negates (object)', 'yes', 'You temporarily suppress the most powerful qualities of a magical item. This item can be any object you suspect bears a magical enchantment, but if the targeted item is not magical, your spell has no effect. The spell reduces the object’s caster level by an amount equal to your caster level, to a minimum of 0. If the item grants a competence, deflection, enhancement, insight, luck, morale, natural armor, profane, resistance, or sacred bonus, the bonus is reduced by 1 for every 4 caster levels the item loses. If the item’s caster level is reduced to 0, all its magic qualities are suppressed (as if dispelled) for the duration of the spell. This spell has no effect on artifacts.', 'a blank scroll or page from a spellbook', NULL, false, false),
  ('ash_storm', 'Ash Storm', 'conjuration', 'creation', 'fire', 3, 'divine', 'druid 3, sorcerer/wizard 3, witch 3', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'cylinder (40-ft. radius, 20 ft. high)', NULL, '1 round/level', 'none; Spell resistance no', NULL, 'Driving ash blocks all sight (even darkvision) within the spell’s area of effect, and falling cinders cause the ground in the area to become difficult terrain.', 'a pinch of ash', NULL, true, false),
  ('ashen_path', 'Ashen Path', 'transmutation', NULL, NULL, 2, 'divine', 'arcanist 2, cleric 2, druid 2, hunter 2, oracle 2, ranger 2, sorcerer 2, warpriest 2, wizard 2', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '10 minutes/level', 'none', 'no', 'You grant the creature touched the ability to breathe with ease air that is contaminated with ash, spores, smoke, dust, or the like. The creature suffers no ill effects from natural airborne irritants or contaminants and gains a +4 bonus on saving throws against magical effects that involve any of these contaminants. In addition, the creature can see through magical obscuring effects caused by dense ash, smoke, fog, or similar concealment up to a distance of 60 feet, although this spell does nothing to enhance sight in dark or shadowy conditions. You can cast this spell on multiple creatures, but if you do, divide the duration evenly among all the creatures you touch (to a minimum duration of 10 minutes per target).', NULL, NULL, false, false),
  ('aspect_of_the_bear', 'Aspect of the Bear', 'transmutation', 'polymorph', NULL, 2, 'divine', 'druid 2, ranger 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'You take on an aspect of a bear. You gain a +2 enhancement bonus to natural armor and a +2 enhancement bonus on CMB rolls. You can also perform bull rush, grapple, and overrun combat maneuvers without provoking attacks of opportunity.', NULL, NULL, true, false),
  ('aspect_of_the_falcon', 'Aspect of the Falcon', 'transmutation ;  Level druid 1, ranger 1', 'polymorph', NULL, 9, 'arcane', NULL, '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'You take on an aspect of a falcon. Your eyes become wide and raptor-like, and you grow feathers on the sides of your head. You gain a +3 competence bonus on Perception checks, a +1 competence bonus on ranged attacks, and the critical multiplier for your bows and crossbows becomes 19-20/x3.', NULL, NULL, true, false),
  ('aspect_of_the_nightingale', 'Aspect of the Nightingale', 'transmutation', 'polymorph', NULL, 1, 'divine', 'bard 1, cleric/oracle 1, druid 1, inquisitor 1, paladin 1, ranger 1, shaman 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You take on an aspect of a nightingale. Your voice becomes clear and pleasant. You gain a +2 competence bonus on Perform (sing) checks and a +2 competence bonus on Diplomacy checks. Once per minute, if you are subject to a charm effect that allows a saving throw, you may roll twice and take the more favorable result.', NULL, NULL, true, false),
  ('aspect_of_the_stag', 'Aspect of the Stag', 'transmutation ;  Level druid 4, ranger 3', 'polymorph', NULL, 9, 'arcane', NULL, '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'When you cast this spell, you take on an aspect of a stag, including some of its physical characteristics. Your features become elongated and sinewy, and you grow a set of antlers you can use for defense. You gain a +2 dodge bonus to AC against attacks of opportunity, your base speed increases by 20 ft., you can move through any undergrowth (including magically manipulated undergrowth) at your normal speed, and can even make a 5-foot step within such terrain.', NULL, NULL, true, false),
  ('aspect_of_the_wolf', 'Aspect of the Wolf', 'transmutation', 'polymorph', NULL, 5, 'divine', 'druid 5, ranger 4; Mystery lunar 5', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'When you cast this spell, you take on an aspect of a wolf, including some of its physical characteristics. You become more rugged, your ears become elongated, and you sprout sharp fangs and fur.', NULL, NULL, true, false),
  ('assume_appearance', 'Assume Appearance', 'transmutation', 'polymorph', NULL, 3, 'divine', 'alchemist 3, bard 3, medium 3, mesmerist 3, occultist 3, psychic 3, shaman 3, sorcerer/wizard 3, spiritualist 3, summoner 3, witch 3', '1 minute', 'personal', 'you', NULL, NULL, '1 day/level (D)', NULL, NULL, 'This spell functions similarly to alter self, except for the following differences.', NULL, 'corpse of the deceased creature whose form you plan to assume', false, false),
  ('assumed_likeness', 'Assumed Likeness', 'illusion )', 'phantasm', 'emotion, mind-affecting', 1, 'arcane', 'bard 1, magus 2, medium 1, mesmerist 1, occultist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '10 minutes/level (D)', 'Will disbelief', 'yes', 'You draw upon the memories of the targets to create a visual disguise for yourself that only they can see. When you cast the spell, you choose an emotion from the table below. Each target perceives you as a creature it feels that way toward. If it doesn’t feel that way toward anyone, it instead perceives you as a stranger with features likely to evoke that emotion (e.g., if you choose respect, a guard who was taught to respect her elders but who currently knows no elders might see you as an elderly version of yourself).', NULL, NULL, false, false),
  ('astral_projection', 'Astral Projection', 'necromancy', NULL, NULL, 9, 'divine', 'cleric/oracle 9, sorcerer/wizard 9, witch 9; Domain travel 9; Bloodline dreamspun 9; Mystery ancestor 9, occult 9', '30 minutes', 'touch', NULL, NULL, NULL, 'see text', 'none', 'yes', 'By freeing your spirit from your physical body, this spell allows you to project an astral body onto another plane altogether. You can bring the astral forms of other willing creatures with you, provided that these subjects are linked in a circle with you at the time of the casting. These fellow travelers are dependent upon you and must accompany you at all times. If something happens to you during the journey, your companions are stranded wherever you left them.', '1,000 gp jacinth', NULL, false, true),
  ('atavism', 'Atavism', 'transmutation', NULL, NULL, 4, 'divine', 'druid 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one animal', NULL, NULL, '1 minute/level', 'Fortitude negates; Spell resistance yes', NULL, 'By bringing forth the primeval ancestry of the target animal, you awaken a savage engine of destruction. The animal immediately gains the advanced creature simple template. It gains a +2 bonus on all rolls, including damage rolls and special ability DCs, a +4 bonus to AC and CMD, and +2 hit points per HD. The animal’s primal instincts take hold for the duration of this spell—if the animal knows tricks granted by the Handle Animal skill, it loses access to all of those tricks save for “attack.” This spell has no effect on animals that already have the advanced creature template.', NULL, NULL, false, false),
  ('atonement', 'Atonement', 'abjuration', NULL, NULL, 5, 'divine', 'cleric/oracle 5, druid 5, inquisitor 5; Subdomain purity 5, redemption 5', '1 hour', 'touch', 'living creature touched', NULL, NULL, 'instantaneous', 'none', 'yes', 'This spell removes the burden of misdeeds from the subject. The creature seeking atonement must be truly repentant and desirous of setting right its misdeeds. If the atoning creature committed the evil act unwittingly or under some form of compulsion, atonement operates normally at no cost to you. However, in the case of a creature atoning for deliberate misdeeds, you must intercede with your deity (requiring you to expend 2,500 gp in rare incense and offerings). Atonement may be cast for one of several purposes, depending on the version selected.', 'burning incense', NULL, true, true),
  ('audiovisual_hallucination', 'Audiovisual Hallucination', 'illusion', 'phantasm', 'mind-affecting', 2, 'arcane', 'bard 3, magus 3, medium 2, mesmerist 3, occultist 3, psychic 3, sorcerer/wizard 3', NULL, NULL, NULL, NULL, NULL, 'concentration + 3 rounds (D)', NULL, NULL, 'This spell functions as auditory hallucination, except that you can include the image of any object, creature, or force you imagine or identify for the targets to imagine. You can move the image while you concentrate. After you cease concentration, you can define simple movements or changes for the phantasm to perform that can be explained in 25 words or fewer.', NULL, NULL, false, false),
  ('auditory_hallucination', 'Auditory Hallucination', 'illusion', 'phantasm', 'mind-affecting', 1, 'arcane', 'bard 1, magus 1, medium 1, mesmerist 1, occultist 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'long (400 ft. + 40 ft./level)', 'one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, 'concentration', 'Will disbelief', 'yes', 'You cause the targets to believe they hear any sound you imagine.', NULL, NULL, false, false),
  ('augmenting_wall', 'Augmenting Wall', 'evocation', NULL, 'see text', 5, 'arcane', 'magus 5, sorcerer/wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '20-ft.-high wall of energy whose area is up to one 10-ft. square/level', '1 round/2 levels (see text)', 'none (object)', 'no (object)', 'You create a wall of faintly shimmering elemental energy.', NULL, NULL, false, false),
  ('augury', 'Augury', 'divination', NULL, NULL, 2, 'divine', 'cleric/oracle 2, psychic 2, shaman 2, witch 2; Subdomain fate 2; Bloodline dreamspun 2, harrow 2', '1 minute', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'An augury can tell you whether a particular action will bring good or bad results for you in the immediate future.', 'incense worth at least 25 gp', 'a set of marked sticks or bones worth at least 25 gp', false, true),
  ('aura_alteration', 'Aura Alteration', 'illusion', NULL, NULL, 3, 'arcane', 'medium 3, mesmerist 3, occultist 3, psychic 4, spiritualist 4', '1 standard action', 'touch', 'one object or willing creature', NULL, NULL, '1 day/level (D)', 'Will negates (harmless, object)', 'yes', 'You mask and manipulate the target creature’s or object’s aura, confounding those who would attempt to discern helpful information from it using the read aura occult skill unlock or the analyze aura spell. You can change each of the following four auras with one casting of aura alteration.', NULL, NULL, false, false),
  ('aura_of_cannibalism', 'Aura of Cannibalism', 'necromancy', NULL, 'evil', 3, 'divine', 'cleric 3, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', NULL, '20-ft.-radius emanation centered on you', NULL, '1 minute/level (D)', 'Fort negates', 'yes', 'You emanate an aura that saps the strength of others of your kind and channels their energy into you.', 'a piece of flesh from another creature of your species', NULL, false, false),
  ('aura_of_distraction', 'Aura of Distraction', 'enchantment', NULL, 'mind-affecting', 2, 'arcane', 'psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', NULL, NULL, '20-ft.-radius emanation centered on you', NULL, '1 minute/level (D)', 'Will negates', 'yes', 'You emit an aura of subsonic noise and mental imagery that makes concentrating difficult.', NULL, NULL, false, false),
  ('aura_of_doom', 'Aura of Doom', 'necromancy', NULL, 'emotion, fear, mind-affecting', 4, 'divine', 'cleric/oracle 4', '1 standard action', 'personal', NULL, '20-ft.-radius emanation centered on you', NULL, '10 minute/level', 'Will negates; Spell resistance yes', NULL, 'You emanate an almost palpable aura of horror. All non-allies within this spell’s area, or that later enter the area, must make a Will save to avoid becoming shaken. A successful save suppresses the effect. Creatures that leave the area and come back must save again to avoid being affected by the effect.', 'powdered bone', NULL, true, false),
  ('aura_of_greater_courage', 'Aura of Greater Courage', 'abjuration', NULL, 'emotion', 2, 'divine', 'paladin 2', '1 standard action', 'personal', NULL, '10-ft.-radius emanation centered on you', NULL, '10/minutes per level', 'Will negates (harmless)', 'yes (harmless)', 'When you cast this spell you strengthen your paladin‘s aura of courage. Until the end of its duration, all allies within that aura are immune to fear (magical or otherwise). If you do not have the aura of courage class feature, aura of greater courage has no effect.', NULL, NULL, true, false),
  ('aura_of_inviolate_ownership', 'Aura of Inviolate Ownership', 'abjuration', NULL, NULL, 3, 'divine', 'cleric 3, inquisitor 3, paladin 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Fort negates (harmless)', 'yes (harmless)', 'This spell wards the attended items of all creatures it targets (items held, securely fastened to their person, or in containers on their person), enhancing each creature’s grip and protecting items from loss or theft.', NULL, NULL, true, false),
  ('aura_of_the_unremarkable', 'Aura of the Unremarkable', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'bard 3, medium 2, mesmerist 3, psychic 3, sorcerer/wizard 4', '1 standard action', '30 ft.', 'non-allied creatures within a 30-ft. emanation', NULL, NULL, '1 minute/level (D) and instantaneous', 'Will negates', 'yes', 'An invisible sphere of magic surrounds you, clouding the minds of creatures in the area so they regard even the strangest actions as innocuous. For example, if you and your allies are beating a member of the city guard for information, creatures within the area don’t think this is unusual or cause for alarm; if your ally is aiming a crossbow at the queen from a balcony, the affected creatures accept this as normal and unworthy of concern. Any hostile actions by you or your allies against a creature or its allies break the effect of the spell for that creature. When the spell ends (or when the affected creatures move outside of the range of the emanation), observers see things normally but altered perceptions from the earlier events remain. Each mention of the events as noteworthy (such as being questioned about them by an authority figure) allows the target another Will save to break the effect and remember things normally.', 'a white feather', NULL, false, false),
  ('aura_sight', 'Aura Sight', 'divination', NULL, NULL, 3, 'divine', 'alchemist 3, cleric 3, inquisitor 4, mesmerist 3, psychic 3, shaman 3, sorcerer/wizard 3, spiritualist 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'This spell makes your eyes glow and allows you to see alignment auras within 120 feet of you. The effect is similar to that of a detect chaos/evil/good/law spell, but aura sight does not require concentration, and it discerns an aura’s location and power more quickly.', NULL, NULL, false, false),
  ('authenticating_gaze', 'Authenticating Gaze', 'divination', NULL, NULL, 1, 'divine', 'alchemist 1, cleric 1, inquisitor 1, occultist 1, sorcerer/wizard 1', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'Your understanding of the written word becomes analytical and discerning. You gain an insight bonus equal to your caster level (maximum +10) on Appraise checks to determine the value of books and scrolls and on Linguistics checks to detect forgeries, and you can attempt a Linguistics check to detect a forged document at a glance, rather than taking the normal 1 round of examination per page. In addition, you immediately detect whether written works within 30 feet and within your line of sight have a magical aura and the strength of any such auras, as though you had concentrated on each written work for 1 round using detect magic.', NULL, NULL, true, false),
  ('aversion', 'Aversion', 'enchantment', 'compulsion', 'mind-affecting', 2, 'divine', 'bard 2, druid 3, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 day/level', 'Will partial', 'yes', 'You plant a revulsion in the mind of the subject, causing her to avoid an object or location. You must choose a specific object or place. A location chosen in this way can be no larger than a cube measuring 50 feet on a side. The aversion is entirely in the target’s mind, so the chosen object or location itself isn’t subject to any magical effect. If the target fails her saving throw, she can’t come within 60 feet of the chosen object or place.', NULL, NULL, false, false),
  ('awaken', 'Awaken', 'transmutation', NULL, NULL, 5, 'divine', 'druid 5, shaman 6; Mystery nature 5', '24 hours', 'touch', 'animal or tree touched', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You awaken a tree or animal to human-like sentience. To succeed, you must make a Will save (DC 10 + the animal’s current HD, or the HD the tree will have once awakened). The awakened animal or tree is friendly toward you. You have no special empathy or connection with a creature you awaken, although it serves you in specific tasks or endeavors if you communicate your desires to it. If you cast awaken again, any previously awakened creatures remain friendly to you, but they no longer undertake tasks for you unless it is in their best interests.', 'herbs and oils worth 2,000 gp', NULL, true, true),
  ('awaken_construct', 'Awaken Construct', 'transmutation', NULL, NULL, 5, 'divine', 'cleric 7, occultist 5, psychic 6, shaman 6, sorcerer/wizard 7', '24 hours', 'touch', 'mindless construct touched', NULL, NULL, 'instantaneous', 'Will negates', 'no', 'You amplify the animating force of a construct to more closely resemble a true soul, granting the construct humanlike sentience. To do so, you must succeed at a Spellcraft check (DC = 15 + the construct’s current Hit Dice). If the construct’s master (if any) is present, this is an opposed Spellcraft check.', 'herbs and oils worth 2,000 gp per HD of target', NULL, true, true),
  ('awaken_the_devoured', 'Awaken the Devoured', 'divination', NULL, 'pain', 4, 'divine', 'cleric 5, inquisitor 4, psychic 5, shaman 5, sorcerer/wizard 5, spiritualist 5, witch 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one daemon per 4 caster levels', NULL, NULL, 'instantaneous and 1 round/level', 'Will partial (see text)', 'yes', 'This spell is often used by conjurers as a method to torment daemons and force compliance, for it awakens the broken, anguished memories of the countless souls that the target daemons have consumed. All daemons targeted by awaken the devoured must be within 30 feet of each other. The fragmented memories haunt and afflict the daemons, dealing 1d8 points of damage per caster level (maximum 15d8) and making the daemons confused for 1 round per level. A daemon that succeeds at a Will save halves the damage and negates the confusion effect.', NULL, NULL, false, false),
  ('babble', 'Babble', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'bard 2, mesmerist 2, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature; see text', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'This spell causes the target to break into a fit of bizarre, uncontrollable babbling. The target also becomes nauseated. If the target succeeds at its save, the effects end. If not, the creature continues babbling and is nauseated for the entire duration.', NULL, NULL, false, false),
  ('badger_s_ferocity', 'Badger’s Ferocity', 'transmutation', NULL, NULL, 2, 'divine', 'cleric/oracle 3, druid 3, ranger 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one weapon/3 levels', NULL, NULL, 'concentration', 'Will negates (harmless); Spell resistance yes (harmless)', NULL, 'This functions like keen edge, except it affects multiple weapons and requires your concentration. You select the weapons to be affected, and can only affect one weapon per creature. If a creature’s weapon exceeds the spell’s range, the spell ends for that weapon.', NULL, NULL, false, false),
  ('balance_of_suffering', 'Balance of Suffering', 'conjuration', 'healing', NULL, 6, 'divine', 'cleric/oracle 6, inquisitor 6, occultist 6, shaman 6, spiritualist 6, warpriest 6, witch 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Will half; see text', 'yes; see text', 'You borrow life force from a living creature and infuse it into another living creature, potentially wreaking destruction on the former and bolstering the life of the latter.', NULL, NULL, true, false),
  ('baleful_polymorph', 'Baleful Polymorph', 'transmutation', 'polymorph', NULL, 4, 'divine', 'druid 5, magus 5, shaman 5, sorcerer/wizard 5, summoner 4, unchained summoner 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent', NULL, NULL, 'As beast shape III, except that you change the subject into a Small or smaller animal of no more than 1 HD. If the new form would prove fatal to the creature, such as an aquatic creature not in water, the subject gets a +4 bonus on the save.', NULL, NULL, false, false),
  ('baleful_shadow_transmutation', 'Baleful Shadow Transmutation', 'illusion', 'shadow', 'shadow', 6, 'divine', 'alchemist 6, bard 6, druid 7, medium 6, shaman 6, sorcerer/wizard 6, spiritualist 6, summoner 6, witch 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent', 'Will disbelief, then Fort negates', 'yes', 'You infuse a target’s shadow with energies from the Shadow Plane, shaping the shadow into one that appears to belong to a different creature, and tricking the target into believing it actually is that creature. When you cast this spell, choose one Huge or smaller creature of the animal type or one Medium or Small creature of the humanoid type. If the chosen creature is ill suited to the target’s current environment, such as an aquatic creature not in water, the subject gains a +4 bonus on all saving throws against baleful shadow transmutation. If the subject fails its Will save, it believes that it is the chosen creature, causing it to lose its extraordinary, supernatural, and spell-like abilities, lose its ability to cast spells (if it had the ability), and gain the alignment, special abilities, and Intelligence, Wisdom, and Charisma scores of its new form in place of its own. It retains any class features (other than spellcasting) that aren’t extraordinary, supernatural, or spell-like abilities.', NULL, NULL, false, false),
  ('ball_lightning', 'Ball Lightning', 'evocation', NULL, 'air, electricity', 4, 'divine', 'bloodrager 4, druid 4, magus 4, shaman 4, sorcerer/wizard 4; Elemental School air 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'two or more 5-ft.-diameter spheres', '1 round/level', 'Reflex negates', 'yes', 'You create two globes of lightning that fly in whichever direction you indicate. For every 4 caster levels above 7th, you create an additional globe of lightning (3 globes at 11th, 4 globes at 15th, to the maximum of 5 globes at 19th). These globes fly at a rate of 20 feet per round and have perfect maneuverability. Wind does not affect a flying sphere’s course.', 'a small iron ring', NULL, true, false),
  ('ban_corruption', 'Ban Corruption', 'abjuration', NULL, 'good', 3, 'divine', 'cleric 5, inquisitor 4, medium 3, occultist 4, paladin 4, shaman 5', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You strip all creatures within the emanation of any gifts associated with corruptions. Abilities associated with corruptions cease to function, as if they were magically dispelled.', NULL, 'a ceremonial dagger', false, false),
  ('bane', 'Bane', 'enchantment', 'compulsion', 'emotion, fear, mind-affecting', 1, 'divine', 'antipaladin 1, cleric/oracle 1, inquisitor 1, shaman 1; Subdomain curse 1', '1 standard action', '50 ft.', NULL, '50-ft.-radius burst, centered on you', NULL, '1 min./level', 'Will negates', 'yes', 'Bane fills your enemies with fear and doubt. Each affected creature takes a -1 penalty on attack rolls and a -1 penalty on saving throws against fear effects. Bane counters and dispels bless.', NULL, NULL, true, false),
  ('banish_seeming', 'Banish Seeming', 'abjuration', NULL, NULL, 3, 'divine', 'inquisitor 3, witch 5; Subdomain revelation 3', '1 standard action', 'touch', NULL, NULL, NULL, 'instantaneous and 1 round/level; see text', 'none', 'no', 'With a melee touch attack you can dispel an illusion or return a creature to its natural form. This functions as dispel magic directed at the effect in question, except you receive a +2 enhancement bonus on your dispel check and you can only dispel illusions or changes in form created by supernatural effects or spells. If multiple effects are changing the creature’s appearance, you can dispel one such effect for every four caster levels you possess, starting with the highest caster level spells and proceeding to spells with lower caster levels.', 'a cold iron nail', NULL, false, false),
  ('banishing_blade', 'Banishing Blade', 'abjuration', NULL, NULL, 4, 'divine', 'antipaladin 4, bloodrager 4, inquisitor 5, magus 5, medium 4, paladin 4, shaman 5, sorcerer/wizard 5, spiritualist 5, summoner 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one melee weapon', '1 round/level or until discharged', 'none and Will partial (see text)', 'yes (see text)', 'You imbue a weapon with the power to drive foes back. The first time each round the weapon strikes a creature, the weapon attempts a free bull rush combat maneuver check against that creature. This does not provoke attacks of opportunity. The combat maneuver for the bull rush is equal to 1d20 + your caster level.', NULL, NULL, false, false),
  ('banishment', 'Banishment', 'abjuration', NULL, NULL, 5, 'divine', 'cleric/oracle 6, inquisitor 5, shaman 6, sorcerer/wizard 7, summoner 5, unchained summoner 6; Bloodline celestial 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'A banishment spell is a more powerful version of the dismissal spell. It enables you to force extraplanar creatures out of your home plane. As many as 2 Hit Dice of creatures per caster level can be banished.', NULL, 'see text', false, false),
  ('banshee_blast', 'Banshee Blast', 'necromancy', NULL, 'death, fear, mind-affecting, sonic', 6, 'arcane', 'sorcerer/wizard 6, witch 6', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous and 1 round/level (see text)', 'Reflex half and Will negates (see text)', 'yes', 'You create a cone of spectral energy resembling screaming elven ghosts that deals 1d4 points of damage per caster level (maximum 15d4); a successful Reflex save halves this damage. Any creature that fails its Reflex save must succeed at a Will save or become panicked for 1 round/level.', NULL, NULL, false, false),
  ('baphomet_s_blessing', 'Baphomet’s Blessing', 'transmutation', 'polymorph', NULL, 4, 'divine', 'cleric/oracle 4, druid 4, sorcerer/wizard 4, summoner 4, witch 4', '1 standard action', 'touch', 'one living creature', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'You change the target’s head into that of a bull.', 'powdered bull’s horn', NULL, true, false),
  ('barbed_chains', 'Barbed Chains', 'conjuration', 'summoning', 'emotion, fear, mind-affecting', 1, 'divine', 'antipaladin 1, bloodrager 1, cleric 1, inquisitor 1, occultist 1, shaman 1, summoner 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'a chain sharpened at one end', 'instantaneous', 'Will partial (see text)', 'no', 'You summon a chain from another realm, causing it to burst out from the ground and strike a target within the spell’s range. You can have the chain either make a melee attack (dealing 1d6 points of slashing damage) or attempt a trip combat maneuver against the target. The chain uses your base attack bonus plus your key spellcasting ability score modifier as its attack bonus and combat maneuver bonus. On a successful hit or combat maneuver check, the target must attempt a Will save. If it fails its save, the creature is shaken for 1d4 rounds. You summon one additional chain every 3 levels after 1st, for a total of two chains at 4th level, three at 7th level, and a maximum of four at 10th level. Multiple chains can attack the same target but the shaken effect doesn’t stack.', 'a length of chain doused with fresh blood', NULL, false, false),
  ('bard_s_escape', 'Bard’s Escape', 'conjuration ;  Level bard 5', 'teleportation', NULL, 9, 'arcane', NULL, '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, 'instantaneous', 'none', 'no', 'You whisk yourself and willing allies out of a tight jam, or instantly transfer yourselves to another location to achieve greater strategic positioning. You can move any allies within range to any other space of your choosing within range. Those spaces need not be in line of sight or line of effect from your original position, but must be open locations on surfaces able to support the creatures teleported. Except as noted above, this spell otherwise functions as dimension door.', 'pieces of a smashed fiddle', NULL, false, false),
  ('barghest_feast', 'Barghest Feast', 'transmutation', NULL, 'evil', 3, 'arcane', 'alchemist 3', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The target gains the ability to absorb power from devouring a humanoid corpse. To use this ability, the target must feed on the corpse of one nonevil humanoid creature, a process that takes 1 full round per Hit Die the creature had and provokes attacks of opportunity. For every 2 rounds it feeds on the corpse in this way, the target gains a +1 profane bonus on attack rolls, saving throws, and skill checks (to a maximum of +5).', NULL, NULL, false, false),
  ('barkskin', 'Barkskin', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, druid 2, ranger 2, shaman 2, summoner/unchained summoner 2; Domain plant 2; Subdomain defense 2; Mystery nature 2, wood 2', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '10 min./level', 'none', 'yes (harmless)', 'Barkskin toughens a creature’s skin. The effect grants a +2 enhancement bonus to the creature’s existing natural armor bonus. This enhancement bonus increases by 1 for every three caster levels above 3rd, to a maximum of +5 at 12th level.', NULL, NULL, true, false),
  ('barrow_haze', 'Barrow Haze', 'necromancy', NULL, NULL, 3, 'arcane', 'sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'fog spreads in 20-ft. radius, 20 ft. high', '1 minute/level', 'none', 'no', 'Barrow haze creates a bank of fog similar to that created by fog cloud, except that the vapors are black and they have a necromantic link to you. The vapors do not interfere with your vision. Because of your link to the haze, if any part of it is within 30 feet of you, any creatures within the haze count as in range for the purpose of using any of your hexes that have a maximum range of 30 feet. For example, suppose you have the slumber hex, you are 25 feet from one edge of the haze, and an opponent is 40 feet farther away at the other extreme of the cloud. You can use your slumber hex on that opponent even though it is actually 65 feet away from you.', NULL, NULL, false, false),
  ('batrachian_surge', 'Batrachian Surge', 'transmutation', NULL, NULL, 1, 'divine', 'bloodrager 1, druid 1, inquisitor 1, ranger 1, summoner 1', '1 swift action', 'personal', 'you', NULL, NULL, '1 round + 1 round/3 levels (D)', 'none', 'yes (harmless)', 'You tap into your latent amphibian strengths, unlocking a short-lived physical talent. Armor or gear you are wearing adjusts to your new shape for the duration of the spell. When you cast batrachian surge, choose one of the following features to gain its associated benefits. You can have only one batrachian surge spell active on you at a time.', NULL, NULL, false, false),
  ('battering_blast', 'Battering Blast', 'evocation', NULL, 'force', 3, 'arcane', 'sorcerer/wizard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature or unattended object', NULL, NULL, 'instantaneous', 'Reflex partial (see text)', 'yes', 'You hurl a fist-sized ball of force resembling a sphere of spikes to ram a designated creature or object. You must succeed on a ranged touch attack to strike your target. On a successful hit, you deal 1d6 points of force damage per two caster levels (maximum 5d6). For every 5 caster levels you possess beyond 5th, you gain a second ball of force.', NULL, NULL, false, false),
  ('battle_trance', 'Battle Trance', 'enchantment', 'compulsion', 'emotion, mind-affecting', 3, 'divine', 'alchemist 3, antipaladin 3, cleric 4, inquisitor 3, ranger 3, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'You are transformed into a single-minded force of destruction. You gain the ferocity monster special ability, a number of temporary hit points equal to 1d6 + your caster level (maximum +10), and a +4 morale bonus on saving throws against mind-affecting effects. You cannot use the withdraw action or willingly move away from a creature that has attacked you.', NULL, NULL, false, false),
  ('battlemind_link', 'Battlemind Link', 'divination', NULL, 'mind-affecting', 4, 'divine', 'inquisitor 4, sorcerer/wizard 6; Elemental School wood 6; Domain [subdomain] Community [education]', '1 standard action', 'personal and close (25 ft. + 5 ft./2 levels)', 'you and 1 ally', NULL, NULL, '1 minute/level', 'Will negates (harmless); Spell resistance yes (harmless)', NULL, 'You fuse your thoughts with an ally’s, allowing the two of you to fight in tandem, perfectly coordinated. You and the ally each roll initiative in combat and use the higher die result before adding modifiers. This has three effects.', NULL, NULL, false, false),
  ('beacon_of_guilt', 'Beacon of Guilt', 'evocation', NULL, 'curse', 2, 'divine', 'arcanist 2, bard 2, inquisitor 2, occultist 2, skald 2, sorcerer/wizard 2', '1 standard action', 'touch', 'one object', NULL, NULL, '24 hours or until discharged, then instantaneous', 'Will negates (object); see text', 'yes', 'You place an invisible ward upon an object that is triggered the first time a creature tries to move the object from its current location. The next creature to touch the object is cursed to become obvious to everyone around it. The creature must succeed at a Will save or be surrounded in an aura of twinkling red light that functions as faerie fire (spell resistance applies). The curse bestowed by this spell cannot be dispelled, but a break enchantment, limited wish, miracle, remove curse, or wish spell can remove it.', NULL, NULL, false, false),
  ('beacon_of_luck', 'Beacon of Luck', 'divination', NULL, NULL, 3, 'divine', 'bard 3, cleric/oracle 3, inquisitor 4, paladin 4', '1 standard action', 'personal; see text', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'You send out a burst of luck with a 30-foot radius centered around you. While the beacon of luck is in effect, you gain a +2 sacred bonus on all saving throws. As an immediate action before a saving throw is made, allies within the area can choose to benefit from this luck, rolling twice for a saving throw and taking the better result. Once a creature benefits from the beacon of luck in this way, it cannot gain the benefit of this spell for 24 hours.', 'a tuft of rabbit fur', NULL, true, false),
  ('beanstalk', 'Beanstalk', 'conjuration', 'creation', NULL, 4, 'arcane', 'sorcerer/wizard 4, summoner 4, witch 4', '1 minute', '0 ft. (see text)', NULL, NULL, 'a 5-foot-radius beanstalk that grows to a height of 50 ft./caster level', '24 hours', 'none', 'no', 'When casting this spell, you must plant the material components in soil. When you do, at the end of casting, a large beanstalk rises up from the ground. It’s strong enough to support Huge or smaller creatures weighing no more than 2,000 pounds total, and has enough handholds and footholds that it can be climbed as if it were knotted rope (Climb DC 5). At the end of the spell’s duration, the beanstalk withers and dies at an accelerated rate, leaving nothing more than a pile of compost.', 'a small handful of beans', NULL, false, false),
  ('bear_s_endurance', 'Bear’s Endurance', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, bloodrager 2, cleric/oracle 2, druid 2, magus 2, psychic 2, ranger 2, shaman 2, sorcerer/wizard 2, summoner/unchained summoner 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes', 'The affected creature gains greater vitality and stamina. The spell grants the subject a +4 enhancement bonus to Constitution, which adds the usual benefits to hit points, Fortitude saves, Constitution checks, and so forth. Hit points gained by a temporary increase in Constitution score are not temporary hit points. They go away when the subject’s Constitution drops back to normal. They are not lost first as temporary hit points are.', 'a few hairs, or a pinch of dung, from a bear', NULL, true, false),
  ('beast_shape', 'Beast Shape', 'transmutation', 'polymorph', NULL, 3, 'arcane', 'alchemist 3, bloodrager 3, magus 3, sorcerer/wizard 3; Subdomain fur 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', NULL, NULL, 'When you cast this spell, you can assume the form of any Small or Medium creature of the animal type. If the form you assume has any of the following abilities, you gain the listed ability: climb 30 feet, fly 30 feet (average maneuverability), swim 30 feet, darkvision 60 feet, low-light vision, and scent.', 'a piece of the creature whose form you plan to assume', NULL, false, false),
  ('beastspeak', 'Beastspeak', 'divination', NULL, NULL, 2, 'divine', 'druid 2, shaman 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'When you’re in the form of an animal (such as when you are using wild shape or are affected by a polymorph effect), you can speak normally, including when you cast spells with verbal components, and you sound like your normal self when you speak. You can cast this spell while in animal form, using animal-appropriate somatic components.', NULL, NULL, true, false),
  ('bed_of_iron', 'Bed of Iron', 'necromancy', NULL, NULL, 1, 'divine', 'inquisitor 1, magus 1, paladin 1, sorcerer/wizard 1', '1 standard action', 'touch', 'one creature touched/level', NULL, NULL, '8 hours', 'Fort negates (harmless)', 'yes (harmless)', 'This spell makes even the clunkiest armor feel soft as silk to the wearer.', 'a feather or swatch of soft fabric', NULL, false, false),
  ('befuddled_combatant', 'Befuddled Combatant', 'enchantment', 'compulsion', 'curse, mind-affecting', 5, 'divine', 'arcanist 5, bard 5, mesmerist 5, psychic 5, shaman 5, skald 5, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'As a way to befuddle your target, you fill its mind with all manner of swirling images as well as baffling and incoherent thoughts, making the target an ineffective combatant and rendering its spellcasting and other such abilities much more feeble.', 'cooked noodles', NULL, false, false),
  ('beguiling_gift', 'Beguiling Gift', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1, psychic 1, witch 1', '1 standard action', '5 ft.', NULL, NULL, NULL, '1 round', 'Will negates', 'yes', 'You offer an object to an adjacent creature, and entice it into using or consuming the proffered item. If the target fails its Will save, it immediately takes the offered object, dropping an already held object if necessary. On its next turn, it consumes or dons the object, as appropriate for the item in question. For example, an apple would be eaten, a potion consumed, a ring put on a finger, and a sword wielded in a free hand. If the target is physically unable to accept the object, the spell fails. The subject is under no obligation to continue consuming or using the item once the spell’s duration has expired, although it may find a cursed item difficult to be rid of.', NULL, 'the object to be offered', false, false),
  ('beloved_of_the_forge', 'Beloved of the Forge', 'divination', NULL, NULL, 2, 'divine', 'alchemist 2, bard 2, cleric 2, shaman 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level', NULL, NULL, 'You gain an innate sense of the direction to your home or to the place where you last attempted a Craft check, whichever you choose when you cast the spell. You gain a +10 insight bonus on Survival checks made to find your way back to the chosen place.', NULL, NULL, false, false),
  ('bereave', 'Bereave', 'enchantment', 'compulsion', 'mind-affecting', 3, 'divine', 'bard 3, cleric 4, mesmerist 3, psychic 4, witch 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'An overwhelming feeling of loss overcomes the targets, and their allies’ words sound bleak and hollow. Regardless of actual allegiances, affected creatures no longer count as allies for other creatures and always count as enemies for the purposes of abilities, effects, and spells that differentiate between allies and enemies, such as flanking or spells such as bane or bless.', 'a broken chain link', NULL, true, false),
  ('bestow_auras', 'Bestow Auras', 'abjuration', NULL, NULL, 3, 'divine', 'antipaladin 3, paladin 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes', 'You transfer one or more of your paladin or antipaladin auras (such as aura of courage and aura of resolve) to another creature. You retain the personal effect of that aura, but the target becomes the center of the aura effect instead of you. For example, if you transfer your aura of courage, you remain immune to fear, but the target becomes the center of the aura that grants a +4 morale bonus on saves against fear effects. If an aura functions only when you are conscious, the transferred aura functions only when the target is conscious. If an aura functions only when you expend uses of another ability (such as with aura of justice or aura of vengeance), the transferred aura functions only if the target has that other ability and expends uses of it to activate the aura.', NULL, NULL, false, false),
  ('bestow_curse', 'Bestow Curse', 'necromancy', NULL, 'curse', 3, 'divine', 'antipaladin 3, bloodrager 4, cleric/oracle 3, shaman 3, sorcerer/wizard 4, spiritualist 3, witch 3; Subdomain curse 3, tyranny 3; Bloodline accursed 4, div 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You place a curse on the subject. Choose one of the following.', NULL, NULL, false, false),
  ('bestow_grace', 'Bestow Grace', 'abjuration', NULL, NULL, 2, 'divine', 'paladin 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level', 'Will (harmless)', 'yes (harmless)', 'With this spell you can bestow your divine grace on another good creature for a short amount of time, infusing that creature with a portion of your holy virtue. When you touch the subject, you grant that creature a sacred bonus to its saving throws equal to its Charisma bonus (if any) on all saving throws.', NULL, NULL, true, false),
  ('bestow_grace_of_the_champion', 'Bestow Grace of the Champion', 'transmutation', NULL, 'good, law', 4, 'divine', 'cleric/oracle 7, paladin 4', '1 standard action', 'touch', 'lawful good creature touched', NULL, NULL, '1 round/level (see text)', 'yes (harmless); Spell resistance yes (harmless)', NULL, 'You channel the power of good and law into the target, temporarily giving it powers similar to those of a paladin. The target gains the ability to use detect evil at will as a spell-like ability, immunity to disease (suppressing any diseases currently affecting it), and immunity to fear (ending any fear effects currently affecting it); can lay on hands (on itself only) once as a paladin of 1/2 your caster level; and can smite evil once as a paladin of 1/2 your caster level. It adds its Charisma bonus to all its saving throws. It can use spell completion, spell trigger, or other magic items that require the ability to cast spells as a paladin. Any abilities not used by the time the spell expires are lost. This spell has no effect if cast on a paladin.', NULL, NULL, true, false),
  ('bestow_insight', 'Bestow Insight', 'enchantment', 'compulsion', NULL, 2, 'divine', 'bard 2, cleric 3, inquisitor 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'one creature touched', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'When casting this spell, choose a single skill that you have at least one rank in. The target gains a +2 insight bonus on skill checks with this skill and is considered trained in that skill. The insight bonus increases by 1 for every four levels of the caster (maximum +6). Furthermore, once before the spell’s duration, the target can choose to roll two checks and take the greater result. Doing so ends the spell’s other effects.', NULL, NULL, false, false),
  ('bestow_planar_infusion_i', 'Bestow Planar Infusion I', 'evocation', NULL, NULL, 1, 'divine', 'cleric 1, inquisitor 1, magus 1, medium 1, occultist 1, psychic 1, sorcerer/wizard 1, summoner 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Fort negates (harmless)', 'yes', 'This spell draws upon the latent planar energy of the caster’s surroundings, allowing her to temporarily infuse a creature with the plane’s power. The touched creature gains that plane’s basic infusion for the spell’s duration. This spell has no effect if cast on the Material Plane, and it ends as soon as the spell’s target leaves the plane with which it has been infused. Details on planar infusions can be found in each plane’s Infusion section.', NULL, NULL, false, false),
  ('bestow_weapon_proficiency', 'Bestow Weapon Proficiency', 'enchantment', 'compulsion', 'mind-affecting', 2, 'divine', 'alchemist 2, antipaladin 2, cleric 2, inquisitor 2, magus 2, paladin 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard actionComponent V, S, M (pieces of shaved metal)', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'You bestow the subject with the ability to use a single type of weapon he is not proficient in as if he were proficient with that weapon. The weapon can be of any type, including an exotic weapon, but the subject of the spell must be holding the weapon.', 'pieces of shaved metal', NULL, false, false),
  ('betraying_sting', 'Betraying Sting', 'evocation', NULL, NULL, 6, 'divine', 'cleric 6, occultist 6, psychic 6, shaman 6, witch 6', '1 standard action', 'long (400 ft. + 40 ft./level)', 'one creature', NULL, NULL, 'instantaneous', 'Will partial', 'yes', 'You unleash divine power to smite those who wrongly trusted you. The power takes the form of a yellow-and-black bolt of energy that makes the sound of a thousand angry, swarming wasps. This spell affects only creatures that have an attitude toward you of indifferent, friendly, or helpful. The spell deals 1d8 points of damage per 2 caster levels you have.', NULL, NULL, false, false),
  ('billowing_skirt', 'Billowing Skirt', 'transmutation', NULL, NULL, 2, 'divine', 'bard 2, inquisitor 2, occultist 2, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', 'none', 'no', 'A skirt, kilt, or gown you are wearing enables you to control your falls through the air. A creature wearing the enchanted item of clothing falls slowly as if affected by feather fall and can attempt a DC 15 Fly skill check as a move action to hover in place for 1 round.', NULL, 'a skirt, kilt, or gown', false, false),
  ('bilocation', 'Bilocation', 'conjuration', 'creation', NULL, 8, 'arcane', 'psychic 8, sorcerer/wizard 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one duplicate', '1 round/level (D)', 'none', 'no', 'The spell creates an identical copy of you, along with everything you wear and carry, anywhere you choose within range; you exist in two places at once until the spell ends. You and the duplicate use the same statistics and share the same resources.', NULL, NULL, false, false),
  ('bind_sage', 'Bind Sage', 'conjuration', 'calling', NULL, 4, 'divine', 'occultist 5, psychic 5, shaman 5, sorcerer/wizard 4, summoner 4, witch 5', '10 minutes', 'close (25 ft. + 5 ft./2 levels); see text', 'one caulborn', NULL, NULL, 'instantaneous', 'Will negates', 'no and yes; see text', 'This variant of planar binding is specifically used to call one of the most knowledgeable types of outsiders: the immortal and prophetic caulborn. This spell calls a single caulborn into a specially prepared trap. The caster of this spell can compel a bound caulborn only to provide information (using its Knowledge skills or detect thoughts); attempts to compel the caulborn to fight, guard a location, or perform some other task automatically fail. This spell otherwise functions as planar binding. The most effective gifts for a caulborn are unique books or intelligent creatures upon whose thoughts the caulborn can feed. The true names of caulborn are nearly impossible to discover, as they are not inherently individualistic.', NULL, NULL, false, false),
  ('binding', 'Binding', 'enchantment', 'compulsion', 'mind-affecting', 8, 'arcane', 'sorcerer/wizard 8, summoner 6; Domain [subdomain] Magic [rites] 8, Law [slavery] 8', '1 minute', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'see text (D)', 'Will negates; see text', 'yes', 'A binding spell creates a magical restraint to hold a creature. The target gets an initial saving throw only if its Hit Dice equal at least half your caster level.', 'opals worth 500 gp per HD of the target creature, plus other components as specified below', NULL, false, true),
  ('binding_earth', 'Binding Earth', 'transmutation', NULL, 'earth', 2, 'divine', 'druid 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature or unattended object (see text)', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'If the target of this spell fails its Fortitude save, areas of earth and stone floor act as a snapping quagmire that pulls the target down and damages it if it attempts to move through such terrain.', NULL, NULL, true, false),
  ('bit_of_luck', 'Bit of Luck', 'evocation', NULL, NULL, 3, 'divine', 'alchemist 4, bard 3, cleric 4, psychic 4, shaman 4, sorcerer/wizard 4, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'For the spell’s duration, the caster gains a reservoir of luck with a total number of points equal to 1 point per 2 caster levels.', 'a four-leaf clover', NULL, false, false),
  ('bite_the_hand', 'Bite the Hand', 'enchantment', 'compulsion', NULL, 3, 'divine', 'druid 3, inquisitor 3, sorcerer/wizard 4, summoner 3, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature summoned by a spell or spell-like ability', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'With a short command and a wave of the hand, you compel the target creature to attack the being who summoned it, to the best of its ability. If the being who summoned it is not present, the creature acts normally according to its last task or instructions. This spell has no effect on called creatures, summoned creatures not brought forth by spells or spell-like abilities (such as a summoner’s eidolon), or bonded creatures not explicitly summoned, such as a paladin’s mount or wizard’s familiar.', NULL, NULL, true, false),
  ('biting_words', 'Biting Words', 'evocation', NULL, 'language-dependent, sonic', 1, 'arcane', 'bard 1, bloodrager 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'no', 'Your voice becomes suffused with magic so that you can harm your opponents with but a word. As a standard action, you can target one opponent within 30 feet with a ranged touch attack by speaking to it, dealing an amount of damage equal to 1d6 + your Strength or Charisma modifier, whichever is higher. The damage dealt is bludgeoning, piercing, and slashing damage and can be reduced by damage reduction. Each attack you make reduces the spell’s remaining duration by 1 minute. If an attack reduces the remaining duration to 0 minutes or less, the spell ends after the attack resolves.', NULL, NULL, false, false),
  ('black_mark', 'Black Mark', 'necromancy', NULL, 'curse, fear', 7, 'divine', 'druid 7, witch 7', '1 standard action', 'touch', 'one creature', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You mark the target with a black marking on its skin; the mark’s exact appearance determined by you, but can be no larger than your hand. The black mark functions as a mark of justice, and when the mark is activated, the target becomes shaken anytime it is on or in the water more than a 5 feet from shore. In addition, as long as the black mark is active, the target is affected as if subject to nature’s exile, but all creatures with the aquatic or water subtype or with a swim speed are made hostile, even those not of the animal type, though non-aquatic animals are not.', 'a flask of seawater', NULL, false, false),
  ('black_spot', 'Black Spot', 'necromancy', NULL, NULL, 4, 'divine', 'cleric 4, sorcerer/wizard 5, witch 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'permanent', 'Will negates', 'yes', 'The black spot is a specific and feared pirate curse. An intangible, illusory black spot manifests above the target’s head and remains until the target dies or the curse is lifted. The black spot cannot be covered or hidden by any means, including other illusions. The black spot radiates a cursed aura in a 10-foot radius around its target. Anyone within the aura gains a +2 bonus on weapon attack and damage rolls against the target. In addition, the target has a –4 penalty on saving throws against death effects.', NULL, NULL, false, false),
  ('black_sword_of_war', 'Black Sword of War', 'necromancy', NULL, NULL, 3, 'divine', 'antipaladin 3, cleric 3, ranger 3, sorcerer/wizard 3', '1 standard action', 'touch', 'piercing or slashing manufactured weapon touched', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless, object)', 'yes (harmless, object)', 'This spell is available to followers of the Horseman of War.', NULL, NULL, false, false),
  ('black_tentacles', 'Black Tentacles', 'conjuration', 'creation', NULL, 3, 'arcane', 'bloodrager 4, magus 4, sorcerer/wizard 4, summoner 3, unchained summoner 4, witch 4; Bloodline aberrant 4; Mystery dark tapestry 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius spread', NULL, '1 round/level (D)', 'none', 'no', 'This spell causes a field of rubbery black tentacles to appear, burrowing up from the floor and reaching for any creature in the area.', 'octopus or squid tentacle', NULL, false, false),
  ('blacklight_3_5e', 'Blacklight(3.5E)', 'evocation', NULL, 'darkness', 3, 'arcane', 'darkness 3, sorcerer/wizard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '20-ft.-radius emanation', NULL, '1 round/level (D)', 'Will negates or none (object)', 'yes or no (object)', 'You create an area of total darkness. The darkness is impenetrable even to darkvision, but you can see normally within it. Creatures outside the spell’s area, even you, cannot see through it.', NULL, NULL, false, false),
  ('blade_barrier', 'Blade Barrier', 'evocation', NULL, 'force', 6, 'divine', 'cleric/oracle 6, inquisitor 6; Domain good 6, war 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'wall of whirling blades up to 20 ft. long/level, or a ringed wall of whirling blades with a radius of up to 5 ft. per two levels; either form is 20 ft. high', '1 min./level (D)', 'Reflex half or Reflex negates; see text', 'yes', 'An immobile, vertical curtain of whirling blades shaped of pure force springs into existence. Any creature passing through the wall takes 1d6 points of damage per caster level (maximum 15d6), with a Reflex save for half damage.', NULL, NULL, false, false),
  ('blade_lash', 'Blade Lash', 'transmutation', NULL, NULL, 1, 'arcane', 'bloodrager 1, magus 1', '1 standard action', 'touch', 'your melee weapon', NULL, NULL, 'instantaneous', 'none', 'no', 'Your weapon elongates and becomes whip-like. As part of casting this spell, you can use this weapon to attempt a trip combat maneuver against one creature within 20 feet, and you gain a +10 bonus on your roll, after which the weapon returns to its previous form.', NULL, NULL, false, false),
  ('blade_of_bright_victory', 'Blade of Bright Victory', 'transmutation', NULL, 'good', 3, 'divine', 'paladin 3', '1 standard action component V, S', 'touch', 'your paladin bonded weapon', NULL, NULL, '1 minute/level', 'Will negates (harmless); Spell resistance no', NULL, 'You strengthen the bond between your divine bond weapon and its celestial spirit. The weapon gains the ghost touch property. You may change your weapon’s damage type (bludgeoning, piercing, slashing) as a swift action. You gain a sacred bonus to your CMD against disarm and sunder attacks directed at your bonded weapon; this bonus is equal to half your caster level.', NULL, NULL, false, false),
  ('blade_of_dark_triumph', 'Blade of Dark Triumph', 'transmutation', NULL, 'evil', 3, 'divine', 'antipaladin 3', '1 standard action component V, S', 'touch', 'your fiendish boon weapon', NULL, NULL, '1 minute/level', 'Will negates (harmless); Spell resistance no', NULL, 'You strengthen the bond between your fiendish boon weapon and its unholy spirit. The weapon gains the ghost touch property. You may change your weapon’s damage type (bludgeoning, piercing, slashing) as a swift action. You gain a profane bonus to your CMD against disarm and sunder attacks directed at your boon weapon; this bonus is equal to half your caster level.', NULL, NULL, false, false),
  ('blade_of_light', 'Blade of Light', 'transmutation', NULL, 'good', 4, 'divine', 'cleric 4, inquisitor 4, paladin 4', '1 standard action', 'touch', 'one melee weapon', NULL, NULL, '1 round/level', 'none', 'no', 'This spell infuses a weapon with pure sunlight (the weapon need not be a bladed weapon).', NULL, NULL, false, false),
  ('blade_snare', 'Blade Snare', 'abjuration', NULL, NULL, 3, 'divine', 'druid 3, magus 3, ranger 3, sorcerer/wizard 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'none', 'no', 'This spell creates an invisible magic field that does not stop weapons (whether manufactured or natural) from moving toward you, but impedes their motion when they are retracted. When you are hit with a melee attack, attempt a caster level check against your opponent’s CMD. If your check succeeds, your opponent’s attacking weapon or body part becomes caught in the field, as if magically affixed to your body. If your check fails, your opponent may retract its weapon.', NULL, NULL, false, false),
  ('blade_tutor_s_spirit', 'Blade Tutor’s Spirit', 'conjuration', 'creation', NULL, 1, 'divine', 'antipaladin 2, magus 1, paladin 2, sorcerer/wizard 2, summoner 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You summon an insubstantial spirit of force that resembles a cloudy vapor hovering around your fists or any melee weapons you wield. The spirit compensates for your defensive or reckless melee attacks, nudging your weapons in the proper direction.', NULL, NULL, false, false),
  ('bladed_dash', 'Bladed Dash', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 2, magus 2, skald 2', '1 standard action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'When you cast this spell, you immediately move up to 30 feet in a straight line any direction, momentarily leaving a multi-hued cascade of images behind you. This movement does not provoke attacks of opportunity. You may make a single melee attack at your highest base attack bonus against any one creature you are adjacent to at any point along this 30 feet. You gain a circumstance bonus on your attack roll equal to your Intelligence or Charisma modifier, whichever is higher. You must end the bonus movement granted by this spell in an unoccupied square. If no such space is available along the trajectory, the spell fails. Despite the name, the spell works with any melee weapon.', NULL, NULL, false, false),
  ('blasphemy', 'Blasphemy', 'evocation', NULL, 'evil, sonic', 7, 'divine', 'cleric/oracle 7, inquisitor 6; Domain evil 7', '1 standard action', '40 ft.', NULL, 'nonevil creatures in a 40-ft.-radius spread centered on you', NULL, 'instantaneous', 'Will partial', 'yes', 'Any nonevil creature within the area of a blasphemy spell suffers the following ill effects:', NULL, NULL, false, false),
  ('blast_barrier', 'Blast Barrier', 'transmutation', 'sonic', NULL, 3, 'divine', 'druid 4, ranger 3, sorcerer/wizard 3, witch 4', '1 standard action', 'close (25 ft. + 5ft./2 levels)', NULL, NULL, '1-ft.-thick wall up to 10 ft. high by 20 ft. wide', 'concentration, up to 1 round/2 levels', 'Reflex half (see below)', 'yes (see below)', 'When you cast blast barrier, you cause a rippling wall of loose earth, mud, snow, sand, or gravel to spring up in a designated space within the spell’s range. This wall provides total cover to all Large or smaller creatures and objects. The barrier can only spring up in an area of natural, unworked ground. The energy that forms the wall’s matrix is unstable, and you must concentrate to maintain the wall’s shape. A blast barrier has an AC of 9, hardness 0, and 5 hit points per caster level. When a blast barrier reaches 0 hit points, or when you cease concentrating on maintaining it, the energies that maintain the barrier’s shape fail with explosive results, sending sharp chunks of the materials comprising the wall and magical energy out along both sides. Any creature that is adjacent to a blast barrier when it explodes takes 2d6 points of slashing damage and 1d6 points of sonic damage per 3 caster levels (maximum 6d6). A successful Reflex save halves the total damage done. Spell resistance applies as well.', 'handful of snow, earth, or gravel', NULL, false, false),
  ('blast_of_wind', 'Blast of Wind', 'evocation', NULL, 'air', 4, 'divine', 'druid 4, sorcerer/wizard 4', '1 standard action', '60 ft.', NULL, NULL, 'line-shaped blast of hurricane-force wind emanating out from you to the extreme of the range', '1 round', 'Fort negates', 'yes', 'With a spiraling gesture of your hand and a forceful exhalation, you create a brief but fierce (90 mph) blast of wind. This spell functions as gust of wind, except all creatures within the area are treated as though they were one size category smaller for the purpose of determining how the spell affects them. For every 4 caster levels beyond 7th, creatures in the area are treated as an additional size category smaller (to a maximum of three size categories smaller at 15th level).', NULL, NULL, false, false),
  ('blaze_of_glory', 'Blaze of Glory', 'conjuration', 'healing', 'good, mind-affecting', 4, 'divine', 'paladin 4', '1 standard action or immediate action; see text', NULL, NULL, '30-ft.-radius burst centered on you', NULL, 'instantaneous and 1 round/level; see text', 'Will partial', 'yes', 'You fall unconscious but also unleash a spectacular wave of holy energy that heartens and heals your allies while leaving your opponents daunted and damaged. You can cast this spell as either a standard action on your turn, or as an immediate action when brought to below 0 hit points. If cast as a standard action, you are immediately reduced to -1 hit points, but stable, after casting the spell.', NULL, NULL, false, false),
  ('blazing_rainbow', 'Blazing Rainbow', 'evocation', NULL, 'light', 6, 'divine', 'druid 6', '1 round', '0 ft. or 10 ft./level', NULL, NULL, 'bow or bridge of light', '1 minute/level or until discharged (see text)', 'none', 'no', 'You create a spectrum of multicolored solid light that can be used for one of two effects.', 'a drop of rainwater', NULL, false, false),
  ('bleed', 'Bleed', 'necromancy', NULL, NULL, 0, 'divine', 'cleric/oracle 0, inquisitor 0, psychic 0, shaman 0, sorcerer/wizard 0, witch 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You cause a living creature that is below 0 hit points but stabilized to resume dying. Upon casting this spell, you target a living creature that has -1 or fewer hit points. That creature begins dying, taking 1 point of damage per round. The creature can be stabilized later normally. This spell causes a creature that is dying to take 1 point of damage.', NULL, NULL, false, false),
  ('bleed_for_your_master', 'Bleed for Your Master', 'enchantment', 'compulsion', 'mind-affecting', 2, 'divine', 'antipaladin 2, druid 3, ranger 3, sorcerer/wizard 3, witch 3', '1 immediate action', 'touch', 'your animal companion, familiar, or fiendish servant', NULL, NULL, 'instantaneous', 'none', 'no', 'When you would be hit by an attack that requires an attack roll, or when you are within an area of effect that allows you to attempt a Reflex saving throw, with a single touch you compel the target to throw itself in front of the blow or shield you from the effect.', NULL, NULL, false, false),
  ('blend', 'Blend', 'illusion', 'glamer', NULL, 1, 'divine', 'alchemist 1, druid 1, magus 1, psychic 1, ranger 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'You draw upon your elven link to the wilderness to change the coloration of yourself and your equipment to match that of your surroundings. This grants you a +4 circumstance bonus on Stealth checks and allows you to make Stealth checks without cover or concealment, but only while you move no more than half your base speed or less. If you move more than half your base speed on your turn, you gain no benefit from this spell until the start of your next turn. If you make an attack, this spell ends (as invisibility).', NULL, NULL, false, false),
  ('blend_with_surroundings', 'Blend With Surroundings', 'illusion', 'glamer', NULL, 1, 'divine', 'bard 1, cleric 1, druid 1, shaman 1, sorcerer/wizard 1, summoner 1, witch 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '10 minutes/level', 'Fort negates (harmless) or Will disbelieves (if interacted with)', 'yes (harmless)', 'This spell changes the appearance of the affected creature so that it better blends in with its surroundings. As chosen by you, the affected creature takes on the appearance of a statue, furniture, a tree, a bush, a rock, or another object of similar size.', 'a chess piece', NULL, true, false),
  ('bless', 'Bless', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'cleric/oracle 1, inquisitor 1, paladin 1, shaman 1; Domain community 1; Subdomain leadership 1, resolve 1; Bloodline celestial 1', '1 standard action', '50 ft.', NULL, 'The caster and all allies within a 50-ft. burst, centered on the caster', NULL, '1 min./level', 'none', 'yes (harmless)', 'Bless fills your allies with courage. Each ally gains a +1 morale bonus on attack rolls and on saving throws against fear effects.', NULL, NULL, true, false),
  ('bless_army', 'Bless Army', 'enchantment', 'compulsion', 'mind-affecting', 6, 'divine', 'cleric 6', '1 standard action', '1 hex', 'one army', NULL, NULL, '1 battle', 'none', 'yes (harmless)', 'This spell fills an army with courage. The army gains a +1 bonus on OM and Morale checks.', NULL, NULL, true, false),
  ('bless_water', 'Bless Water', 'transmutation', NULL, 'good', 1, 'divine', 'cleric/oracle 1, inquisitor 1, paladin 1; Subdomain divine 2', '1 minute', 'touch', 'flask of water touched', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'This transmutation imbues a flask (1 pint) of water with positive energy, turning it into holy water.', '5 pounds of powdered silver worth 25 gp', NULL, false, true),
  ('bless_weapon', 'Bless Weapon', 'transmutation', NULL, NULL, 2, 'arcane', 'paladin 1; Domain  glory 2', '1 standard action', 'touch', 'weapon touched', NULL, NULL, '1 min./level', 'none', 'no', 'This transmutation makes a weapon strike true against evil foes. The weapon is treated as having a +1 enhancement bonus for the purpose of bypassing the DR of evil creatures or striking evil incorporeal creatures (though the spell doesn’t grant an actual enhancement bonus). The weapon also becomes good-aligned, which means it can bypass the DR of certain creatures. (This effect overrides and suppresses any other alignment the weapon might have.) Individual arrows or bolts can be transmuted, but affected projectile weapons (such as bows) don’t confer the benefit to the projectiles they shoot.', NULL, NULL, false, false),
  ('blessed_fist', 'Blessed Fist', 'transmutation', NULL, 'good', 1, 'divine', 'cleric 1, paladin 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'none', 'yes', 'The target is considered to be armed even when unarmed, so it doesn’t provoke attacks of opportunity when it attacks foes with unarmed strikes. Its unarmed strikes can deal lethal or nonlethal damage (target’s choice). If the target already has this ability (such as from the monk unarmed strike ability or the Improved Unarmed Strike feat), its unarmed strikes gain a +1 enhancement bonus on attack rolls and damage rolls, and they count as good-aligned weapons for the purposes of overcoming damage reduction.', NULL, NULL, false, false),
  ('blessing_of_courage_and_life', 'Blessing of Courage and Life', 'conjuration', 'healing', 'emotion', 2, 'divine', 'cleric/oracle 2, paladin 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 minute/level (see below)', 'Will negates (harmless)', 'yes (harmless)', 'With this prayer you provide long-lasting succor to a wounded creature. For as long as the effect lasts, the target receives a +2 morale bonus on saving throws against fear and death effects. At any time while the spell is in effect, the target can choose to end the spell as a swift action for a burst of healing energy. The target loses the saving throw bonus, but is healed of 1d8 points of damage +1 point per caster level (maximum +10).', NULL, NULL, true, false),
  ('blessing_of_fervor', 'Blessing of Fervor', 'transmutation', NULL, NULL, 4, 'divine', 'cleric/oracle 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'With this blessing, you call your allies to move forth and empower them to conquer and become victorious. Each round for the duration of this spell, each of your allies can choose one of the following bonuses for that round at the beginning of its turn (their choice).', NULL, NULL, true, false),
  ('blessing_of_liberty', 'Blessing of Liberty', 'abjuration', NULL, NULL, 2, 'divine', 'bard 2, shaman 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You imbue yourself with the blessings of liberty. You gain a +1 luck bonus per 6 caster levels (minimum +1, maximum +3) to your CMD and on saving throws against spells and traps that would move you or impede your movement. You can end the spell’s effects as a swift action to gain a +20 foot enhancement bonus to your base speed for 1 round per whole minute of duration remaining.', 'a feather or small object that symbolizes good fortune', NULL, false, false),
  ('blessing_of_the_mole', 'Blessing of the Mole', 'transmutation', NULL, NULL, 3, 'divine', 'cleric/oracle 3, inquisitor 3, paladin 3, ranger 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, '1 creature/level', NULL, '1 minute/level', 'none (harmless); Spell resistance yes (harmless)', NULL, 'The targets gain darkvision 30 feet and a +2 competence bonus on Stealth checks.', NULL, NULL, false, false),
  ('blessing_of_the_salamander', 'Blessing of the Salamander', 'transmutation', 'polymorph', NULL, 4, 'divine', 'druid 5, ranger 4', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'When you cast this on a creature, its skin turns slick and clammy and it is able to regenerate damage each round. While under the effects of the spell, the creature gains fast healing 5, fire resistance 20 and a +2 competence bonus to its Combat Maneuver Defense.', NULL, NULL, true, false),
  ('blessing_of_the_watch', 'Blessing of the Watch', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'cleric 1, inquisitor 1, paladin 1', NULL, NULL, NULL, NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'This spell functions like bless, except as noted. It works only in the caster’s home city, and in areas under the jurisdiction of the city watch. For example, if the watch patrols a shantytown outside the city walls but not the ruined subterranean tunnels that lie beneath the city, the spell works in the former area but not the latter.', NULL, NULL, false, false),
  ('blessings_of_luck_and_resolve', 'Blessings of Luck and Resolve', 'enchantment', 'compulsion', 'mind-affecting', 2, 'divine', 'cleric 2, inquisitor 2, paladin 2', '1 standard action', 'touch', 'one living creature touched', NULL, NULL, '1 minute/level (D), special see below', 'Will negates (harmless)', 'yes (harmless)', 'A favored blessing of halfling clerics, this spell grants its target a +2 morale bonus on saving throws against fear effects. If the target has the fearless racial trait, it is immune to fear instead. If the target fails a saving throw against fear, it can end the spell as an immediate action to reroll the save with a +4 morale bonus, and must take the new result, even if it is worse.', NULL, NULL, false, false),
  ('blight', 'Blight', 'necromancy', NULL, NULL, 4, 'divine', 'druid 4, shaman 5, sorcerer/wizard 5, witch 5; Subdomain radiation 4, seasons 4; Bloodline daemon 5', '1 standard action', 'touch', 'plant touched', NULL, NULL, 'instantaneous', 'Fortitude half; see text', 'yes', 'This spell withers a single plant of any size. An affected plant creature takes 1d6 points of damage per level (maximum 15d6) and may attempt a Fortitude saving throw for half damage. A plant that isn’t a creature doesn’t receive a save and immediately withers and dies.', NULL, NULL, true, false),
  ('blightburn_weapon', 'Blightburn Weapon', 'transmutation', NULL, NULL, 4, 'divine', 'alchemist 4, inquisitor 4, magus 4, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one weapon', NULL, NULL, '1 round/level (D)', 'Will negates (object)', 'yes (object)', 'You transform the target weapon into pure blightburn. The weapon functions as normal, but any creature that touches it, or that it strikes, takes 2d6 points of fire damage each round it remains in contact. In addition, the weapon emanates an aura of radiation that causes blightburn sickness. This is as the disease, but with a 10-foot radius and a save DC equal to this spell’s save DC.', NULL, NULL, true, false),
  ('blinding_ray', 'Blinding Ray', 'evocation', NULL, 'good, light', 2, 'divine', 'cleric 2, inquisitor 3, paladin 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one or more rays of light', 'instantaneous (see text)', 'Fort negates', 'yes', 'You blast your enemies with blinding rays of sunlight. You may fire one ray, plus one additional ray for every four levels beyond 3rd (to a maximum of three rays at 11th level). Each ray requires a ranged touch attack to hit. If a ray hits, it explodes into powerful motes of light, and the target must save or be blinded for 1 round. If the target has light blindness, light sensitivity, or is otherwise vulnerable to bright light, it instead must save or be blinded for 1d4 rounds and take 1d4 points of damage per two caster levels (maximum 5d4). Any creature blinded by a ray sheds light as a sunrod for the duration of its blindness. The rays may be fired at the same or different targets, but all rays must be aimed at targets within 30 feet of each other and fired simultaneously.', NULL, NULL, true, false),
  ('blindness_deafness', 'Blindness-Deafness', 'necromancy', NULL, 'curse', 2, 'divine', 'antipaladin 2, bard 2, bloodrager 2, cleric/oracle 3, psychic 2, shaman 3, sorcerer/wizard 2, witch 2; Domain darkness 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, 'permanent (D)', 'Fortitude negates', 'yes', 'You call upon the powers of unlife to render the subject blinded or deafened, as you choose.', NULL, NULL, false, false),
  ('blink', 'Blink', 'transmutation', NULL, NULL, 3, 'arcane', 'bard 3, magus 3, psychic 3, sorcerer/wizard 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'You “blink” quickly back and forth between the Material Plane and the Ethereal Plane and look as though you’re winking in and out of reality at random. Blink has several effects, as follows.', NULL, NULL, false, false),
  ('blistering_invective', 'Blistering Invective', 'evocation', NULL, 'fire, language-dependent', 2, 'divine', 'alchemist 2, bard 2, inquisitor 2', '1 standard action', 'personal', NULL, '30-ft. radius', NULL, 'instantaneous', 'Reflex partial, see text', 'special, see below', 'You unleash an insulting tirade so vicious and spiteful that enemies who hear it are physically scorched by your fury. When you cast this spell, make an Intimidate check to demoralize each enemy within 30 feet of you. Enemies that are demoralized this way take 1d10 points of fire damage and must succeed at a Reflex save or catch fire. Spell Resistance can negate the fire damage caused by this spell, but does not protect the creature from the demoralizing effect.', NULL, NULL, false, false),
  ('bloatbomb', 'Bloatbomb', 'necromancy', NULL, 'acid, death', 4, 'divine', 'antipaladin 4, cleric 4, sorcerer/wizard 4', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous and 1 minute/level (see text)', 'Fort negates or Reflex half (see text)', 'yes', 'The target creature dies if it fails a Fortitude saving throw and its Hit Dice are no more than half your caster level. If it dies, its corpse rapidly putrefies. The next creature to touch the corpse within 1 minute per level of the target’s death causes the corpse to explode in a 10-foot-radius burst, dealing 3d6 points of acid damage (Reflex half).', NULL, NULL, false, false),
  ('blood_armor', 'Blood Armor', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, bloodrager 2, psychic 2, sorcerer/wizard 2, summoner/unchained summoner 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'Your blood becomes as hard as iron upon contact with air. Each time you take at least 5 points of piercing or slashing damage, your armor gains a +1 enhancement bonus to your AC. An outfit of regular clothing counts as armor that grants no AC bonus for the purpose of this spell. This enhancement bonus stacks with itself, but not with an existing enhancement bonus, to a maximum enhancement bonus of +5. This spell has no effect while underwater or in environments that lack air.', NULL, NULL, false, false),
  ('blood_biography', 'Blood Biography', 'divination', NULL, NULL, 2, 'divine', 'bard 2, bloodrager 3, cleric/oracle 3, inquisitor 3, medium 2, occultist 2, psychic 3, sorcerer/wizard 3', '1 minute', 'touch', NULL, NULL, NULL, 'instantaneous', 'Will negates (see text)', 'no', 'You learn the answers to a specific set of questions about a creature so long as you have access to at least one drop of its blood. You can cast this spell on the blood of the living or the dead, but living or undead creatures are entitled to a Saving Throw to resist the spell. You can cast the spell on dried or fresh blood. Once you cast the spell the answers to the following four questions appear on any flat surface you designate (a wall, a piece of paper, and so on).', 'a scrap of parchment', NULL, true, false),
  ('blood_blaze', 'Blood Blaze', 'transmutation', NULL, 'fire', 1, 'divine', 'alchemist 2, antipaladin 1, bloodrager 2, cleric 2, magus 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level (D)', 'Fort negates (harmless)', 'yes (harmless)', 'The target gains a 5-foot-radius aura that causes the blood of creatures in that area to ignite upon contact with air. Any creature (including the spell’s target) within the aura that takes at least 5 points of piercing, slashing, or bleed damage from a single attack automatically creates a spray of burning blood. The spray strikes a creature in a randomly determined square adjacent to the injured creature. The spray deals 1d6 points of fire damage to any creature in that square, and 1 point of splash damage to all creatures within 5 feet of the spray’s target, including the target of this spell. A creature can only create one spray of burning blood per round. Creatures that do not have blood (including oozes and most constructs and undead) do not create blood sprays when attacked.', NULL, NULL, false, false),
  ('blood_boil', 'Blood Boil', 'necromancy', NULL, NULL, 5, 'arcane', 'magus 5, sorcerer/wizard 5, witch 5', '1 standard action', 'touch', 'one living creature', NULL, NULL, '3 rounds', 'Fort negates (see text)', 'yes', 'The temperature of the target creature’s blood (or other similar body fluid) begins to rise over the next 3 rounds during the caster’s turn. Each round starting with the first, the target creature attempts a new saving throw at the start of the caster’s turn to resist that round’s effect. A successful save does not end the spell effect, but does prevent that round’s effect. On the round that this spell is cast, the target becomes fatigued. On the next round, as the blood temperature begins to rise, the target’s capillaries burst, dealing 1d6 points of Constitution damage to the target. On the third and final round, the target’s blood begins to boil; the spell deals 1d6 points of damage per caster level (to a maximum of 15d6), and—if the target is still alive—the target becomes exhausted rather than fatigued.', 'a drop of mercury', NULL, false, false),
  ('blood_crow_strike', 'Blood Crow Strike', 'evocation', NULL, 'fire', 4, 'divine', 'cleric/oracle 4', '1 round', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, 'instantaneous', 'none; Spell resistance yes', NULL, 'Your unarmed strikes release blasts of energy in the form of bolts of fire or glowing red crows, which fly instantaneously to strike your target. You can make unarmed strike or flurry of blows attacks against the target as if it were in your threatened area; each successful attack deals damage as if you had hit it with your unarmed strike, except half the damage is fire and half is negative energy (this negative energy does not heal undead). For example, if you are a 14th-level monk, you can use a flurry of blows to attack five times, creating one energy crow for each successful attack against the target, and dealing 2d6 points of damage (plus appropriate unarmed strike modifiers) with each crow.', NULL, NULL, false, false),
  ('blood_in_the_water', 'Blood in the Water', 'necromancy', 'emotion', NULL, 2, 'divine', 'cleric 2, psychic 2, sorcerer/wizard 2', '1 standard action', '20 ft.', NULL, '20-ft.-radius emanation centered on you', NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'As part of the casting of this spell, you must deal 1 point of piercing or slashing damage to yourself to release your blood. This causes you to take 1 point of bleed damage. While the spell is in effect, all sharks, feeders in the depths, and creatures with the blood frenzy ability in the area gain a +2 bonus to Strength and Constitution and take a –2 penalty to AC. This is treated as blood frenzy for the purposes of other feats and effects, and doesn’t stack with the effects of actual blood frenzy. If you cease bleeding, the spell immediately ends.---', NULL, NULL, true, false),
  ('blood_mist', 'Blood Mist', 'conjuration', 'creation', 'poison', 8, 'divine', 'druid 8, shaman 8; Mystery lunar 8', '1 standard action', 'medium (100ft. +10ft./level)', NULL, '60-ft. radius', NULL, '1 minute/level', 'Fortitude negates (see text); Spell resistance yes', NULL, 'This spell summons forth a misty cloud of rust-red toxic algae. Any creature within the mist is coated by it, turning the creature the same reddish color. All targets within the mist gain concealment. Any creature within the mist must save or take 1d4 points of Wisdom damage and become enraged, attacking any creatures it detects nearby (as the “attack nearest creature” result of the confused condition). An enraged creature remains so as long as the spell is in effect. A creature only needs to save once each time it is within the mist (though leaving and returning requires another save).', 'a pinch of dried red algae', NULL, false, false),
  ('blood_money', 'Blood Money', 'transmutation', NULL, NULL, 1, 'arcane', 'magus 1, sorcerer/wizard 1, witch 1', '1 swift action', 'personal', NULL, NULL, NULL, 'Instantaneous', NULL, NULL, 'You cast blood money just before casting another spell. As part of this spell’s casting, you must cut one of your hands, releasing a stream of blood that causes you to take 1d6 points of damage. When you cast another spell in that same round, your blood transforms into one material component of your choice required by that second spell. Even valuable components worth more than 1 gp can be created, but creating such material components requires an additional cost of 1 point of Strength damage, plus a further point of damage for every full 500 gp of the component’s value (so a component worth 500–999 gp costs a total of 2 points, 1,000–1,500 costs 3, etc.). You cannot create magic items with blood money.', NULL, NULL, false, false),
  ('blood_of_the_martyr', 'Blood of the Martyr', 'necromancy', NULL, NULL, 2, 'divine', 'cleric/oracle 2, inquisitor 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'You cause the target to bleed from every orifice, and her organs and blood become suffused with positive energy. If the subject fails her Fortitude save, she takes 1d6 points of bleed damage per 4 caster levels (to a maximum of 4d6 at 16th level) when you cast this spell. Any creature that takes a full-round action to sup the blood of the bleeding subject heals a number of hit points equal to twice as many as the subject lost that round due to the bleed effect. The subject must be willing or helpless to sup her blood, which provokes attacks of opportunity. Only one creature can be healed in this way per round. The subject can lick her own wounds in this way to regain half as many hit points as she lost that round. If the bleeding effect is stopped or the spell’s duration ends, the subject’s blood no longer heals those who drink it, though in the latter case the subject continues to bleed until the bleeding is stopped via magical healing or a successful DC 15 Heal check.', NULL, NULL, false, false),
  ('blood_rage', 'Blood Rage', 'enchantment', 'compulsion', 'mind-affecting', 2, 'divine', 'adept 3, bard 2, cleric 3, sorcerer/wizard 3', '1 standard action', 'close (25 ft. + 5 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'The targets of this spell become angrier as they fight, the pain of their wounds fueling their strength. An affected creature gains a cumulative +2 morale bonus to Strength and a cumulative -1 penalty to AC for every 5 points of damage it takes (maximum +10 Strength, -5 AC) for the duration of the spell. These bonuses last until the spell expires or the target falls unconscious.', 'a drop of blood from each creature to be affected', NULL, false, false),
  ('blood_salvation', 'Blood Salvation', 'abjuration', NULL, NULL, 3, 'arcane', 'bloodrager 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D; see below)', NULL, NULL, 'While under the effect of this spell, you’re immune to any damaging area spells you cast. You can dismiss this spell as an immediate action when you are caught within the area of someone else’s damaging area spell; if you do, you’re immune to that particular casting of that spell as well. If you have the blood casting class feature, you can cast this spell as a swift action instead of a standard action while you’re in a bloodrage.', NULL, NULL, false, false),
  ('blood_scent', 'Blood Scent', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 3, antipaladin 2, bloodrager 3, cleric 3, druid 3, inquisitor 3, psychic 3, ranger 2, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'You greatly magnify the target’s ability to smell the presence of blood. The target is considered to have the scent universal monster ability, but only for purposes of detecting and pinpointing injured creatures (below full hit points). Creatures below half their full hit points or suffering bleed damage are considered strong scents for this ability.', NULL, NULL, false, false),
  ('blood_sentinel', 'Blood Sentinel', 'transmutation', NULL, NULL, 3, 'arcane', 'alchemist 3, sorcerer/wizard 3', '1 standard action', 'touch', 'one animal sculpture', NULL, NULL, '10 minutes/level', 'none', 'no (harmless)', 'After casting this spell, you pour a few drops of your blood and saliva into the mouth of the animal sculpture material component, temporarily giving it life. The animal is bonded to you as if it were a familiar, and it has the abilities of a familiar (use your caster level as your effective wizard level to determine its abilities), but it does not grant you the Alertness feat or the special ability of its animal type. If your blood sentinel is slain, you take 2 points of Intelligence drain and the blood sentinel’s body becomes a destroyed statue. This spell has no effect if you already have a familiar or another blood sentinel.', 'a life-sized animal sculpture of a familiar made of clay, cloth, stone, or wood, plus mandrake root worth 25 gp', NULL, false, true),
  ('blood_song', 'Blood Song', 'evocation', NULL, NULL, 4, 'arcane', 'bard 4', '2 minutes', 'touch', 'creature touched; see text', NULL, NULL, '1 day or until discharged (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell functions as imbue with spell ability, with the following exceptions: only bard spells of the conjuration (healing), enchantment, and transmutation schools can be transferred; the imbued spells last for 1 day; and the subject isn’t beholden to any principles regarding the imbued spells’ use.', 'the caster’s blood', NULL, false, false),
  ('blood_tentacles', 'Blood Tentacles', 'necromancy', NULL, NULL, 4, 'divine', 'antipaladin 4, cleric 5, shaman 5, sorcerer/wizard 5, summoner 4, witch 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'no', 'You smear a handful of your own blood across your chest, causing one writhing tentacle per caster level to burst forth. You can direct these tentacles to attack a single creature within 15 feet as a standard action, or one creature per 5 caster levels as a full-round action. Each tentacle has an attack bonus equal to your base attack bonus plus either your Constitution or Charisma bonus (whichever is higher). Each tentacle deals 2d6 points of damage, and a tentacle collapses into dried blood on a successful hit, granting you a number of temporary hit points equal to the damage dealt. You can’t gain more temporary hit points than your maximum number of hit points. These temporary hit points disappear after 1 hour.', 'a fresh handful of the caster’s blood', NULL, false, false),
  ('blood_ties', 'Blood Ties', 'necromancy', NULL, 'evil', 4, 'divine', 'antipaladin 4, cleric 5, druid 5, inquisitor 5, psychic 5, shaman 5, witch 5', '1 standard action', 'unlimited (see text)', 'two living creatures', NULL, NULL, '1 day/level (D)', 'Will negates (see text)', 'no', 'One of the targets of this spell must be a hostage—a bound, pinned, or helpless creature within your reach (though the spell doesn’t end if the hostage later moves beyond your reach). The second target must be a member of the first target’s family. If neither creature successfully saves against the spell, the second target also takes any damage conferred to the hostage, provided both are still alive, to a maximum of 10 points of damage per caster level per day (damage beyond that necessary to kill the first target does not transfer). This transferred damage is typeless and ignores the second creature’s damage reduction and resistances. If either target succeeds at the saving throw, you can never attempt to exploit the connection between these particular two creatures again. The connection between your targets weakens when the two are less familiar with one another. Each target gains a +2 bonus on its save if the two are distant relations or related by marriage. Each target takes a –2 penalty on its save if the two targets are parent and child or siblings.', NULL, 'a small length of crimson string', false, false),
  ('blood_transcription', 'Blood Transcription', 'divination', NULL, 'evil', 2, 'arcane', 'alchemist 2, magus 2, witch 2, wizard 2', '1 standard action', 'touch', 'one dead spellcaster', NULL, NULL, '24 hours', 'none; Spell resistance no', NULL, 'By consuming 1 pint of blood from a spellcaster killed within the last 24 hours, you can attempt to learn a spell that spellcaster knew. Select one spell available to the dead spellcaster (this must be a spell on your spell list); you gain the knowledge of this spell for 24 hours. During this time, you may write it down (or teach it to your familiar, if you are a witch) using the normal rules for copying a spell from another source. Once you have learned it, you may prepare the spell normally.', NULL, NULL, false, false),
  ('bloodbath', 'Bloodbath', 'necromancy', NULL, NULL, 1, 'divine', 'antipaladin 1, bloodrager 1, cleric 2, inquisitor 2, medium 1, psychic 2, sorcerer/wizard 2, spiritualist 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./level)', 'up to one living creature/level, no two of which can be more than 30 feet apart', NULL, NULL, '1 round/level (D)', 'Fort negates', 'yes', 'You cut yourself with the dagger, dealing yourself 1d6 points of bleed damage. So long as you keep taking this bleed damage, your targets each bleed for 1d6 points of damage at the beginning of their turns. The bleed damage on any target ends if that target receives magical healing, or if your bleed damage ends for any reason. This spell has no effect if you’re immune to bleed damage or can otherwise reduce or ignore the bleed damage to yourself.', NULL, 'a ceremonial dagger', false, false),
  ('bloodhound', 'Bloodhound', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 3, inquisitor 2, ranger 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 hour/level', NULL, NULL, 'You gain the scent special quality, including the ability to track by scent. You receive a +8 competence bonus on Perception checks involving smell and a +4 competence bonus on Survival checks to track using scent. You take a -4 penalty on saving throws against odor-related effects such as the stench ability and stinking cloud. A creature under the effects of bloodhound can detect poison by scent with a DC 20 Perception check.', 'a drop of blood and a pinch of cinnamon', NULL, false, false),
  ('bloodstone_mirror', 'Bloodstone Mirror', 'abjuration', NULL, NULL, 5, 'divine', 'cleric 7, occultist 5, witch 7', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level', NULL, NULL, 'This spell reflects any attempts to steal your free will. Whenever you are exposed to a mind-affecting effect or a spell that would otherwise give another creature control of your actions (such as control undead), you can dispel this effect as an immediate action to redirect the spell to a creature within 30 feet. The affected creature must attempt a save against the original DC of the triggering effect. On a failure, it is subject to the effects of the triggering spell, with the exception that you are treated as the original caster (statistics determined by caster level are still calculated according to its original caster). The target creature applies any spell resistance or immunities it has normally. You can have only one instance of this spell active at a time.', 'a red bloodstone worth 500 gp', NULL, false, true),
  ('bloodsworn_retribution', 'Bloodsworn Retribution', 'necromancy', NULL, NULL, 4, 'divine', 'cleric/oracle 6, paladin 4, ranger 4', '1 round', 'personal', 'you', NULL, NULL, 'special (see text)', NULL, NULL, 'When you cast this spell, you cut yourself and swear an oath of retribution on your own blood. You decide how much damage you want to take from this attack, up to 25 points. This damage cannot be healed for as long as the spell is in effect. Anytime you perform an attack, save, or check that is directly related to the oath and brings you closer to the fulfillment of that oath, you gain a morale bonus to that roll equal to the number of hit points of damage you took from the oath divided by 5. The GM is the final arbiter over whether or not an action qualifies for this bonus. When you fulfill the oath (or choose to forsake it), the spell ends, and the lost hit points can be healed as normal.', 'your blood', NULL, false, false),
  ('bloody_arrows', 'Bloody Arrows', 'necromancy', NULL, NULL, 3, 'divine', 'antipaladin 3, inquisitor 3, magus 3, ranger 3, shaman 4, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one willing creature', NULL, NULL, '1 round/level', 'none (harmless)', 'no (harmless)', 'Whenever this spell’s target hits a creature with a ranged weapon that successfully deals piercing or slashing damage, the struck creature takes 1 point of bleed damage. Unlike most bleed damage, the bleed damage dealt by the subject of this spell is cumulative up to an amount equal to 1/2 your caster level (to a maximum of 5 points of bleed damage at 10th level).', NULL, NULL, false, false),
  ('bloody_claws', 'Bloody Claws', 'necromancy', NULL, NULL, 3, 'divine', 'druid 4, ranger 3', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'You give a creature the ability to deal bleed damage when making natural attacks so long as the attack deals slashing or piercing damage. This bleed damage for each attack is equal to one-half your caster level (limited to the creature’s maximum damage with that attack), though bleed damage does not stack. When two or more attacks deal bleed damage, take the worse effect.', NULL, NULL, true, false),
  ('bloody_tears_and_jagged_smile', 'Bloody Tears and Jagged Smile', 'necromancy', NULL, NULL, 2, 'divine', 'arcanist 2, cleric/oracle 2, sorcerer/wizard 2, warpriest 2', '1 standard action', 'personal and see text', 'you and see text', NULL, NULL, '10 minutes/level', 'none', 'yes', 'Your eyes turn black and weep blood, and your teeth become jagged fangs. You gain a bite attack (1d3 points of damage if you are Small, 1d4 points of damage if you are Medium). You gain a +4 profane bonus on Intimidate checks and on your spell DCs for spells with the fear descriptor. You perceive creatures as if using deathwatch.', NULL, NULL, false, false),
  ('blot', 'Blot', 'transmutation', NULL, NULL, 3, 'divine', 'bard 3, cleric 3, sorcerer/wizard 3', '1 standard action', 'close (25 ft. + 5 ft/2 levels)', NULL, '10 ft.-radius burst', NULL, '24 hours', 'Will negates (object)', 'yes (object)', 'This spell reduces all types of writing and other recognizable symbols found on any sort of surface within range into illegible smears. It affects books, carvings on stone, or even tattoos with equal ease. It does not affect writing that is not actually on a surface, such as an illusion, projection, reflection, or anything similar. Spellbooks and magical items that contain writing (such as scrolls) gain a saving throw to resist the effects of this spell. Against magical writing created by spell effects (such as glyphs of warding or symbols), blot instead functions as a dispel magic spell capable of targeting all such spell effects in the area. This spell has no effect on writing found on artifacts or similarly unique surfaces.', 'a bit of cloth made wet with saliva', NULL, false, false),
  ('blur', 'Blur', 'illusion', 'glamer', NULL, 2, 'arcane', 'alchemist 2, bard 2, magus 2, psychic 2, sorcerer/wizard 2, summoner/unchained summoner 2; Bloodline destined 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level (D)', 'Will negates (harmless)', 'yes (harmless)', 'The subject’s outline appears blurred, shifting, and wavering. This distortion grants the subject concealment (20% miss chance).', NULL, NULL, false, false),
  ('blurred_movement', 'Blurred Movement', 'illusion', 'glamer', NULL, 1, 'arcane', 'alchemist 1, bard 1, bloodrager 1, magus 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1; Mystery shadow 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'This spell functions as blur, except that the blurring occurs only when you move at least 10 feet on your turn and ceases at the end of your movement. It is therefore mainly used to protect against attacks on your turn, such as attacks of opportunity. If you move at least twice your speed on your turn, the blurring lasts until the start of your next turn.', NULL, NULL, false, false),
  ('body_capacitance', 'Body Capacitance', 'transmutation', NULL, 'electricity', 1, 'arcane', 'alchemist 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level or until discharged (see text)', NULL, NULL, 'If you take electricity damage while this spell is active, some of the energy is stored on your skin, as with holding the charge on a touch spell. You can release this stored electricity by making a melee touch attack. You gain a +3 bonus on the attack roll if your opponent is wearing metal armor, is carrying a metal weapon, or is made of metal. The target of your touch attack is dealt electricity damage equal to half the amount of electricity damage you took after you cast this spell (for example, if you saved for half damage against a lightning bolt and took only 15 points of electricity damage, your next touch attack deals 7 points of electricity damage). This spell is discharged once you hit with a melee touch attack to deliver its damage. If you take electricity damage multiple times while this spell is active, use the largest amount of electricity damage you took to determine your touch attack damage.', 'an iron coil', NULL, false, false),
  ('body_double', 'Body Double', 'illusion', 'glamer', NULL, 2, 'arcane', 'bard 2, bloodrager 2, magus 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'two creatures; see text', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'Upon casting this spell, choose a primary target and a secondary target, both of which must be within range. If the primary target fails or forfeits its saving throw, its appearance, scent, sounds, and mannerisms change to match those of the secondary target.', 'two glass beads', NULL, false, false),
  ('boiling_blood', 'Boiling Blood', 'transmutation', NULL, NULL, 2, 'divine', 'bard 2, bloodrager 2, cleric/oracle 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, 'concentration + 1 round/level (D)', 'Fortitude negates (see text); Spell resistance yes', NULL, 'The blood of the targeted creatures begins to boil. If a target fails its save, it takes 1 point of fire damage per round. This spell has no effect on creatures that don’t have blood.', NULL, NULL, false, false),
  ('bolt_of_glory', 'Bolt of Glory', 'evocation', NULL, 'good', 6, 'arcane', 'glory 6', '1 standard action', 'close (25 ft. + 5 ft./level)', NULL, NULL, 'ray', 'instantaneous', 'none', 'yes', 'You fire a ray of positive energy. A creature struck takes varying damage, depending on its nature and home plane of existence.', NULL, NULL, true, false),
  ('bolts_of_bedevilment', 'Bolts of Bedevilment', 'enchantment', NULL, 'mind-affecting', 5, 'arcane', 'madness 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'ray', '1 round/level', 'Will negates', 'yes', 'You can fire one ray per round that dazes one living creature for 1d3 rounds.', NULL, NULL, false, false),
  ('bomber_s_eye', 'Bomber’s Eye', 'transmutation', NULL, NULL, 1, 'arcane', 'alchemist 1', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', NULL, NULL, 'This extract allows you to throw weapons farther and more accurately. While this extract is in effect, increase the range of any thrown weapon by 10 feet. In addition, you receive a +1 insight bonus on attack rolls made with thrown weapons.', NULL, NULL, false, false),
  ('bone_fists', 'Bone Fists', 'necromancy', NULL, NULL, 2, 'divine', 'bloodrager 2, cleric 2, druid 2, psychic 2, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level', 'none (harmless)', 'no', 'The bones of your targets’ joints grow thick and sharp, protruding painfully through the skin at the knuckles, elbows, shoulders, spine, and knees. The targets each gain a +1 bonus to natural armor and a +2 bonus on damage rolls with natural weapons, and they are treated as having armor spikes, with which they are proficient.', 'the knucklebone of a dire animal', NULL, false, false),
  ('bone_flense', 'Bone Flense', 'transmutation', NULL, NULL, 2, 'divine', 'bloodrager 2, cleric 3, druid 3, inquisitor 3, magus 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'Choose a creature that you can see. When that creature is struck by a weapon wielded by a member of the Crimson Assassins, a sawtooth sabre, or by the claw of a giant mantis, the bone nearest to the wound instantly sprouts jagged, razor-sharp spurs that flense the muscle and flesh from the inside out unless the target succeeds at a Fortitude save. The creature takes 1d6 points of piercing damage per caster level. While the bone returns to normal immediately after dealing damage, the creature takes 1d4 points of bleed damage for 1 round per 2 caster levels. The victim is sickened by the pain for the duration of the bleeding. If the target creature has no bones, this spell has no effect.', NULL, NULL, false, false),
  ('boneshaker', 'Boneshaker', 'necromancy', NULL, NULL, 1, 'divine', 'antipaladin 1, cleric 2, inquisitor 2, sorcerer/wizard 2, spiritualist 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature or undead creature with a skeleton', NULL, NULL, 'instantaneous', 'Fortitude partial or negates (see text)', 'yes', 'By using a bone fetish like a marionette, you take control of a target creature’s skeleton. This has a variety of effects depending on whether the target is living or undead.', NULL, 'human-shaped fetish made of bones', false, false),
  ('boneshatter', 'Boneshatter', 'necromancy', NULL, NULL, 4, 'divine', 'arcanist 4, cleric/oracle 5, sorcerer/wizard 4, warpriest 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one corporeal creature or object', NULL, NULL, 'instantaneous and 1 minute/level (see text)', 'Fortitude partial (see text)', 'yes', 'The target’s bones (or exoskeleton) splinter, dealing 1d6 points of damage per caster level (maximum 15d6) to the target, which is also exhausted for 1 minute per caster level from the pain and exertion of the transformation.', 'a broken bone', NULL, false, false),
  ('book_ward', 'Book Ward', 'abjuration', NULL, NULL, 2, 'divine', 'bard 2, cleric/oracle 2, sorcerer/wizard 2', '1 standard action', 'touch', 'one touched object of up to 10 pounds/level', NULL, NULL, '1 day/level or until discharged (see text)', 'Will negates', 'Yes (harmless)', 'As protection from energy, except as noted above and that the spell only protects against acid and fire damage. While the energy protection remains, the item is also completely waterproof (this protection extends to other liquids as well, such as alcohol and oil).', 'a drop of clear oil', NULL, true, false),
  ('borrow_corruption', 'Borrow Corruption', 'transmutation', NULL, 'evil', 2, 'divine', 'antipaladin 2, cleric 4, druid 4, medium 2, occultist 3, psychic 4, shaman 4, witch 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level (D)', 'none', 'no', 'You touch a creature with at least one manifestation from a corruption. You temporarily gain any stains and gifts that corruption grants to the creature, and the creature retains them. If the gifts have limited uses, you count as having no uses remaining. You take 1d3 points of Wisdom drain whenever you cast this spell.', 'a dirty scrap of a good priest’s raiment', NULL, false, false),
  ('borrow_fortune', 'Borrow Fortune', 'evocation', NULL, NULL, 3, 'divine', 'medium 3, oracle 3, psychic 3; Subdomain fate 3', '1 immediate action', 'personal', NULL, NULL, NULL, 'instantaneous; see text', NULL, NULL, 'When you make a d20 roll, you may choose to immediately cast this spell to reroll that die before success or failure is known, keeping the more favorable result. For the next two rounds following your casting of the spell, you must roll two dice each time a d20 roll is called for, keeping the less favorable result.', NULL, NULL, false, false),
  ('borrow_skill', 'Borrow Skill', 'transmutation', NULL, NULL, 1, 'arcane', 'bard 1, psychic 1; Subdomain cooperation 1', '1 standard action', 'touch', NULL, NULL, NULL, 'up to 1 round/level (see description)', 'Will negates (harmless)', 'yes (harmless)', 'You borrow one of the target’s known skills. After touching the subject, you can make a single check with the chosen skill using the subject’s skill ranks, but modified by your own key ability.', NULL, NULL, false, false),
  ('bouncing_bomb_admixture', 'Bouncing Bomb Admixture', 'transmutation', NULL, NULL, 3, 'arcane', 'alchemist 3', '1 swift action', 'personal', 'you', NULL, NULL, '1 round', 'Will negates (harmless)', 'no', 'Upon drinking an extract created with this formula, you make a significant change to your magical reserve that modifies the nature of the next bomb you create and throw during this extract’s duration. This effect on your magical reserve has no effect on any discoveries that you use to modify your bombs, but you can only have one admixture effect (a formula with ‘bomb admixture’ in its title) active at a time. If you drink another bomb admixture, the effects of the former bomb admixture end and the new one becomes active.', NULL, NULL, false, false),
  ('bouncy_body', 'Bouncy Body', 'transmutation', NULL, NULL, 1, 'arcane', 'alchemist 1, bloodrager 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', NULL, NULL, 'The target’s flesh becomes flexible and rubbery.', NULL, NULL, false, false),
  ('bountiful_banquet', 'Bountiful Banquet', 'conjuration', 'creation', NULL, 4, 'divine', 'bard 4, cleric 4, druid 4, shaman 4', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'feast for two creatures/level', '1 hour; see text', 'none', 'no', 'You conjure a beautiful and delicious feast with hors d’oeuvres, four courses worth of food, and plentiful drink. The food appears on ornate serving trays or in exquisite covered tureens, as appropriate to each type of dish. Place settings and serving utensils also appear—enough for each creature that will participate in the feast—along with elegant tablecloths and table linens. The spell doesn’t create furniture, but the feast does adapt to appear on top of existing tables (or similar objects in the environment).', 'a turkey bone', NULL, false, false),
  ('bow_spirit', 'Bow Spirit', 'conjuration ;  Level ranger 4', 'creation', NULL, 9, 'arcane', NULL, '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', NULL, NULL, 'A bow spirit is a shapeless force that hovers about you, taking ammunition from your quiver and firing it. For as long as the bow spirit lasts, you can spend a swift action to direct the bow spirit to fire an arrow or a bolt at a target of your choice, as if the bow spirit were firing the necessary ranged weapon. The bow spirit uses your base attack bonus plus your Dexterity modifier, as well as any bonuses and effects from feats you have that affect ranged attacks, or bonuses from the ammunition it uses.', NULL, NULL, true, false),
  ('bowstaff', 'Bowstaff', 'transmutation', NULL, NULL, 1, 'divine', 'inquisitor 1, paladin 1, ranger 1', '1 swift action', 'personal', 'one weapon (bow)', NULL, NULL, '1 round/level (D)', 'Will negates (harmless, object)', 'yes (harmless, object)', 'The bow that is touched takes on the rigidity and toughness of forged steel, allowing it to be used as a melee weapon. The spell allows a shortbow to be used as a club or a longbow to be used as a quarterstaff, although the bow retains its normal hit points and hardness. The bow’s enhancement bonus, if any, applies on melee attack and damage rolls. Additional weapon special weapon qualities also apply to melee attacks if such qualities can be added to a melee weapon.', NULL, NULL, false, false),
  ('brand', 'Brand', 'transmutation', NULL, 'curse', 0, 'divine', 'inquisitor 0', '1 standard action', 'touch', NULL, NULL, NULL, '1 day/level', 'Fortitude negates', 'yes', 'Brand etches an indelible rune or mark of no more than 6 characters onto a creature, inflicting 1 point of damage. The mark may be placed on any exposed portion of the creature, typically the head or forearm. A brand can be hidden by clothing or removed by scraping it away (causing 1d6 points of damage), though the brand returns if the damage is healed.', NULL, NULL, true, false),
  ('brand_of_conformity', 'Brand of Conformity', 'transmutation', NULL, 'curse', 1, 'divine', 'inquisitor 1', '1 round', 'touch', 'creature touched', NULL, NULL, '1 day/level', 'Fort negates', 'yes', 'This spell etches the symbol of a nation, organization, or order on the target, dealing 1 point of damage. The mark can be placed on any exposed portion of the creature, typically the head or forearm. While branded in this way, the recipient loses the ability to speak or understand its racial language and the language of its homeland or primary culture (if these are different). For example, an elf raised among a primitive tribe would lose Elven and the tribal language (if she knew both those languages), while a halfling raised among dwarves would lose both Halfling and Dwarven (if she knew both those languages). A gnome raised among gnomes would lose Gnome, but no other language. This spell never suppresses Common or Undercommon, nor does it prevent spellcasting, though it may prevent a target from speaking intelligibly if it suppresses all of the target’s languages. A brand of conformity can be hidden beneath clothing or removed by scraping it away (the latter deals 1d6 points of damage, though the brand returns if that damage is healed). In any event, the language-suppression element of a brand of conformity continues to function even when hidden or scraped away.', NULL, NULL, true, false),
  ('brand_of_hobbling', 'Brand of Hobbling', 'transmutation', NULL, 'curse', 2, 'divine', 'inquisitor 2', '1 round', 'touch', 'creature touched', NULL, NULL, '1 day/level', 'Fort negates', 'yes', 'This spell etches a symbol of chains, a particular prison, or a lawful institution on the target, dealing 1d6 points of damage. The mark can be placed on any exposed portion of the creature, typically on the head or forearm. While the recipient is branded in this way, all of its movement speeds are reduced by half (rounded down to the next 5-foot increment). A brand of hobbling can be hidden by clothing or removed by scraping the brand away (the latter deals 1d6 points of damage, though the brand returns if that damage is healed), but in either case the effects of a brand of hobbling continue to function.', NULL, NULL, true, false),
  ('brand_of_tracking', 'Brand of Tracking', 'transmutation', NULL, 'curse', 4, 'divine', 'inquisitor 4', '1 round', 'touch', 'creature touched', NULL, NULL, 'permanent', 'Fort negates', 'yes', 'This spell etches the symbol of an eye or a lawful institution on the target, dealing 1d6 points of damage. The mark can be placed on any exposed portion of the creature, typically the head or forearm. While the target is branded in this way, twice per day as a standard action, you can instantly determine in what direction and how far away the target is, as long as it is within a range equal to 1 mile per your caster level. If the target travels beyond this range or to another plane, you cannot gain information about the recipient’s location. Similarly, if the target becomes warded by a spell or effect that thwarts divination spells (such as nondetection) or moves into such an area (such as one created by antimagic field), you cannot gain information about the target’s location. This effect otherwise works as a locate creature spell that lasts for 1 minute per caster level. It can be fooled by mislead but not by polymorph.', NULL, NULL, true, false),
  ('break', 'Break', 'transmutation', NULL, NULL, 1, 'arcane', 'bloodrager 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Fortitude negates (object)', 'yes (object)', 'You can attempt to break or at least damage any one Medium or smaller object within range. If the target fails its Fortitude Saving Throw, it gains the broken condition. If cast on a broken item, that item is destroyed on a failed save.', 'a twig', NULL, false, false),
  ('break_enchantment', 'Break Enchantment', 'abjuration', NULL, NULL, 4, 'divine', 'bard 4, cleric/oracle 5, inquisitor 5, paladin 4, shaman 5, sorcerer/wizard 5, witch 5; Domain liberation 5, luck 5; Subdomain restoration 5; Bloodline destined 5; Mystery godclaw 5, spellscar 5', '1 minute', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'see text', 'no', 'This spell frees victims from enchantments, transmutations, and curses. Break enchantment can reverse even an instantaneous effect. For each such effect, you make a caster level check (1d20 + caster level, maximum +15) against a DC of 11 + caster level of the effect. Success means that the creature is free of the spell, curse, or effect. For a cursed magic item, the DC is equal to the DC of the curse.', NULL, NULL, false, false),
  ('breath_of_life', 'Breath of Life', 'conjuration', 'healing', NULL, 5, 'divine', 'cleric/oracle 5, shaman 5; Domain healing 5; Mystery life 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Will negates (harmless) or Will half, see text', 'yes (harmless) or yes, see text', 'This spell cures 5d8 points of damage + 1 point per caster level (maximum +25).', NULL, NULL, false, false),
  ('brightest_light', 'Brightest Light', 'evocation', NULL, 'light', 4, 'divine', 'bard 4, cleric 4, druid 4, inquisitor 4, magus 4, occultist 4, paladin 4, ranger 4, shaman 4, sorcerer/wizard 4', NULL, NULL, NULL, NULL, NULL, '1 hour/level (D)', NULL, NULL, 'This spell functions as daylight, except it lasts longer. In addition, as a swift action once during the spell’s duration, you can will the light to try to end a magical darkness effect located within 60 feet of the light this spell emits. Attempt a dispel check (1d20 + your caster level), with a DC equal to 11 + the caster level of the darkness effect. If you succeed, the darkness effect ends. Regardless of whether you are successful, the light from this spell dims to the brightness of a torch for the spell’s remaining duration.', NULL, NULL, false, false),
  ('brightest_night', 'Brightest Night', 'transmutation', NULL, NULL, 1, 'divine', 'arcanist 1, bard 1, cleric 1, druid 1, hunter 1, oracle 1, paladin 1, skald 1, sorcerer 1, warpriest 1, witch 1, wizard 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 hour/level', 'none', 'no', 'You grant low-light vision to the affected creatures. Creatures that already have low-light vision have their existing low-light vision enhanced so that they can see four times as far in conditions of dim light. Creatures within 10 feet of someone under the effects of brightest night do not gain concealment from dim light.', NULL, NULL, false, false),
  ('brilliant_inspiration', 'Brilliant Inspiration', 'evocation', NULL, 'language-dependent', 6, 'arcane', 'bard 6; Subdomain leadership 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level and special (see below)', 'Will negates (harmless)', 'yes (harmless)', 'You open a link between your mind and the subject’s mind, giving advice and encouragement for as long as the spell is in effect. Each time the subject of the spell makes an attack roll, ability check, or skill check, it rolls two d20s and takes the better result. If any roll is a natural 20, the spell’s effect ends-your brilliant advice is spent.', NULL, NULL, false, false),
  ('bristle', 'Bristle', 'transmutation', NULL, NULL, 1, 'divine', 'druid 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level', 'Fortitude negates (harmless)', 'yes', 'You give a creature the ability to redirect a portion of its innate toughness away from its own defense and toward the amount of damage it deals with natural attacks. Each round, as a swift action at the start of its turn, the creature can choose to reduce some or all of its natural armor bonus to AC and gain an enhancement bonus on all damage rolls for natural attacks equal to that amount. The reduction to natural armor, and thus the enhancement bonus on damage rolls, cannot exceed 1 point per 3 caster levels, to a maximum penalty/bonus of -5/+5 at 15th level. A creature cannot reduce its natural armor bonus to less than 0 with this spell.', NULL, NULL, true, false),
  ('brittle_portal', 'Brittle Portal', 'transmutation', NULL, NULL, 2, 'divine', 'antipaladin 2, cleric 2, druid 2, inquisitor 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '5-ft.-radius spread', NULL, '1 round/level', 'Will negates (object)', 'yes (object)', 'This spell weakens the bonds of existence, and reduces the hardness of any non-magical surface within its area of effect by 2 per caster level. The spell is centered on a flat surface chosen by the caster, and the hardness reduction effect persists for the duration of the spell.', NULL, NULL, false, false),
  ('brow_gasher', 'Brow Gasher', 'necromancy', NULL, NULL, 2, 'divine', 'bloodrager 2, inquisitor 2, magus 2, ranger 2, sorcerer/wizard 2', '1 standard action', 'touch', NULL, 'one slashing melee weapon touched', NULL, '1 round/level or until discharged', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You imbue a slashing melee weapon with the ability to deal a gruesome head wound. When the target weapon hits a living creature, in addition to the normal effects of that hit, the wielder can discharge this spell as a free action to open a gash on the target’s forehead that deals bleed damage equal to half your caster level. At the start of each of the target’s turns, when it takes bleed damage, it also takes a cumulative –1 penalty on all attack rolls. When that penalty reaches –3, the target also treats all targets as having concealment (20% miss chance). When the penalty reaches –5, the target is blinded. Stopping the bleed damage ends the effects this spell imposes on the bleeding creature. A target that is immune to bleed damage is also immune to all this spell’s effects.', NULL, NULL, false, false),
  ('build_trust', 'Build Trust', 'divination', NULL, NULL, 1, 'divine', 'bard 2, cleric 2, inquisitor 2, mesmerist 2, paladin 1, psychic 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 day/level; see text', 'Will negates', 'yes', 'You get a sense of the best way to interact with the target in order to encourage positive regard and fellowship toward you.', 'a gold piece', NULL, false, false),
  ('bull_s_strength', 'Bull’s Strength', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, antipaladin 2, bloodrager 2, cleric/oracle 2, druid 2, magus 2, paladin 2, psychic 2, shaman 2, sorcerer/wizard 2, summoner/unchained summoner 2; Domain strength 2; Subdomain rage 2; Bloodline abyssal 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes (harmless)', 'The subject becomes stronger. The spell grants a +4 enhancement bonus to Strength, adding the usual benefits to melee attack rolls, melee damage rolls, and other uses of the Strength modifier.', 'a few hairs, or a pinch of dung, from a bull', NULL, true, false),
  ('bullet_shield', 'Bullet Shield', 'abjuration', NULL, NULL, 2, 'arcane', 'alchemist 2, bloodrager 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'The warded creature gains a +4 deflection bonus to AC against firearm and ranged attacks, with an additional +1 to the bonus for every five caster levels you have (to a maximum of +8 at 20th level). Though the spell is called bullet shield, it also grants this protection from attacks made from firearms with the scatter weapon quality.', 'a bullet', NULL, false, false),
  ('bullet_ward', 'Bullet Ward', 'abjuration', NULL, NULL, 2, 'divine', 'antipaladin 2, bard 2, inquisitor 2, paladin 2, psychic 2, ranger 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level or until discharged', NULL, NULL, 'You toss several adamantine bullets into the air, which then hover protectively nearby and intercept firearm attacks targeting you. The number of bullets protecting you is equal to half your caster level (maximum 4). When an opponent takes a shot at you with a firearm, as an immediate action you can designate a hovering bullet to attempt to block the attack, increasing your AC against that attack by 10. Doing this destroys the adamantine bullet whether or not the attack hits. The spell is discharged when all affected adamantine bullets are destroyed or taken from you. Each adamantine bullet has AC 24, 20 hit points, and hardness 20.', NULL, 'one to four adamantine bullets, each worth 61 gp', false, true),
  ('bungle', 'Bungle', 'enchantment', 'compulsion', NULL, 1, 'arcane', 'psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid', NULL, NULL, 'concentration + 2 rounds or until triggered', 'Will negates; Spell resistance yes', NULL, 'The target takes a –20 penalty on its next attack roll or check that requires a d20 roll. The action must be one deliberately taken by the target on its turn. Creatures with more than 10 HD are unaffected by this spell.', NULL, NULL, false, false),
  ('buoyancy', 'Buoyancy', 'transmutation', NULL, NULL, 2, 'divine', 'bard 2, psychic 2, shaman 2, sorcerer/wizard 2, witch 2', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'up to 1 round/level (see text)', 'Will negates (harmless) or Will negates (object)', 'yes (object)', 'The affected creatures or objects become incredibly buoyant. The affected creatures (including gear and carried objects up to each creature’s maximum load) and objects naturally float on any water at least 1 foot deep. An affected creature that deliberately tries to submerge must succeed at a DC 20 Swim check every round to stay underwater. The spell ends if the creature or object spends at least 1 round on dry land.', NULL, NULL, false, false),
  ('burdened_thoughts', 'Burdened Thoughts', 'enchantment', 'compulsion', 'mind-affecting', 2, 'divine', 'druid 2, shaman 2, sorcerer/wizard 3, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You fill a creature’s mind with the realization of its earthly weight and responsibilities. Disheartened and wearied by these thoughts, the creature gains heavy encumbrance and is unable to fly (if already flying, it must land as soon as possible).', 'a lead bearing wrapped in clay', NULL, false, false),
  ('burn_corruption', 'Burn Corruption', 'evocation', NULL, 'fire, good', 4, 'arcane', 'bloodrager 4, magus 5, sorcerer/wizard 5', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, '10-ft. cube/level (S)', NULL, 'instantaneous', 'Reflex half', 'yes', 'This spell fills the area with violet flames that scour an area clean of life—especially of the corrupted life of the Abyss.', NULL, NULL, false, false),
  ('burning_arc', 'Burning Arc', 'evocation', NULL, 'fire', 2, 'arcane', 'sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Reflex half', 'yes', 'This spell causes an arc of flame to leap from your fingers, burning a number of enemies nearby. It deals 1d6 points of fire damage per caster level (maximum 10d6). For every additional target the discharge arcs to, reduce the number of damage dice by half (rounded down). Therefore, at 9th level, your burning arc deals 9d6 points of fire damage to the primary target, then 4d6 points of fire damage to a secondary target, then 2d6 points of fire damage to an additional target.', NULL, NULL, false, false),
  ('burning_disarm', 'Burning Disarm', 'transmutation', NULL, 'fire', 1, 'divine', 'cleric/oracle 1, druid 1, sorcerer/wizard 1', '1 standard action', 'Short (25 ft. + 5 ft./2 levels)', 'Held metal item of one creature or 15 lbs. of unattended metal', NULL, NULL, 'instantaneous', 'Reflex negates (object, see text)', 'Yes (object)', 'This spell causes a metal object to instantly become red hot. A creature holding the item may attempt a Reflex save to drop it and take no damage (even if it is not their turn), otherwise the hot metal deals 1d4 points of fire damage per caster level (maximum 5d4). Circumstances that prevent the creature from dropping the item (such as a locked gauntlet) mean the creature gets no saving throw. The heat does not harm the item, and it does not get hot enough or last long enough to ignite flammable objects. The item cools to its previous temperature almost instantly. If cast underwater, burning disarm deals half damage and boils the surrounding water.', NULL, NULL, false, false),
  ('burning_entanglement', 'Burning Entanglement', 'evocation', NULL, NULL, 3, 'divine', 'druid 3, hunter 3, ranger 3, shaman 3, witch 3', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, '40-ft.-radius spread', NULL, '1 round/level', 'Reflex negates or partial (see text)', 'no', 'This spell functions as per entangle, except it sets the foliage on fire. A creature that begins its turn entangled by the spell takes 4d6 points of fire damage (Reflex half), and a creature that begins its turn in the area but is not entangled takes 2d6 points of fire damage (Reflex negates). Smoke rising from the vines partially obscures visibility. Creatures can see things in the smoke within 5 feet clearly, but attacks against anything farther away in the smoke must contend with concealment (20% miss chance). When the spell’s duration expires, the vines burn away entirely.', NULL, NULL, true, false),
  ('burning_gaze', 'Burning Gaze', 'evocation', NULL, 'fire', 2, 'divine', 'bloodrager 2, druid 2, magus 2, sorcerer/wizard 2, witch 2; Elemental School fire 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', 'Fortitude negates (see text)', 'yes', 'Your eyes burn like hot coals, allowing you to set objects or foes alight with a glance.', 'eye of a mundane salamander', NULL, true, false),
  ('burning_hands', 'Burning Hands', 'evocation', NULL, 'fire', 1, 'divine', 'bloodrager 1, magus 1, shaman 1, sorcerer/wizard 1, witch 1; Domain fire 1; Bloodline elemental 1; Elemental School fire 1; Mystery flame 1, volcano 1', '1 standard action', '15 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Reflex half', 'yes', 'A cone of searing flame shoots from your fingertips.', NULL, NULL, false, false),
  ('burning_sands', 'Burning Sands', 'conjuration', 'creation', 'earth, fire', 1, 'divine', 'druid 1, ranger 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft. radius', NULL, '1 round/level', 'none', 'no', 'You cause sheets of hot sand to spread over the ground in the area of effect. This layer of sand is 1 foot deep and constantly shifts and churns, transforming the ground in the area into difficult terrain. The sand itself burns, and periodic flames rise from the grit. While these flames cannot ignite objects, they deal 1d4 points of fire damage to any creature that ends its turn in contact with the ground within the area of effect. At the end of the duration, the sand vanishes, leaving no aftereffects (other than damage dealt).', 'a handful of sand', NULL, true, false),
  ('burrow', 'Burrow', 'transmutation', NULL, NULL, 3, 'divine', 'alchemist 3, bloodrager 3, druid 3, ranger 3, sorcerer/wizard 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Will negates (harmless); Spell resistance yes (harmless)', NULL, 'The subject can burrow at a speed of 15 feet (or 10 feet if it wears medium or heavy armor, or if it carries a medium or heavy load) through sand, loose soil, or gravel, or at a speed of 5 feet through stone. Using burrow requires only as much concentration as walking, so the subject can attack or cast spells normally. The burrowing creature cannot charge or run. Loose material collapses behind the target 1 round after it leaves the area. This spell does not give the target the ability to breathe underground, so when passing through loose material, the creature must hold its breath and take only short trips, or else it may suffocate.', NULL, NULL, false, false),
  ('burst_bonds', 'Burst Bonds', 'evocation', NULL, NULL, 1, 'divine', 'inquisitor 1', '1 standard action', 'touch', NULL, NULL, NULL, 'instantaneous', 'Fortitude half (object)', 'yes', 'You blast your restraints with divine wrath, dealing 1d6 points of damage per caster level to the target object (maximum 5d6), ignoring hardness of 10 or less. A Fortitude save halves the damage, although only magical restraints receive a Saving Throw.', NULL, NULL, false, false),
  ('burst_of_adrenaline', 'Burst of Adrenaline', 'transmutation', NULL, NULL, 1, 'arcane', 'mesmerist 1, psychic 1, spiritualist 1', '1 immediate action', 'personal', 'you', NULL, NULL, 'instantaneous', 'none', 'no', 'You draw upon your body’s inner reserves of strength, leaving you winded. When you are about to make a d20 roll based on Strength, Dexterity, or Constitution, you can cast this spell to gain a +8 enhancement bonus to Strength, Dexterity, or Constitution for that roll, but you are fatigued for 1 round afterward.', NULL, NULL, false, false),
  ('burst_of_force', 'Burst of Force', 'evocation', NULL, 'force', 5, 'arcane', 'psychic 5, sorcerer/wizard 5', '1 standard action', NULL, NULL, '20-ft.-radius burst centered on you', NULL, 'instantaneous', 'Fortitude half (see text)', 'yes', 'With a burst of telekinetic force, you deal 1d6 points of force damage per caster level (maximum 15d6 points of damage) to all other creatures in the affected area. A successful Fortitude save reduces the damage taken by half. A creature that fails its Fortitude save must also succeed at a Reflex save or be knocked prone.', NULL, NULL, false, false),
  ('burst_of_glory', 'Burst of Glory', 'enchantment', 'compulsion', 'mind-affecting', 4, 'divine', 'cleric/oracle 5, inquisitor 4, paladin 4', '1 standard action', NULL, NULL, '10-ft.-radius burst, centered on you', NULL, '1 round/level (D; see text)', 'Will negates (harmless)', 'yes (harmless)', 'Allies in the area of this spell at the time of casting gain a +1 sacred bonus on attack rolls and saves against fear effects, plus 1 temporary hit point per caster level (maximum 20). You shine with a white or golden radiance equal to a torch for the spell’s duration, though you can dismiss the glow effect as a free action.', NULL, NULL, true, false),
  ('burst_of_insight', 'Burst of Insight', 'transmutation', NULL, NULL, 1, 'arcane', 'medium 1, mesmerist 1, psychic 1, spiritualist 1', '1 immediate action', 'personal', 'you', NULL, NULL, 'instantaneous', 'none', 'no', 'You plumb the depths of your mind for insight, leaving you momentarily frazzled. When you are about to make a d20 roll based on Intelligence, Wisdom, or Charisma, you can cast this spell to gain a +8 enhancement bonus to Intelligence, Wisdom, or Charisma for that roll, but you are dazed for 1 round afterward.', NULL, NULL, false, false),
  ('burst_of_nettles', 'Burst of Nettles', 'conjuration', NULL, 'acid', 3, 'divine', 'druid 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '10-ft.-radius burst', NULL, 'instantaneous', 'Reflex half; Spell resistance yes', NULL, 'You release a burst of barbed, acid-filled nettles. Creatures caught in the burst take 3d6 points of damage plus 1d6 points of acid damage on the next round. Those that save take half damage from the initial burst and no damage on the next round.', NULL, NULL, false, false),
  ('burst_of_radiance', 'Burst of Radiance', 'evocation', NULL, 'good, light', 2, 'divine', 'cleric 2, druid 2, sorcerer/wizard 2', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, '10-ft.-radius burst', NULL, 'instantaneous', 'Reflex partial', 'yes', 'This spell fills the area with a brilliant flash of shimmering light. Creatures in the area are blinded for 1d4 rounds, or dazzled for 1d4 rounds if they succeed at a Reflex save. Evil creatures in the area of the burst take 1d4 points of damage per caster level (max 5d4), whether they succeed at the Reflex save or not.', 'a piece of flint and a pinch of silver dust', NULL, true, false),
  ('burst_of_speed', 'Burst of Speed', 'transmutation', NULL, NULL, 3, 'divine', 'alchemist 3, antipaladin 3, bloodrager 3, magus 3, medium 3, inquisitor 3, paladin 3, psychic 3, ranger 3', '1 swift actionComponent V', 'personal', 'you', NULL, NULL, 'see text', NULL, NULL, 'Until the end of your turn, you gain a +20-foot bonus to speed (or +10-foot bonus if you are wearing Medium or Heavy armor), your movement does not provoke attacks of opportunity, and you can move through the space of creatures that are larger than you are, but you cannot end your movement this round in a space occupied by a creature.', NULL, NULL, false, false),
  ('burst_with_light', 'Burst With Light', 'evocation', NULL, 'light', 4, 'divine', 'cleric 4, paladin 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/4 levels', 'see text', 'yes', 'The target becomes filled with intense magical light, taking 2d6 points of damage as the light bursts from its wounds and orifices (if the target is an undead creature, it instead takes 2d8 points of damage). In addition, the creature radiates bright light in a 30-foot radius and increases the light level by one step for an additional 30 feet beyond that area—darkness becomes dim light, dim light becomes normal light, and normal light becomes bright light.', NULL, NULL, false, false),
  ('business_booms', 'Business Booms', 'enchantment', NULL, NULL, 3, 'arcane', 'bard 3, sorcerer/wizard 3', '1 standard action', 'touch', 'one building', NULL, NULL, 'see text (D)', 'none', 'no', 'You may cast this spell immediately prior to spending 1 day of downtime to promote a business. The spell is cast on a building you wish to promote, which is magically bestowed with magical decorations and other improvements that make it generally more appealing, and it is treated as seeing increased activity for the spell’s duration. If the spell is cast on a building that you do not promote immediately thereafter, the spell is expended with no effect.', 'promotional materials such as flyers and posters worth 10 gp', NULL, false, true),
  ('cackling_skull', 'Cackling Skull', 'illusion', 'glamer', NULL, 3, 'arcane', 'witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one skull', NULL, NULL, 'permanent until discharged', 'Will negates; Spell resistance yes', NULL, 'This spell functions as magic mouth, except rather than creating an illusory mouth on any surface, it affects a skull. In addition, when the skull’s magic is triggered, it releases wild and unnerving cackles before speaking its message. All creatures that can hear the cackles must save or become shaken for 1d4 rounds.', NULL, NULL, false, false),
  ('cacophonous_call', 'Cacophonous Call', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'bard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You fill your target’s mind with a blaring cacophony of discordant sounds, making it hard for the target to act and concentrate. The creature gains the nauseated condition for the duration of the spell if it fails its Will save.', 'a scrap of sheet music', NULL, false, false),
  ('caging_bomb_admixture', 'Caging Bomb Admixture', 'evocation', NULL, 'force', 6, 'arcane', 'alchemist 6', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'Upon drinking an extract created with this formulae, you make a significant change to your magical reserve that modifies the nature of all bombs you create and throw during this extract’s duration. This effect on your magical reserve has no effect on any discoveries that you use to modify your bombs, but you can only have one admixture effect (formulae with the word “bomb admixture” in its title) active at a time. If you drink another bomb admixture, the effects of the former bomb admixture end and the new one becomes active. When you throw a bomb and hit a direct target, it creates an invisible cubical prison composed of a solid wall of force. The prison is as large as the splash area of the bomb that you threw, and traps any creature that is entirely inside the area. Creatures within the area are caught and contained unless any creature within the splash radius is too big to fit inside, in which case the effect automatically fails. Teleportation and other forms of astral travel provide means for escape, but the force walls extend into the Ethereal Plane, blocking ethereal travel. Like a wall of force, the cage created by the caging bomb admixture resists dispel magic, although a mage’s disjunction still functions. The walls of the cage can be damaged by spells as normal, except for disintegrate, which automatically destroys the cage. The walls of this cage can be damaged by weapons and supernatural abilities, but the cage has a hardness of 20 and a number of hit points equal to 20 per alchemist level. Contact with a sphere of annihilation or a rod of cancellation instantly destroys this cage. When using caging bomb admixture, an alchemist can only have one cage in effect at a time. If the alchemist throws another bomb during the duration of caging bomb admixture, any other cage created by the earlier admixture ends, and a new one is created. When the duration of the caging bomb admixture ends, so does any remaining cage created by this admixture’s effect.', NULL, NULL, false, false),
  ('calamitous_flailing', 'Calamitous Flailing', 'necromancy', NULL, 'curse', 3, 'divine', 'bard 3, cleric 4, mesmerist 3, sorcerer/wizard 4, spiritualist 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level (D)', 'Will negates', 'yes', 'You cause the victim’s attacks to careen wildly, endangering itself and those around it. Your target gains a 25% miss chance on all attack rolls. If an attack misses due to this magical effect, the victim instead targets an ally, or else itself if there are no allies within range of the original attack. Apply the attack roll for the original attack to the new target’s Armor Class to determine if this attack hits. This is a curse effect.', NULL, NULL, false, false),
  ('calcific_touch', 'Calcific Touch', 'transmutation', NULL, 'earth', 4, 'arcane', 'bloodrager 4, sorcerer/wizard 4; Elemental School earth 4', '1 standard action', 'touch', 'creature or creatures touched (up to one per level)', NULL, NULL, '1 round/level', 'Fortitude Partial', 'yes', 'Your touch progressively transmutes the substance of creatures you touch into stone. Once per round, you may deliver a touch attack that inflicts 1d4 points of Dexterity damage and slows the target (as the spell) for 1 round. A successful Fortitude save negates the slow effect but not the ability damage. A target reduced to 0 Dexterity is petrified permanently. Break enchantment, restoration, or stone to flesh can reverse the effects of calcific touch.', NULL, NULL, false, false),
  ('calculated_luck', 'Calculated Luck', 'divination', NULL, NULL, 3, 'divine', 'cleric 3, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', 'none', 'no', 'You are able to use the Path of Numbers to substantially boost your combat preparedness, but your foresight comes at a price.', NULL, NULL, false, false),
  ('call_animal', 'Call Animal', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'druid 1, ranger 1', '1 standard action', 'see description', NULL, NULL, 'one animal whose CR is equal or less than your caster level', '1 hour/level (D)', 'None', 'None', 'This spell calls the nearest wild animal of a particular type you designate (provided the animal’s CR is equal to or less than your caster level) to seek you out. The animal moves toward you under its own power, so the time it takes to arrive depends on how close an animal of the desired type is when you cast the spell. If there is no animal of that type capable of reaching you within the spell’s duration, you are aware of this fact, but the spell is wasted. Knowledge of the local fauna makes this spell more effective, and the GM may permit a Knowledge (nature) skill check (DC 15) to know what animals can be found in an area.', NULL, NULL, true, false),
  ('call_construct', 'Call Construct', 'conjuration', 'teleportation', NULL, 8, 'divine', 'cleric/oracle 8, sorcerer/wizard 8; Elemental School metal 8', '10 minutes', 'touch', 'construct touched', NULL, NULL, 'permanent until discharged', 'none; Spell resistance no', NULL, 'This spell functions as instant summons, except it can only summon a construct you control. For constructs such as golems that are immune to magic, the value of the specially inscribed sapphire must be at least 5,000 gp. For other constructs, a 1,000 gp sapphire suffices.', 'a sapphire worth 1,000 or 5,000 gp; see text', NULL, false, true),
  ('call_lightning', 'Call Lightning', 'evocation', NULL, 'electricity', 3, 'divine', 'druid 3, shaman 3; Domain weather 3; Subdomain catastrophe 3', '1 round', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one or more 30-ft.-long vertical lines of lightning', '1 min./level', 'Reflex half', 'yes', 'Immediately upon completion of the spell, and once per round thereafter, you may call down a 5-foot-wide, 30-foot-long, vertical bolt of lightning that deals 3d6 points of electricity damage. The bolt of lightning flashes down in a vertical stroke at whatever target point you choose within the spell’s range (measured from your position at the time). Any creature in the target square or in the path of the bolt is affected.', NULL, NULL, false, false),
  ('call_lightning_storm', 'Call Lightning Storm', 'evocation', NULL, 'electricity', 5, 'divine', 'druid 5, shaman 5; Subdomain storms 5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like call lightning, except that each bolt deals 5d6 points of electricity damage (or 5d10 if created outdoors in a stormy area), and you may call a maximum of 15 bolts.', NULL, NULL, false, false),
  ('call_spirit', 'Call Spirit', 'conjuration', 'calling', NULL, 3, 'divine', 'cleric 5, medium 3, shaman 5, spiritualist 5', '10 minutes', '10 ft.', NULL, NULL, 'call the spirit of a single deceased humanoid creature', 'concentration', 'Will negates; see text', 'no', 'You attempt to cause the spirit of a specific individual to manifest from its final resting place. You must request the spirit’s presence by speaking its name.', NULL, NULL, false, false),
  ('call_the_godspawn', 'Call the Godspawn', 'conjuration', 'calling', 'chaotic, evil', 9, 'divine', 'cleric/oracle 9, sorcerer/wizard 9, witch 9', '1 week', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, 'instantaneous', 'none', 'no', 'Having attained the highest and most profane form of magical achievement in your god’s service, you are able to call forth his most dreaded creations: the godspawn.', 'bull’s blood, tallow, one or more humanoid victims totaling at least 15 Hit Dice', NULL, true, false),
  ('call_the_void', 'Call the Void', 'evocation', NULL, NULL, 3, 'arcane', 'sorcerer/wizard 3, witch 3; Elemental School void 3*', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', 'Reflex for half; see text', 'yes', 'This spell surrounds you with an aura of nothingness that channels mysterious energies.', NULL, NULL, false, false),
  ('call_weapon', 'Call Weapon', 'transmutation', NULL, NULL, 1, 'divine', 'bard 1, magus 1, ranger 1', '1 swift action', '30 feet', 'one melee weapon wielded by an ally', NULL, NULL, 'instantaneous', NULL, NULL, 'You cause a weapon wielded by an ally within 30 feet to telekinetically fly across the space between you and into your open hand. This extra energy persists in the weapon for the rest of the round, granting you a +2 circumstance bonus on attack rolls and weapon damage rolls made during the same round you cast this spell.', NULL, NULL, false, false),
  ('callback', 'Callback', 'conjuration', 'teleportation', NULL, 2, 'divine', 'shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'long (400 ft. + 40 ft./level)', 'your familiar or spirit animal', NULL, NULL, '10 minutes/level or until expended (see text)', 'Fort negates (harmless)', 'yes', 'If the target takes hit point damage while within range of this spell, it immediately teleports to your space (or adjacent to your space) after the damage is applied. If the target is killed, its corpse teleports instead. Optionally, you can specify a number of points of damage for your familiar to take before the spell takes effect, but you must do so when the spell is cast. Once the familiar has teleported back to you, the spell ends.', 'a crushed grasshopper', NULL, false, false),
  ('calm_air', 'Calm Air', 'abjuration', NULL, 'air', 4, 'divine', 'druid 4, sorcerer/wizard 5, summoner 4', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'cylinder (5-ft./level radius, 40 ft. high)', NULL, '10 minute/level (D)', 'none (object)', 'no (object)', 'This spell calms the air and disperses fog, dust, and other particles. The wind force in the area is reduced in strength by one step per 4 caster levels (to a minimum wind force of light) and clouds are dispersed, although parts of non-magical clouds that extend beyond the area are not affected. If a magical cloud or wind’s point of origin is inside the area of a calm air spell, the whole effect is suppressed; otherwise, only the part inside the area is suppressed. Suppression still counts against the duration of a wind or cloud effect. Magical wind and cloud effects are suppressed only if you succeed at a caster level check (DC 11 + effect’s caster level). You can move the calm air effect by concentrating as a standard action.', NULL, NULL, false, false),
  ('calm_animals', 'Calm Animals', 'enchantment', 'compulsion', 'emotion, mind-affecting', 1, 'divine', 'druid 1, psychic 1, ranger 1, shaman 1; Domain animal 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 min./level', 'Will negates', 'yes', 'This spell soothes and quiets animals, rendering them docile and harmless. Only ordinary animals (those with Intelligence scores of 1 or 2) can be affected by this spell. All the subjects must be of the same kind, and no two may be more than 30 feet apart. The maximum number of HD of animals you can affect is equal to 2d4 + caster level.', NULL, NULL, false, false),
  ('calm_emotions', 'Calm Emotions', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'divine', 'bard 2, cleric/oracle 2, inquisitor 2, psychic 2, shaman 2; Domain charm 2; Subdomain family 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'creatures in a 20-ft.-radius spread', NULL, 'concentration, up to 1 round/level (D)', 'Will negates', 'yes', 'This spell calms agitated creatures. You have no control over the affected creatures, but calm emotions can stop raging creatures from fighting or joyous ones from reveling. Creatures so affected cannot take violent actions (although they can defend themselves) or do anything destructive. Any aggressive action against or damage dealt to a calmed creature immediately breaks the spell on all calmed creatures.', NULL, NULL, true, false),
  ('calm_spirit', 'Calm Spirit', 'necromancy', NULL, NULL, 1, 'divine', 'cleric 2, medium 1, shaman 2, spiritualist 2; Mystery reaper 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one incorporeal undead creature or haunt', NULL, NULL, '1 minute or 1 round/level; see text', 'Will negates or none; see text', 'yes', 'This spell temporarily calms agitated haunts and incorporeal undead such as ghosts. You have no control over the affected creatures, but calm spirit postpones hostile action by the affected spirits for the duration of the spell. Entities so affected cannot take violent actions or do anything destructive, including triggering persistent haunt abilities, though they can defend themselves. Any aggressive action against or damage dealt to a calmed spirit or haunt immediately ends the effect.', NULL, NULL, false, false),
  ('campfire_wall', 'Campfire Wall', 'evocation', NULL, 'fire, light', 2, 'divine', 'bard 3, druid 2, ranger 2, sorcerer/wizard 3; Elemental School fire 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '20-ft.-radius sphere centered on fire source', '2 hours/level; see below (D)', 'none', 'yes', 'You can create a barrier around a fire of at least campfire size that shelters everyone inside so long as the fire continues to burn. The barrier appears as a crackling sphere of light and fire that is clearly visible, providing as much illumination as a torch.', 'ash made from burnt thorns', NULL, true, false),
  ('canopic_conversion', 'Canopic Conversion', 'necromancy', NULL, 'death, evil', 9, 'divine', 'cleric/oracle 9, sorcerer/wizard 9', '1 round', 'close (25 f. + 5 f./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Fortitude half', 'yes', 'This spell eviscerates the target, drawing forth his life essence as well as his internal organs. The target takes 1d6 hit points of damage per caster level (maximum 20d6). If this damage kills the target, the spell pulls his organs into a set of 4 canopic jars and seals them; 1d4 rounds later, the corpse revives as an undead with the dune mummy template.', 'black onyx worth 100 gp per hit die of the target', 'four alabaster canopic jars worth 100 gp each', false, true),
  ('cape_of_wasps', 'Cape of Wasps', 'conjuration', 'summoning', NULL, 4, 'divine', 'druid 4, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'You summon a wasp swarm, which fills your space (up to 5 feet by 5 feet) but does not attack you. The dense cloud of vermin gives you partial concealment against ranged attacks. Any creature that makes a successful melee attack against you takes 2d6 points of swarm damage and poison from the wasp swarm, but is not affected by the swarm’s distraction ability. As a free action on your turn, you may have the swarm cling to you tightly, giving you a fly speed of 20 feet (poor maneuverability); when using the swarm to fly, it does not provide concealment or harm creatures that strike you. You can return the swarm to its protective shape as a free action on your turn.', NULL, NULL, false, false),
  ('carrion_compass', 'Carrion Compass', 'divination', NULL, NULL, 1, 'divine', 'cleric 1, ranger 1, sorcerer/wizard 2, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one undead creature', NULL, NULL, '10 minutes/level', 'Will negates', 'no', 'You animate one of the target’s fetid organs so that it leads you to the undead creature’s most recent controller or the cause of the creature’s undeath. The organ (typically the heart, the brain, or an eyeball) floats in front of you at chest level and slowly leads you to the undead creature’s most recent controller at a rate of 30 feet per round, always staying within your range of vision. If the creature from which the organ originated had no controller, but rather was created deliberately by another creature, the organ instead leads you to that creator. If the undead was animated by an effect or event at a particular location, the organ leads you to that location. If the creature was animated by none of the methods above, if it was self-created, or if the creature’s most recent controller no longer exists, the spell fails. Once the organ is within 10 feet of its intended destination, the spell ends, and the organ falls to the ground.', NULL, NULL, false, false),
  ('carry_companion', 'Carry Companion', 'transmutation', NULL, NULL, 2, 'divine', 'druid 2, paladin 2, ranger 2, sorcerer/wizard 2, witch 2', NULL, 'touch', 'one willing creature touched', NULL, NULL, 'permanent; see text', 'none', 'yes (harmless)', 'You touch an animal or magical beast that has a helpful attitude toward you, instantly transforming the creature into a miniature figurine of stone, small enough to fit into the palm of your hand. Creatures with an attitude of less than helpful will not tolerate this spell, and it automatically fails to work on them.', NULL, NULL, false, false),
  ('carrying_wind', 'Carrying Wind', 'conjuration', NULL, 'air', 3, 'divine', 'druid 3, shaman 3', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'When you cast this spell, a wind spirit envelopes you and carries you with it at your direction. You gain a +10-foot enhancement bonus to your base speed and fly speed while this spell is in effect. If you don’t have a fly speed, you instead gain a fly speed of 10 feet with poor maneuverability. If your caster level is 10th–14th, the enhancement bonus to these speeds is +20 feet (if applicable, your temporary fly speed is 20 feet with average maneuverability). If your caster level is 15th or higher, the enhancement bonus to these speeds is +30 feet (if applicable, your temporary fly speed is 30 feet with average maneuverability).', NULL, NULL, true, false),
  ('carve_passage', 'Carve Passage', 'transmutation', NULL, 'earth', 5, 'divine', 'druid 5, sorcerer/wizard 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'dirt or loose rock in one 5-ft. cube/level', NULL, 'instantaneous', 'see text', 'no', 'You can excavate and move an amount of snow, earth, dust, sand, and loose or packed rocks or ice chunks (each no more than 5 feet in diameter) whose volume fills one 5-foot cube per level. If you are buried, you can open a space around yourself and use any remaining cubes for tunneling. This spell is otherwise similar to expeditious excavation. Carve passage has no effect on earth creatures or solid rock or ice.', NULL, 'a tiny diamond pick worth 500 gp', false, true),
  ('cast_out', 'Cast Out', 'abjuration', NULL, NULL, 3, 'divine', 'inquisitor 3', '1 standard action', 'touch', NULL, NULL, NULL, 'instantaneous', 'Will partial', 'yes', 'With a melee touch attack you blast a single creature and disrupt any magic controlling it. The target takes 2d8 points of damage + 1 point per caster level (maximum +15). In addition, you make a dispel check against any magic jar effect (including a ghost‘s malevolence ability) or enchantment (compulsion) spells on the target creature, starting with the highest level spells and proceeding to lower level spells. Treat this as a targeted dispel magic spell, except cast out can dispel one such spell for every four caster levels you possess. A successful Will save halves the damage and limits the dispelling to a single spell or effect.', NULL, NULL, true, false),
  ('castigate', 'Castigate', 'enchantment', 'compulsion', 'emotion, fear, language-dependent, mind-affecting', 2, 'arcane', 'inquisitor 2; Subdomain judgment 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level or 1 round; see text', 'Will partial', 'yes', 'You compel the target to beg for forgiveness. On a failed save, the target cowers with fear. On a successful save, it is shaken for 1 round. Each round on its turn, a cowering subject may attempt a new save to end the effect. A creature who worships the same god as you takes a -2 penalty on its Saving Throw.', NULL, NULL, true, false),
  ('cat_s_grace', 'Cat’s Grace', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, bard 2, bloodrager 2, druid 2, psychic 2, magus 2, ranger 2, sorcerer/wizard 2, summoner/unchained summoner 2; Subdomain flowing 2; Elemental School wood 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes', 'The transmuted creature becomes more graceful, agile, and coordinated. The spell grants a +4 enhancement bonus to Dexterity, adding the usual benefits to AC, Reflex saves, and other uses of the Dexterity modifier.', 'pinch of cat fur', NULL, false, false),
  ('catatonia', 'Catatonia', 'necromancy', NULL, NULL, 2, 'divine', 'alchemist 2, bard 2, cleric 3, medium 2, mesmerist 2, psychic 3, sorcerer/wizard 3, spiritualist 2, witch 3', '1 standard action', 'touch', 'willing creature touched', NULL, NULL, '1 hour/level (D)', 'none', 'yes', 'You touch the target and place it into a deathlike state that persists for the duration. The target appears to be dead, and any creature that interacts with the target must succeed at a DC 20 Heal check to recognize it is actually alive.', NULL, NULL, false, false),
  ('cause_fear', 'Cause Fear', 'necromancy', NULL, 'emotion, fear, mind-affecting', 1, 'divine', 'antipaladin 1, bard 1, bloodrager 1, cleric/oracle 1, inquisitor 1, psychic 1, shaman 1, sorcerer/wizard 1, witch 1; Domain death 1; Subdomain daemon 1, fear 1; Bloodline abyssal 1; Mystery bones 1, dragon 1, godclaw 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature with 5 or fewer HD', NULL, NULL, '1d4 rounds or 1 round; see text', 'Will partial', 'yes', 'The affected creature becomes frightened. If the subject succeeds on a Will save, it is shaken for 1 round. Creatures with 6 or more HD are immune to this effect. Cause fear counters and dispels remove fear.', NULL, NULL, false, false),
  ('caustic_blood', 'Caustic Blood', 'transmutation', NULL, 'acid', 4, 'divine', 'alchemist 4, bloodrager 4, cleric/oracle 5, druid 4, magus 4, sorcerer/wizard 5, summoner 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'Reflex half or negates; see text', 'no', 'You imbue your blood with corrosive acid.', 'vial of black adder venom', NULL, false, false),
  ('caustic_eruption', 'Caustic Eruption', 'conjuration', 'creation', 'acid', 7, 'arcane', 'sorcerer/wizard 7', '1 standard action', '30 ft.', NULL, '30-ft.-radius burst', NULL, 'instantaneous and 2 rounds; see text', 'Reflex half (see text); Spell resistance no', NULL, 'Acid erupts from your space in all directions, causing 1d6 points of damage per caster level (maximum 20d6) to creatures and unattended objects in the area. On your turn in each of the next 2 rounds, creatures and objects that failed their saves against the initial burst take an additional 1d6 points of acid damage per 2 caster levels (maximum 10d6) unless the acid is neutralized, dispelled, or washed away.', NULL, NULL, false, false),
  ('caustic_safeguard', 'Caustic Safeguard', 'abjuration', NULL, 'acid', 3, 'arcane', 'alchemist 3, bloodrager 3, magus 3, sorcerer/wizard 4', '1 round', 'touch', 'object touched', NULL, NULL, '1 hour/level (D)', 'Reflex half (see text)', 'no', 'You imbue a single object with an acidic protective ward. Any creature other than you that touches the object takes 1d6 points of acid damage per 2 caster levels (maximum 10d6; Reflex half).', 'a thin metal wire and a vial of acid', NULL, false, false),
  ('cauterizing_weapon', 'Cauterizing Weapon', 'transmutation', NULL, NULL, 2, 'divine', 'bard 2, magus 2, ranger 2, sorcerer/wizard 3', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You infuse a weapon with faint but pernicious energy that stymies accelerated healing. Damage dealt by the weapon or ammunition is treated as acid, cold, electricity, and fire, but only for the purpose of negating a creature’s regeneration. The weapon is also treated as silver and cold iron at 8th level and is treated as chaotic, evil, good, and lawful at 11th level for the purpose of negating regeneration.', 'a gobbet of melted wax', NULL, false, false),
  ('cave_fangs', 'Cave Fangs', 'conjuration', 'creation', 'earth', 5, 'divine', 'druid 5, shaman 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one 5-ft. square/level (S); the area must be a stone surface', NULL, '1 day/level or until triggered (D)', 'Reflex half (see below)', 'no', 'You create a magical trap in the area that causes deadly stalactites or stalagmites to lurch out of the floor or ceiling of a stone surface to “bite” an intruder. the magical trap is triggered whenever a Small or larger creature (other than you or your animal companion, familiar, or spirit animal) moves through the affected area. the effect of cave fangs depends on whether you create stalactites or stalagmites (see below). You can place these trapped squares anywhere within the spell’s range; they need not be adjacent to each other, and you can create any mix of stalactites and stalagmites you wish. Cave fangs can be detected and disarmed as per a magical trap with successful DC 30 Perception and Disable Device checks. All trapped squares created by a single casting are linked, and they are all disabled if one of them is. If you place the traps in an area that is occupied by a creature, the spell effect is triggered at the completion of the casting.', 'a sharp gemstone fragment worth 150 gp', NULL, false, true),
  ('celestial_companion', 'Celestial Companion', 'transmutation', NULL, NULL, 1, 'divine', 'druid 2, paladin 1, ranger 2, shaman 2, sorcerer/wizard 2, summoner 1, witch 2', '1 standard action', 'touch', 'animal companion, eidolon, familiar, or mount', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'You bestow divine protection on your companion. The target gains spell resistance equal to 5 plus half your caster level against spells and spell-like effects produced by evil creatures. The target also gains a +1 sacred bonus on saving throws and DR 5/evil or silver.', NULL, NULL, true, false),
  ('celestial_healing', 'Celestial Healing', 'conjuration', 'healing', 'good', 1, 'divine', 'bloodrager 1, cleric 1, magus 1, sorcerer/wizard 1, summoner 1, witch 1', '1 round', 'touch', 'creature touched', NULL, NULL, '1 round/2 levels', 'Will negates (harmless)', 'yes (harmless)', 'You anoint a wounded creature with the blood of an outsider with the good subtype (such as an angel) or holy water, giving it fast healing 1. The target radiates the aura of a good creature for the duration of the spell and can sense the righteousness of the magic, though this has no long-term effect on the target’s alignment. If the target has its own evil aura, this is not suppressed by celestial healing, and can also be detected normally.', '1 drop of blood from a good outsider or 1 dose of holy water', NULL, false, false),
  ('ceremony', 'Ceremony', 'transmutation', NULL, NULL, 1, 'divine', 'cleric 1', '8 hours', 'touch or medium (100 ft. + 10 ft./level) (see text)', 'willing, living creature or creatures touched or one creature/level (see text)', NULL, NULL, '1 hour/level or 1 day/level (see text)', 'Will negates (see text)', 'yes', 'You harness divine power to create one of four different ceremonies—a funeral, holiday fete, marriage, or naming—and can also create two domain-based ceremonies. Each ceremony provides a boon to two living, touched subjects for 1 hour per caster level, representing the divine gifts granted by your deity as well as the normal morale-boosting benefits of participating in an officiated ceremony. Bonuses granted by these boons are sacred bonuses if you channel positive energy or profane bonuses if you channel negative energy. (Bonuses in this section are referred to simply as sacred bonuses for ease of reading.) Only subjects whose alignments are within one step of your deity can be affected by this spell.', NULL, NULL, true, false),
  ('certain_grip', 'Certain Grip', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, bloodrager 2, druid 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'The subject’s grip and footing become sure, granting a +4 competence bonus on Climb checks, on Acrobatics checks to balance, and to CMD against bull rush, drag, reposition, and trip attempts. While affected by this spell, the target is also immune to the disarm combat maneuver.', 'a tiny ball of tar', NULL, true, false),
  ('chain_lightning', 'Chain Lightning', 'evocation', NULL, 'electricity', 6, 'arcane', 'magus 6, sorcerer/wizard 6, witch 7; Domain air 6; Bloodline djinni 6; Elemental School air 6, metal 6; Mystery heavens 6', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, NULL, 'instantaneous', 'Reflex half', 'yes', 'This spell creates an electrical discharge that begins as a single stroke commencing from your fingertips. Unlike lightning bolt, chain lightning strikes one object or creature initially, then arcs to other targets.', NULL, 'a bit of fur; a piece of amber, glass, or a crystal rod; plus one silver pin per caster level', false, false),
  ('chain_of_perdition', 'Chain of Perdition', 'evocation', NULL, 'force', 3, 'divine', 'bloodrager 3, cleric/oracle 3, psychic 3, sorcerer/wizard 3; Subdomain psychopomp (death, repose) 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '10-ft. chain', '1 round/level (D)', 'none', 'yes', 'A floating chain of force with hooks at each end appears within an unoccupied space of your choosing within range. This chain is a Medium object that has a 10-foot reach. Physical attacks cannot hit or harm the chain of perdition, but dispel magic, disintegrate, a sphere of annihilation, or a rod of cancellation affects it normally. The chain’s AC against touch attacks is 10 + your Charisma modifier (sorcerer), Intelligence modifier (wizard), or Wisdom modifier (cleric).', 'chain link', NULL, true, false),
  ('chains_of_fire', 'Chains of Fire', 'evocation', NULL, 'fire', 6, 'arcane', 'magus 6, sorcerer/wizard 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, 'instantaneous', 'Reflex half', 'yes', 'This spell functions like chain lightning, except as noted above, and the spell deals fire damage instead of electricity damage.', NULL, 'a drop of oil and a small piece of flint', false, false),
  ('chains_of_light', 'Chains of Light', 'conjuration', 'creation', 'good', 4, 'divine', 'cleric 6, inquisitor 5, paladin 4, sorcerer/wizard 6', '1 standard action', 'short (25 ft. + 5 ft./level)', 'one creature', NULL, NULL, '1 round/level (D)', 'Reflex negates', 'no', 'A creature targeted by this spell is held immobile by glowing golden chains composed of pure light. The creature is paralyzed and held in place, but may attempt a new saving throw each round to end the effect. While held by the golden chains, a creature cannot use any sort of extradimensional travel, such as astral projection, blink, dimension door, ethereal jaunt, etherealness, gate, maze, plane shift, shadow walk, teleport, and similar spells and spell-like abilities. The spell does not affect creatures that are already in ethereal or astral form when the spell is cast.', NULL, 'a length of fine golden chain', false, false),
  ('challenge_evil', 'Challenge Evil', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'paladin 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level (D)', 'Will negates', 'yes', 'You challenge an evil creature to bring the fight to you, or suffer the consequences. You gain a +2 sacred bonus on all melee attacks against the subject of the spell. At the end of its turn, if the target has not made at least one attack on you, it becomes sickened. If you move away from the target, the spell ends.', NULL, NULL, true, false),
  ('chameleon_scales', 'Chameleon Scales', 'transmutation', NULL, NULL, 0, 'divine', 'alchemist 1, druid 0, ranger 1, sorcerer/wizard 0', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'You temporarily alter the color of your skin, hide, or scales to another option legal for your race. You take no penalty for using Disguise to appear as a member of a different race as long as that race has the same type and color of skin, hide, or scales as you.', NULL, NULL, true, false),
  ('chameleon_stride', 'Chameleon Stride', 'illusion', 'glamer', NULL, 2, 'divine', 'ranger 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'You fade into the background, and while you are not truly invisible, you are hard to pinpoint due to your translucent state. While under the effects of this spell, you gain a +4 bonus on Stealth checks and have concealment from creatures more than 5 feet away (attacks have a 20% miss chance).', NULL, NULL, true, false),
  ('champion_s_bout', 'Champion’s Bout', 'enchantment', 'compulsion', 'mind-affecting', 3, 'divine', 'bard 3, cleric 3, mesmerist 3', '1 round', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates (see text)', 'yes (see text)', 'You allow two chosen champions to fight without interference.', NULL, NULL, false, false),
  ('changestaff', 'Changestaff', 'transmutation', NULL, NULL, 8, 'arcane', 'druid 7; Mystery wood 8', '1 round', 'touch', 'your touched staff', NULL, NULL, '1 hour/level (D)', 'none', 'no', 'You change a specially prepared quarterstaff into a Huge treant-like creature, about 24 feet tall. When you plant the end of the staff in the ground and speak a special command to conclude the casting of the spell, your staff turns into a creature that looks and fights just like a treant. The staff-treant defends you and obeys any spoken commands. However, it is by no means a true treant; it cannot converse with actual treants or control trees. If the staff-treant is reduced to 0 or fewer hit points, it crumbles to powder and the staff is destroyed. Otherwise, the staff returns to its normal form when the spell duration expires (or when the spell is dismissed), and it can be used as the focus for another casting of the spell. The staff-treant is always at full strength when created, despite any wounds it may have incurred the last time it appeared.', NULL, 'a quarterstaff that has been carved and polished for 28 days', false, false),
  ('channel_the_gift', 'Channel the Gift', 'evocation', NULL, NULL, 3, 'divine', 'bard 3, cleric/oracle 3, druid 3, ranger 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'ally spellcaster touched', NULL, NULL, '1 round or see text', 'Will negates (harmless) or none', 'yes (harmless) or no', 'You channel your magical power to fuel the target’s spellcasting.', NULL, NULL, true, false),
  ('channel_vigor', 'Channel Vigor', 'transmutation', NULL, NULL, 3, 'divine', 'alchemist 3, cleric 3, inquisitor 3, magus 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You focus the energy of your mind, body, and spirit into a specific part of your being, granting yourself an exceptional ability to perform certain tasks. When you cast the spell, choose one of the following portions of your self as your focus target. Thereafter, you may change the focus target as a move action. You can gain the benefit of only one channel vigor spell at a time.', NULL, NULL, false, false),
  ('chaos_hammer', 'Chaos Hammer', 'evocation', NULL, 'chaotic', 4, 'divine', 'cleric/oracle 4, inquisitor 4; Domain chaos 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius burst', NULL, 'instantaneous (1d6 rounds); see text', 'Will partial; see text', 'yes', 'You unleash chaotic power to smite your enemies. The power takes the form of a multicolored explosion of leaping, ricocheting energy. Only lawful and neutral (not chaotic) creatures are harmed by the spell.', NULL, NULL, false, false),
  ('charge_object', 'Charge Object', 'transmutation', NULL, NULL, 1, 'arcane', 'medium 1, mesmerist 1, occultist 1, psychic 1, spiritualist 1', '10 minutes', 'touch', 'object touched', NULL, NULL, 'permanent', 'none; see text', 'no', 'You charge an item with minor psychic energy. The item can be detected by the detect psychic significance spell. If you wish, You can imprint the item with your ownership history. Spells such as object reading and uses of the psychometry occult skill unlock can reveal any information about yourself you impart into the object, including your name, alignment, profession, and a summary of your experiences with the item. You can’t impart false information into the object, but you can omit any details you’d prefer not to divulge. If the target object is already psychically charged, you can add more information to it, but you can’t use charge object to erase existing psychic information.', NULL, NULL, false, false),
  ('charitable_impulse', 'Charitable Impulse', 'enchantment', 'compulsion', 'mind-affecting', 2, 'divine', 'bard 2, cleric/oracle 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'This spell makes a creature more charitable, compelling it to aid others rather than use violence.', NULL, NULL, true, false),
  ('charm_animal', 'Charm Animal', 'enchantment', 'charm', 'mind-affecting', 1, 'divine', 'druid 1, psychic 1, ranger 1, shaman 1; Mystery nature 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like charm person, except that it affects a creature of the animal type.', NULL, NULL, false, false),
  ('charm_fey', 'Charm Fey', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1, sorcerer/wizard 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as charm person, except it affects a fey instead of a humanoid.', NULL, NULL, false, false),
  ('charm_monster', 'Charm Monster', 'enchantment', 'charm', 'mind-affecting', 3, 'arcane', 'bard 3, sorcerer/wizard 4, summoner 3, unchained summoner 4, witch 4; Domain charm 5; Elemental School wood 4; Mystery juju(PAP39/PZO9039) 4, juju(PZO9436) 4', NULL, NULL, NULL, NULL, NULL, '1 day/level', NULL, NULL, 'This spell functions like charm person, except that the effect is not restricted by creature type or size.', NULL, NULL, false, false),
  ('charm_person', 'Charm Person', 'enchantment', 'charm', 'mind-affecting', 1, 'divine', 'bard 1, psychic 1, shaman 1, sorcerer/wizard 1, witch 1; Domain charm 1; Subdomain slavery 1; Elemental School wood 1; Mystery intrigue 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'This charm makes a humanoid creature regard you as its trusted friend and ally (treat the target’s attitude as friendly). If the creature is currently being threatened or attacked by you or your allies, however, it receives a +5 bonus on its saving throw.', NULL, NULL, false, false),
  ('charnel_house', 'Charnel House', 'illusion', 'shadow', 'evil, shadow', 3, 'divine', 'antipaladin 3, cleric 5, mesmerist 5, psychic 5, sorcerer/wizard 5, witch 5', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, '20-ft. cube (S)', NULL, '10 minutes/level', 'Will partial', 'no', 'By sacrificing a living creature, you create the grisly illusion of viscera and gore splattered about the nearby area. When the casting time is complete, the walls drip with blood and the floor is slick with unidentifiable lumps of meat and other signs of a massacre. Anyone entering the area must attempt a Will save or be sickened for 1d6 rounds. This is a mind-affecting effect. If a creature succeeds at its save, it can see the semi-real nature of the illusion.', 'one Tiny or larger living creature', NULL, false, false),
  ('charon_s_dispensation', 'Charon’s Dispensation', 'abjuration', NULL, NULL, 4, 'divine', 'cleric 4, inquisitor 4, medium 4, mesmerist 4, psychic 4, shaman 4, sorcerer/wizard 4, spiritualist 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature/level', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'The target of this spell gains immunity to the harmful effects of touching or drinking from the River Styx and a +4 profane bonus on saves against effects that alter or suppress memory (such as modify memory or mindwipe). This does not grant the target the ability to breathe water, nor does it grant any protection against creatures or mundane hazards such as rapids. The spell has no power to restore memory to a creature already suffering from an existing fugue or amnesia state.', '2 silver coins', NULL, false, false),
  ('chastise', 'Chastise', 'transmutation', NULL, NULL, 1, 'arcane', 'bard 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You gain a +5 bonus on Bluff, Diplomacy, and Intimidate checks to convince a listener that they will get in trouble with their superiors or with the law if they don’t do what you ask.', NULL, NULL, false, false),
  ('cheetah_s_sprint', 'Cheetah’s Sprint', 'transmutation', NULL, NULL, 1, 'divine', 'bloodrager 1, druid 1, ranger 1, shaman 1, witch 1', '1 swift action', 'personal', 'you', NULL, NULL, '1 round', NULL, NULL, 'A wild surge of energy courses through your body and propels you into a sprint.', NULL, NULL, false, false),
  ('chill_metal', 'Chill Metal', 'transmutation', NULL, 'cold', 2, 'divine', 'druid 2, psychic 2; Elemental School metal 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'metal equipment of one creature per two levels, no two of which can be more than 30 ft. apart; or 25 lbs. of metal/level, none of which can be more than 30 ft. away from any of the rest', NULL, NULL, '7 rounds', 'Will negates (object)', 'yes (object)', 'Chill metal makes metal extremely cold.', NULL, NULL, true, false),
  ('chill_touch', 'Chill Touch', 'necromancy', NULL, NULL, 1, 'divine', 'bloodrager 1, magus 1, shaman 1, sorcerer/wizard 1, witch 1; Mystery reaper 1', '1 standard action', 'touch', NULL, NULL, NULL, 'instantaneous', 'Fortitude partial or Will negates; see text', 'yes', 'A touch from your hand, which glows with blue energy, disrupts the life force of living creatures. Each touch channels negative energy that deals 1d6 points of damage. The touched creature also takes 1 point of Strength damage unless it makes a successful Fortitude saving throw. You can use this melee touch attack up to one time per level.', NULL, NULL, false, false),
  ('chord_of_shards', 'Chord of Shards', 'evocation', NULL, NULL, 1, 'arcane', 'bard 1', '1 standard action', '15 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Reflex negates; Spell resistance no', NULL, 'During your bardic performance, you can strike a chord whose notes transform into a shower of razor sharp, crystalline shards. The shards deal 2d6 points of piercing damage to all creatures caught in the area of effect.', NULL, NULL, false, false),
  ('circle_of_clarity', 'Circle of Clarity', 'abjuration', NULL, NULL, 7, 'divine', 'cleric/oracle 7, shaman 8, sorcerer/wizard 7; Domain [subdomain] Community [education]', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '20-ft.-radius emanation centered on a creature, object, or point in space', '1 round/level (D)', 'Will negates (harmless); Spell resistance yes (harmless)', NULL, 'You create a magical emanation that interferes with all figments and glamers within it, giving creatures a +4 bonus on saving throws to recognize them as illusions. The emanation negates concealment less than total concealment within the area. Perception checks to notice creatures or objects within the area gain a bonus equal to half your caster level (maximum +10). The spell is stationary if cast on a point in space. It is mobile if centered on a creature or object, though creatures or attended objects can negate the spell with a saving throw or spell resistance.', NULL, 'a crystal lens worth 100 gp', false, true),
  ('circle_of_death', 'Circle of Death', 'necromancy', NULL, 'death', 6, 'divine', 'inquisitor 6, sorcerer/wizard 6; Bloodline daemon 6; Mystery apocalypse 6, bones 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'several living creatures within a 40-ft.-radius burst', NULL, 'instantaneous', 'Fortitude negates', 'yes', 'Circle of death snuffs out the life force of living creatures, killing them instantly. The spell slays 1d4 HD worth of living creatures per caster level (maximum 20d4). Creatures with the fewest HD are affected first; among creatures with equal HD, those who are closest to the burst’s point of origin are affected first. No creature of 9 or more HD can be affected, and HD that are not sufficient to affect a creature are wasted.', 'a crushed black pearl worth 500 gp', NULL, false, true),
  ('claim_identity', 'Claim Identity', 'transmutation', 'polymorph', NULL, 3, 'divine', 'alchemist 3, antipaladin 3, bard 3, druid 4, inquisitor 3, shaman 4, sorcerer/wizard 4, witch 3', '1 standard action', 'touch', 'humanoid creature touched', NULL, NULL, '1 hour/level', 'Fort negates', 'yes', 'You steal the target’s face, transforming yourself into a flawless imitation of it. All of the target’s facial features, vocal cues, and identifying physical traits change, transforming it into an unremarkable member of its race and gender. You transform into a perfect likeness of the target’s true form, as if affected by alter self, and gain a +10 bonus on Disguise checks to impersonate the original subject of this spell; you take no penalties on this check if the original target is of a different race, age, size, or gender.', 'a needle and thread', NULL, false, false),
  ('clairaudience_clairvoyance', 'Clairaudience-Clairvoyance', 'divination', 'scrying', NULL, 2, 'divine', 'bard 3, medium 2, mesmerist 3, occultist 3, psychic 3, shaman 3, sorcerer/wizard 3, spiritualist 3, witch 3; Elemental School void 3; Mystery occult 3', '10 minutes', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'magical sensor', '1 min./level (D)', 'none', 'no', 'Clairaudience/clairvoyance creates an invisible magical sensor at a specific location that enables you to hear or see (your choice) almost as if you were there. You don’t need line of sight or line of effect, but the locale must be known – a place familiar to you, or an obvious one. Once you have selected the locale, the sensor doesn’t move, but you can rotate it in all directions to view the area as desired. Unlike other scrying spells, this spell does not allow magically or supernaturally enhanced senses to work through it. If the chosen locale is magically dark, you see nothing. If it is naturally pitch black, you can see in a 10-foot radius around the center of the spell’s effect. Clairaudience/clairvoyance functions only on the plane of existence you are currently occupying.', NULL, NULL, true, false),
  ('clarion_call', 'Clarion Call', 'illusion', NULL, NULL, 1, 'divine', 'bard 1, cleric 1, magus 1, sorcerer/wizard 1', NULL, 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Fort negates (harmless)', 'yes (harmless)', 'The subject of this spell gains two benefits. First, the affected creature gains the ability to create a sound like the blast of a mighty horn or trumpet simply by miming the action of sounding one. Second, the subject can speak in a booming voice that carries easily over great distances, lowering the DC of any check to hear what is said by –15. This spell is particularly prized by battlefield commanders and champions who wish to make themselves clearly heard or gain the attention of their allies or foes.', NULL, NULL, false, false),
  ('clashing_rocks', 'Clashing Rocks', 'conjuration', 'creation', 'earth', 9, 'divine', 'druid 9, sorcerer/wizard 9; Bloodline deep earth 9; Elemental School earth 9; Mystery stone 9', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'see text', 'instantaneous', 'Reflex partial, see text', 'no', 'You create two Colossal-sized masses of rock, dirt, and stone and slam them together against a single creature between them. The clashing rocks appear up to 30 feet away from the target on opposite sides and rush toward it with a mighty grinding crash. You must make a ranged touch attack to hit the target with the rocks. The clashing rocks ignore concealment and cover, and if there is a solid barrier between the target and either of the clashing rocks, the spell has a +28 bonus on the Strength check to burst through the barrier and continue unimpeded to the target. A creature struck by the clashing rocks takes 20d6 points of bludgeoning damage and is knocked prone. If the target fails a Reflex Saving Throw, it is also buried under the resulting rubble as if by a cave-in.', NULL, NULL, false, false),
  ('clay_skin', 'Clay Skin', 'abjuration', NULL, NULL, 3, 'divine', 'alchemist 3, bloodrager 3, inquisitor 3, magus 3, sorcerer/wizard 3, summoner 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level or until discharged', 'Will negates (harmless)', 'yes (harmless)', 'The target’s skin becomes as thick and tough as clay, granting the target DR 5/adamantine. Once the spell has prevented a total of 5 points of damage per caster level (maximum 50 points), it is discharged and the spell ends.', 'clay and iron filings', NULL, false, false),
  ('cleanse', 'Cleanse', 'evocation', NULL, NULL, 5, 'divine', 'cleric/oracle 5, inquisitor 6; Subdomain divine 5', '1 standard action', 'personal', NULL, NULL, NULL, 'instantaneous', NULL, NULL, 'Positive energy infuses and cleanses your body.', NULL, NULL, true, false),
  ('cleansing_fire', 'Cleansing Fire', 'evocation', NULL, 'good, fire', 4, 'divine', 'cleric 5, inquisitor 4, paladin 4', '1 standard action', 'touch', NULL, '30-ft. radius emanating from the touched point', NULL, 'concentration, up to 1 round/level', 'none', 'yes', 'A ring of fire surrounds the area affected by the spell. The flames radiate heat, but not enough to damage adjacent creatures. The flames deal 2d6 points of fire damage to any creatures that pass through them (or 4d6 points of damage to undead creatures). If you manifest a portion of the ring in a square that contains a creature, that creature takes damage as if it passed through the ring.', NULL, NULL, true, false),
  ('clear_grove', 'Clear Grove', 'transmutation', NULL, NULL, 2, 'divine', 'druid 3, ranger 2, shaman 3, witch 3', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '20-ft.-radius clearing', '2 hours/level (D)', 'none', 'no', 'Trees, shrubs, and other thick vegetation move out of the spell’s area. The affected area is cleared of all vegetation thick enough to provide cover or concealment. This also creates a hole in any tree canopy, allowing sunlight to pass through. Affected trees and undergrowth form a 5-foot-wide ring along the edge of the clearing, which may provide cover or concealment based on the thickness of the vegetation (at the GM’s discretion).', 'a miniature hoe', NULL, true, false),
  ('clenched_fist', 'Clenched Fist', 'evocation', NULL, 'force', 8, 'arcane', 'sorcerer/wizard 8; Domain strength 8', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like interposing hand, except that the hand can also push or strike one opponent that you select. The floating hand can move as far as 60 feet and can attack in the same round. Since this hand is directed by you, its ability to notice or attack invisible or concealed creatures is no better than yours.', NULL, NULL, true, false),
  ('cleromancy', 'Cleromancy', 'divination', NULL, NULL, 2, 'divine', 'cleric 2, druid 3, inquisitor 3, sorcerer/wizard 3', 'full-round action', 'personal', 'you', NULL, NULL, '1 round/caster level', 'none', 'no', 'Cleromancy involves casting bones and interpreting the results. Those able to arrive at the proper interpretation are granted knowledge of coming events. Roll 1d4 per caster level. Group the dice by like results, and choose one of the groups. For the duration of cleromancy, you can apply a luck bonus equal to the result of the selected dice to any d20 roll.', NULL, NULL, true, false),
  ('climbing_beanstalk', 'Climbing Beanstalk', 'conjuration', 'creation', NULL, 2, 'divine', 'druid 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '5-ft. square of climbable beanstalks', 'instantaneous', NULL, NULL, 'You cause a thick, sturdy beanstalk to sprout from the ground and grow upward to a height of 10 feet + 5 feet per 2 caster levels. The growing stalk anchors itself to sturdy objects such as walls or ceilings, and grows around objects that do not fully obstruct its square (such as tree branches), but is stopped by solid obstacles. The beanstalk provides numerous hand- and footholds; its climb DC 5. The beanstalk can support up to 200 pounds plus 50 pounds per caster level, or double that amount if anchored on its upper end. If it anchors itself to a sturdy mobile object (such as a ship or a siege engine), breaking the object free requires a DC 23 Strength check or cutting through the beanstalk (hardness 2, 40 hp).', NULL, NULL, true, false),
  ('cloak_of_chaos', 'Cloak of Chaos', 'abjuration', NULL, 'chaotic', 8, 'divine', 'cleric/oracle 8; Domain chaos 8', '1 standard action', '20 ft.', NULL, NULL, NULL, '1 round/level (D)', 'see text', 'yes (harmless)', 'A random pattern of color surrounds the subjects, protecting them from attacks, granting them resistance to spells cast by lawful creatures, and causing lawful creatures that strike the subjects to become confused. This abjuration has four effects.', NULL, 'a tiny reliquary worth 500 gp', false, true),
  ('cloak_of_dreams', 'Cloak of Dreams', 'enchantment', 'compulsion', 'mind-affecting', 5, 'divine', 'bard 5, shaman 7, sorcerer/wizard 6, witch 6; Subdomain nightmare 6, whimsy 6', '1 round', '5 ft.', NULL, '5-ft.-radius emanation centered on you', NULL, '1 round/level (D)', 'Will negates', 'yes', 'You are surrounded by a soporific aroma that causes living creatures that begin their turn or end their movement within 5 feet of you to fall asleep for 1 minute. Creatures must save each time they begin their turn or end their movement within the cloak of dreams, even if they have previously saved against the effect. Sleeping creatures are helpless but can be awakened with a standard action or after being wounded.', 'a rose petal and a drop of perfume', NULL, false, false),
  ('cloak_of_secrets', 'Cloak of Secrets', 'illusion', 'glamer', NULL, 1, 'divine', 'antipaladin 1, bard 1, cleric 1, inquisitor 1, sorcerer/wizard 1, witch 1', '1 minute', 'close (25 ft. + 5 ft./2 levels)', NULL, '5-ft.-radius emanation centered on a point in space', NULL, '10 minutes/level (D)', 'none', 'no', 'This spell forms an invisible bubble that filters all speech coming from inside the affected area so that creatures outside hear a completely different version of the conversation. The bubble also disguises lip movements to match the false conversation.', NULL, NULL, false, false),
  ('cloak_of_shade', 'Cloak of Shade', 'abjuration', NULL, NULL, 1, 'divine', 'druid 1, ranger 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 hour/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell provides the subject with some degree of protection from the harmful effects of the sun. The cloaked subject treats environmental heat due to sun exposure as one level less: severe heat is considered very hot conditions, while very hot is considered average temperature (see heat dangers). The cloak of shade also reduces any penalties from sunlight by 1. The spell does not, however, eliminate the effects of direct sunlight on creatures vulnerable to sunlight. Cloak of shade has no effect on environmental heat from sources other than the sun.', 'a leaf from a shade tree', NULL, false, false),
  ('cloak_of_shadows', 'Cloak of Shadows', 'illusion', 'shadow', 'evil, shadow', 4, 'divine', 'antipaladin 4, arcanist 5, bard 5, mesmerist 5, skald 5, sorcerer/wizard 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You wrap yourself in a protective mantle of semireal shadow. This grants a number of advantages: you gain concealment (20% miss chance), a +5 competence bonus on Stealth checks, and DR 5/good. This shroud of shadows also protects you from direct sunlight, negating sunlight vulnerability, sunlight powerlessness, and similar effects.', NULL, NULL, false, false),
  ('cloak_of_winds', 'Cloak of Winds', 'abjuration', NULL, 'air', 3, 'divine', 'bloodrager 3, druid 3, magus 3, ranger 3, sorcerer/wizard 3; Elemental School air 3, wood 3; Mystery wind 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'You shroud a creature in a whirling screen of strong, howling wind.', NULL, NULL, false, false),
  ('clone', 'Clone', 'necromancy', NULL, NULL, 8, 'arcane', 'sorcerer/wizard 8, witch 8; Mystery streets 9', '10 minutes', '0 ft.', NULL, NULL, 'one clone', 'instantaneous', 'none', 'no', 'This spell makes an inert duplicate of a creature. If the original individual has been slain, its soul immediately transfers to the clone, creating a replacement (provided that the soul is free and willing to return). The original’s physical remains, should they still exist, become inert and cannot thereafter be restored to life. If the original creature has reached the end of its natural life span (that is, it has died of natural causes), any cloning attempt fails.', 'laboratory supplies worth 1,000 gp', 'special laboratory equipment costing 500 gp', false, true),
  ('cloud_of_seasickness', 'Cloud of Seasickness', 'conjuration', 'creation', 'poison', 2, 'divine', 'cleric 2, druid 2, sorcerer/ wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'cloud spreads in 20-ft. radius, 20 ft. high', '1 round/level', 'Fort negates; see text', 'no', 'This spell functions like stinking cloud, except as noted above and that the vapors make creatures sickened instead of nauseated.', 'a piece of seaweed', NULL, false, false),
  ('cloud_shape', 'Cloud Shape', 'transmutation', NULL, 'air', 4, 'divine', 'druid 4, ranger 4, sorcerer/wizard 4', NULL, 'personal', 'you', NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'This spell functions like gaseous form, except you assume the shape of a Colossal cloud with a space of 30 feet. You choose the general appearance of the cloud (white, stormy, fluffy, flat, and so on), after which your appearance cannot be changed. Even the closest inspection cannot reveal that the cloud in question is actually a magically concealed creature. To all normal tests you are, in fact, a cloud, although a detect magic spell reveals a moderate transmutation aura on the cloud. Your fly speed in cloud form is 30 feet.', NULL, NULL, false, false),
  ('cloudkill', 'Cloudkill', 'conjuration', 'creation', 'poison', 5, 'arcane', 'magus 5, sorcerer/wizard 5, unchained summoner 5, witch 5; Subdomain venom 6; Elemental School water 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'cloud spreads in 20-ft. radius, 20 ft. high', '1 min./level', 'Fortitude partial; see text', 'no', 'This spell generates a bank of fog, similar to a fog cloud, except that its vapors are yellowish green and poisonous. These vapors automatically kill any living creature with 3 or fewer HD (no save). A living creature with 4 to 6 HD is slain unless it succeeds on a Fortitude save (in which case it takes 1d4 points of Constitution damage on your turn each round while in the cloud).', NULL, NULL, false, false),
  ('codespeak', 'Codespeak', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'you plus one willing creature per 2 levels, no two of which can be more than 30 ft. apart', NULL, NULL, '10 min./level (D)', 'none', 'no', 'Upon casting this spell, all recipients gain the ability to speak a new language. This language sounds like random, babbling syllables to anyone not under the influence of the spell, but the targets understand each other perfectly.', 'a complex rune inscribed on a slip of paper that is then placed under your tongue', NULL, false, false),
  ('cognitive_block', 'Cognitive Block', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'medium 2, mesmerist 2, psychic 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You create a mental block in the target’s mind, impeding the flow of his mental spellcasting process and forcing him to incorporate a thought component into any spell or spell-like ability he uses. This is in addition to any other components the spell already requires, and doesn’t replace the verbal component. Spell-like abilities require this thought component, even though they normally don’t need spell components.', NULL, NULL, false, false),
  ('coin_shot', 'Coin Shot', 'transmutation', NULL, NULL, 1, 'divine', 'alchemist 1, antipaladin 1, bard 1, bloodrager 1, magus 1, sorcerer/wizard 1', '1 standard action', 'touch', 'up to three coins touched', NULL, NULL, '10 minutes or until discharged', 'none', 'yes (harmless, object)', 'You turn up to three coins into deadly projectiles that gain the velocity of a bullet when thrown. The coins retain their normal appearance but can be used as simple thrown weapons with a range increment of 20 feet and a critical multiplier of ×2. The transmuted coins are treated as ammunition for the purposes of drawing them. Like firearm bullets, the coins deal bludgeoning and piercing damage, and attacks with them are resolved as touch attacks within the first range increment. Regardless of whether a transmuted coin hits or misses the target, it is destroyed after the attack. Only you can make attacks with the coins, though other creatures can safely handle them without discharging the spell.', NULL, NULL, false, false),
  ('cold_ice_strike', 'Cold Ice Strike', 'evocation', NULL, 'cold', 6, 'divine', 'cleric/oracle 6, sorcerer/wizard 6', '1 swift action', '30 feet', NULL, '30-ft. line', NULL, 'instantaneous', 'Reflex half; Spell resistance yes', NULL, 'You create a shredding flurry of ice slivers, which blast from your hand in a line. The line deals 1d6 points of cold damage per caster level (maximum 15d6).', NULL, NULL, false, false),
  ('cold_iron_fetters', 'Cold Iron Fetters', 'conjuration', 'creation', NULL, 3, 'divine', 'arcanist 5, cleric/oracle 5, hunter 3, inquisitor 4, occultist 5, ranger 3, shaman 5, sorcerer/wizard 5, summoner 4, summoner (unchained) 4, warpriest 5, witch 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 round/level (D)', 'Reflex negates', 'no', 'Cold iron shackles materialize around the target’s limbs, reducing each of the target’s movement speeds by half. Any flying target has its maneuverability worsened by two steps (from good to poor, for example, to a minimum of clumsy maneuverability). Additionally, if the target has DR/cold iron or DR/cold iron and magic, it is unable to use supernatural or spell-like means of movement (such as dimension door, teleport, or tree meld) for the duration of the spell.', 'miniature cold iron shackle', NULL, true, false),
  ('collaborative_thaumaturgy', 'Collaborative Thaumaturgy', 'universal', NULL, NULL, 3, 'divine', 'bard 3, cleric 3, druid 3, magus 3, summoner 3, sorcerer/wizard 3, witch 3', '1 immediate action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You tap into the magical resonance between you and your allies to enhance one another’s magic. Cast this spell when an ally casts a spell at least 1 level lower than the highest-level spell she can cast.', NULL, 'a bronze tuning fork', false, false),
  ('color_spray', 'Color Spray', 'illusion', 'pattern', 'mind-affecting', 1, 'arcane', 'bloodrager 1, magus 1, psychic 1, sorcerer/wizard 1; Mystery heavens 1', '1 standard action', '15 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous; see text', 'Will negates', 'yes', 'A vivid cone of clashing colors springs forth from your hand, causing creatures to become stunned, perhaps also blinded, and possibly knocking them unconscious. Each creature within the cone is affected according to its HD.', 'red, yellow, and blue powder or colored sand', NULL, false, false),
  ('command', 'Command', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 1, 'divine', 'antipaladin 1, cleric/oracle 1, inquisitor 1, psychic 1, witch 1; Subdomain devil (evil, law) 1, toil 1, tyranny 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'You give the subject a single command, which it obeys to the best of its ability at its earliest opportunity. You may select from the following options.', NULL, NULL, false, false),
  ('command_plants', 'Command Plants', 'transmutation', NULL, NULL, 3, 'divine', 'druid 4, ranger 3, shaman 4; Domain plant 4; Elemental School wood 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 day/level', 'Will negates', 'yes', 'This spell allows you some degree of control over one or more plant creatures. Affected plant creatures can understand you, and they perceive your words and actions in the most favorable way (treat their attitude as friendly). They will not attack you while the spell lasts. You can try to give a subject orders, but you must win an opposed Charisma check to convince it to do anything it wouldn’t ordinarily do. (Retries are not allowed.) A commanded plant never obeys suicidal or obviously harmful orders, but it might be convinced that something very dangerous is worth doing.', NULL, NULL, false, false),
  ('command_undead', 'Command Undead', 'necromancy', NULL, NULL, 3, 'arcane', 'sorcerer/wizard 2; Domain inevitable 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 day/level', 'Will negates; see text', 'yes', 'This spell allows you a degree of control over an undead creature. If the subject is intelligent, it perceives your words and actions favorably (treat its attitude as friendly). It will not attack you while the spell lasts. You can give the subject orders, but you must win an opposed Charisma check to convince it to do anything it wouldn’t ordinarily do. Retries are not allowed. An intelligent commanded undead never obeys suicidal or obviously harmful orders, but it might be convinced that something very dangerous is worth doing.', 'a shred of raw meat and a splinter of bone', NULL, false, false),
  ('commune', 'Commune', 'divination', NULL, NULL, 5, 'divine', 'cleric/oracle 5, inquisitor 5, shaman 5', '10 minutes', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You contact your deity–or agents thereof–and ask questions that can be answered by a simple yes or no. (A cleric of no particular deity contacts a philosophically allied deity.) You are allowed one such question per caster level. The answers given are correct within the limits of the entity’s knowledge. “Unclear” is a legitimate answer, because powerful beings of the Outer Planes are not necessarily omniscient. In cases where a one-word answer would be misleading or contrary to the deity’s interests, a short phrase (five words or less) may be given as an answer instead.', 'holy or unholy water and incense worth 500 gp', NULL, true, true),
  ('commune_with_birds', 'Commune with Birds', 'divination', NULL, NULL, 1, 'divine', 'bard 2, druid 1, psychic 2, ranger 1, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes; see text', NULL, NULL, 'You utter a question in the form of a low-pitched bird call that can be heard up to a mile away, and can understand the responses given by birds in the area. Over the next 10 minutes, the birds reply as if you had asked them the question using speak with animals, giving you a general consensus answer to the question based on their knowledge. For example, you could ask if there is drinkable water in the area, the location of predators or other creatures, directions to a mountaintop or other natural feature, and so on, and the local bird communities would answer to the best of their ability.', NULL, NULL, false, false),
  ('commune_with_nature', 'Commune with Nature', 'divination', NULL, NULL, 4, 'divine', 'druid 5, ranger 4, shaman 5', '10 minutes', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'You become one with nature, attaining knowledge of the surrounding territory. You instantly gain knowledge of as many as three facts from among the following subjects: the ground or terrain, plants, minerals, bodies of water, people, general animal population, presence of woodland creatures, presence of powerful unnatural creatures, or even the general state of the natural setting.', NULL, NULL, false, false),
  ('commune_with_plane', 'Commune With Plane', 'divination', NULL, NULL, 4, 'divine', 'cleric 5, psychic 5, ranger 4, summoner 5, witch 5', '10 minutes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You become one with the plane around you, attaining knowledge of the surrounding territory.', NULL, NULL, false, false),
  ('commune_with_texts', 'Commune With Texts', 'divination', NULL, NULL, 4, 'divine', 'bard 5, cleric 6, inquisitor 6, medium 4, occultist 4, psychic 6, sorcerer/wizard 5, spiritualist 6', '1 minute', 'close (25 ft. + 5 ft./2 levels)', 'a collection of texts', NULL, NULL, '1 hour/level', NULL, NULL, 'You quickly absorb the knowledge in the target, which can be any assortment of books, scrolls, or other texts. During the spell’s duration, you can search the texts and immediately find the most relevant information regarding any topic the collection holds, potentially including singling out spellbooks or scrolls containing individual or particular types of spells. You can attempt Knowledge checks related to the collection’s topics as if you were trained in those skills, and you know whether the collection contains any information about which you failed a Knowledge check in the past 24 hours. The bonus on Knowledge checks granted by the collection of texts (if any) increases by 2.', 'incense worth 250 gp', NULL, false, true),
  ('companion_life_link', 'Companion Life Link', 'necromancy', NULL, NULL, 2, 'divine', 'druid 2, ranger 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'one of your animal companions or your familiar', NULL, NULL, '1 minute/level (see below)', 'Fort negates (harmless)', 'yes (harmless)', 'You create a life link between yourself and the target. You sense whenever the target is wounded and are made immediately aware if the target is slain. If you are wounded or slain, the target is made aware. As a free action, you can call out to the target, causing it to return to you (if able and willing); this ends the spell.', 'a drop of eidolon ichor', NULL, true, false),
  ('companion_mind_link', 'Companion Mind Link', 'enchantment', 'charm', 'mind-affecting', 3, 'divine', 'druid 3, ranger 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'your animal companion', NULL, NULL, '1 minute/level', NULL, NULL, 'The link between you and your animal companion becomes stronger. As long as you are within line of sight of your animal companion, you can telepathically communicate with it as if you two shared a language. Also, as long as you are within line of sight of the animal companion, you can push your animal companion a swift action instead of a move action, and you do not need to succeed at Handle Animal checks to handle your animal companion. Such checks automatically succeed.', NULL, NULL, false, false),
  ('companion_transposition', 'Companion Transposition', 'conjuration', 'teleportation', NULL, 4, 'divine', 'antipaladin 4, druid 5, paladin 4, ranger 4, shaman 5, sorcerer/wizard 5, witch 5', '1 standard action', 'long (400 ft. + 40 ft./level)', 'yourself and one animal companion, familiar, or spirit animal within range', NULL, NULL, 'instantaneous', 'none (harmless)', 'no', 'You trade places with the other target, teleporting as if you were both affected by dimension door. Both you and the other target arrive in a square you choose in the other’s former space. If the targets are different sizes, they must appear in locations that cover previously occupied squares. As with dimension door, after casting this spell, you can’t take any other actions until your next turn, and the other target is staggered until the end of its next turn due to the transposition.', NULL, 'a feather, tuft of fur, or similar memento from your target', false, false),
  ('compassionate_ally', 'Compassionate Ally', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'divine', 'bard 2, cleric/oracle 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates; Spell resistance yes', NULL, 'At the sight of an injured ally, the target immediately disengages from its current course of action and rushes to provide aid. If the target possesses curative spells or magic items, it utilizes them to help the injured ally. If not, the target provides aid by performing a Heal check. The target remains with the injured ally to assure her safety and refuses to leave the ally’s side until her wounds are fully treated or the spell ends, but can otherwise defend itself and make attacks.', NULL, NULL, false, false),
  ('compel_hostility', 'Compel Hostility', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'bard 1, cleric 1, inquisitor 1, paladin 1, psychic 1, ranger 1, summoner/unchained summoner 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'see text', 'see text', 'Whenever a creature you can see that threatens you makes an attack against one of your allies, as an immediate action, you can compel that creature to attack you instead. When you compel a creature to attack you, you must first overcome that creature’s spell resistance, and the creature can attempt a Will saving throw to ignore the compulsion. A summoner casting this spell can choose his eidolon as the target of the spell.', 'a drop of your blood', NULL, false, false),
  ('compel_tongue', 'Compel Tongue', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'bard 1, cleric/oracle 2, druid 2, medium 2, mesmerist 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'one creature', NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'This spell functions as share language, granting a creature the ability to read, understand, and communicate to the best of its ability in any one language you know. For the spell’s entire duration, the target can speak and write only in the language imparted, but its ability to understand other languages is unaffected.', 'a wooden block carved with a letter', NULL, false, false),
  ('compelling_rant', 'Compelling Rant', 'enchantment', 'charm', NULL, 5, 'divine', 'bard 5, cleric 5, inquisitor 5, mesmerist 5, psychic 5, sorcerer/wizard 5', '1 minute', 'medium (100 ft. + 10 ft./level)', 'any number of creatures', NULL, NULL, 'concentration plus 1 round/level, up to 1 hour/level', 'Will negates (see text)', 'no', 'You deliver a confusing but fascinating monologue, relaying conspiracies or metaphysical revelations that confound your audience, throughout the spell’s casting time and as long as you concentrate. You take 1d4 points of Wisdom drain when you begin the speech and can’t reduce or prevent this damage in any way. Each intelligent creature in the spell’s area takes 1d6 points of Wisdom damage as their perceptions of reality realign with yours for the spell’s duration. Listeners with at least 5 HD can attempt a Will save to negate the effects. Your targets view you with a friendly attitude and respond to criticism of you with irritation. Bluff, Diplomacy, or Intimidate checks to create doubt about your purpose in those affected by the spell take a –4 penalty. The attitude of your targets regarding any creature that criticizes you or your vision automatically changes one step toward hostile; a Diplomacy check that fails by 5 or more reduces their attitude further. Your targets retain the same alignment and their prior beliefs, in addition to the ones you force on them. You can’t force beliefs on a target if such beliefs would be necessarily against the nature of its alignment and prior beliefs, but targets are otherwise able to hold contradictory beliefs.', 'a handwritten sheet of notes', NULL, true, false),
  ('complex_hallucination', 'Complex Hallucination', 'illusion', 'phantasm', 'mind-affecting', 3, 'arcane', 'bard 4, magus 4, medium 3, mesmerist 4, occultist 4, psychic 4, sorcerer/wizard 4, witch 4', NULL, NULL, NULL, NULL, NULL, 'concentration + 3 rounds', NULL, NULL, 'This spell functions as audiovisual hallucination, except that the phantasm you create can also include olfactory, tactile, and thermal effects.', NULL, NULL, false, false),
  ('comprehend_languages', 'Comprehend Languages', 'divination', NULL, NULL, 1, 'divine', 'alchemist 1, bard 1, cleric/oracle 1, inquisitor 1, psychic 1, shaman 1, sorcerer/wizard 1, witch 1; Domain knowledge 1; Subdomain language 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 min./level', NULL, NULL, 'You can understand the spoken words of creatures or read otherwise incomprehensible written messages. The ability to read does not necessarily impart insight into the material, merely its literal meaning. The spell enables you to understand or read an unknown language, not speak or write it.', 'pinch of soot and salt', NULL, true, false),
  ('compulsive_liar', 'Compulsive Liar', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1, mesmerist 1, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'The target becomes unable to speak the truth. Lies the target speaks don’t need to be convincing, nor do they even need to be consistent, but they can’t be true as far as the target is aware.', NULL, NULL, false, false),
  ('concealed_breath', 'Concealed Breath', 'transmutation', NULL, NULL, 4, 'divine', 'alchemist 4, arcanist 4, cleric/oracle 4, druid 4, hunter 4, investigator 4, shaman 4, sorcerer/wizard 4, summoner 4, summoner (unchained) 4, warpriest 4', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 hour/level; see text', 'Will negates (harmless)', 'yes (harmless)', 'This spell allows affected creatures to hold their breath freely without negative effects or risk of suffocation.', 'a palm-sized stone', NULL, true, false),
  ('condensed_ether', 'Condensed Ether', 'transmutation', NULL, NULL, 3, 'arcane', 'psychic 4, sorcerer/wizard 5, spiritualist 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', '20-ft.-radius spread', NULL, NULL, '1 minute/level', 'none', 'no', 'You condense the substance of the Ethereal Plane as it interpenetrates the Material Plane. This thickened planar conjunction slows movement through the area to a crawl.', 'crushed amber', NULL, false, false),
  ('conditional_curse', 'Conditional Curse', 'necromancy', NULL, 'curse', 3, 'divine', 'antipaladin 4, cleric 4, inquisitor 4, medium 3, mesmerist 3, occultist 4, psychic 5, shaman 4, sorcerer/wizard 5, spiritualist 5, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent (see text)', 'Will negates', 'yes', 'This spell functions as bestow curse, except that you must state a condition under which the curse is broken, ending its effect.', NULL, NULL, false, false),
  ('conditional_favor', 'Conditional Favor', 'abjuration', NULL, NULL, 1, 'divine', 'antipaladin 1, bard 2, cleric 2, inquisitor 2, mesmerist 2, occultist 2, paladin 1, witch 2', '1 swift action', NULL, '1 creature', NULL, NULL, '1 day/level (D)', 'none (see below)', 'yes', 'You must cast this spell immediately before casting another spell on the same creature, eliciting a promise or warning against a behavior and binding the target to the paired spell. If you don’t cast a paired spell, conditional favor has no effect. The paired spell must be from the abjuration, conjuration (healing), enchantment, or transmutation school or subschool, and must be cast on a willing creature. If the spell’s recipient violates the oath or prohibition while conditional favor remains in effect, the paired spell is undone as if never cast. If the spell was a healing spell, the hit point damage or condition you removed returns immediately, even if the subject has enjoyed subsequent rest or healing. Poisons, diseases, curses, restored ability damage, and negative levels removed by the paired spell return as well.', NULL, NULL, false, false),
  ('cone_of_cold', 'Cone of Cold', 'evocation', NULL, 'cold', 5, 'divine', 'magus 5, shaman 6, sorcerer/wizard 5, witch 6; Domain water 6; Bloodline boreal 5; Elemental School water 5; Mystery winter 6', '1 standard action', '60 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Reflex half', 'yes', 'Cone of cold creates an area of extreme cold, originating at your hand and extending outward in a cone. It drains heat, dealing 1d6 points of cold damage per caster level (maximum 15d6).', 'a small crystal or glass cone', NULL, false, false),
  ('confess', 'Confess', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 2, 'divine', 'inquisitor 2, psychic 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round', 'Will partial; see text', 'yes', 'You ask the target creature a single question. On the subject’s next action, it must answer truthfully in the same language as the question or take 1d6 points of damage per two caster levels (maximum 5d6) and be sickened for 2d4 rounds. A successful Will save negates the sickening effect and halves the damage. A creature that is unable to answer still takes damage.', NULL, NULL, true, false),
  ('confusion', 'Confusion', 'enchantment', 'compulsion', 'mind-affecting', 3, 'arcane', 'bard 3, bloodrager 4, sorcerer/wizard 4, witch 4; Domain madness 4, trickery 4; Subdomain entropy 5, lust 4, whimsy 4; Mystery outer rifts 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'This spell causes confusion in the targets, making them unable to determine their actions. Roll on the following table at the start of each subject’s turn each round to see what it does in that round.', 'three nutshells', NULL, true, false),
  ('conjuration_foil', 'Conjuration Foil', 'abjuration', NULL, NULL, 3, 'arcane', 'bard 4, magus 3, medium 4, occultist 4, psychic 4, sorcerer/wizard 4, spiritualist 4, summoner 3, witch 4', '1 immediate action', 'medium (100 ft. + 10 ft./level)', NULL, '20-foot radius spread', NULL, '1 round', 'Will partial (see text)', 'yes (object)', 'All creatures in the area gain a +4 bonus on saving throws against teleportation effects. If any creature would enter or depart the area via a summoning or teleportation effect, that creature takes 1d6 points of damage per spell level of the triggering effect (or half the HD of the originating creature if the effect has no spell level) and arrives in a random similar location within the triggering effect’s range, rather than the intended destination.', NULL, NULL, false, false),
  ('conjure_black_pudding', 'Conjure Black Pudding', 'conjuration', 'summoning', 'acid', 5, 'arcane', 'sorcerer/wizard 6, summoner/unchained summoner 5', '1 round', 'close (25 ft. + 5 ft./2 level)', NULL, NULL, 'one summoned black pudding', '1 round/level (D)', 'none; Spell resistance no', NULL, 'You summon a black pudding that immediately attacks creatures near it. You have no control over the creature, and it may attack you if there are no more obvious opponents. The black pudding is treated as a summoned creature and has the extraplanar subtype. The black pudding’s split ability works normally, but all puddings derived from the summoned one disappear when the spell ends.', 'a flask of acid worth 10 gp', NULL, false, true),
  ('conjure_carriage', 'Conjure Carriage', 'conjuration', 'creation', NULL, 3, 'arcane', 'bard 3, magus 3, sorcerer/wizard 3, summoner 3, witch 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one quasi-real carriage, horses, and driver', '1 hour/level (D)', 'none', 'no', 'You create a fine wooden carriage with whatever cosmetic embellishments you desire. It is well constructed, although not exceptionally ostentatious. The carriage can carry up to six Medium or Small passengers. When conjured, the carriage comes with a team of two quasi-real light horses, which are already harnessed to the carriage. At your command, an invisible coachman similar to an unseen servant can assume the role of driver and direct the carriage, although it can’t perform any complex or dangerous driving, and fails any checks made to drive the carriage in such conditions. At the end of the spell’s duration, the carriage, horses, and coachman disappear into nothingness, depositing everything on or in it on the ground in its space.', 'a gourd', NULL, false, false),
  ('conjure_deadfall', 'Conjure Deadfall', 'conjuration', 'creation', NULL, 4, 'arcane', 'magus 5, sorcerer/wizard 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'see text', NULL, 'instantaneous', 'Reflex negates (see text)', 'yes', 'You conjure a large metal cube covered in sharp spikes.', 'fistful of mithral tacks', NULL, false, false),
  ('consecrate', 'Consecrate', 'evocation', NULL, 'good', 2, 'divine', 'cleric/oracle 2, inquisitor 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '20-ft.-radius emanation', NULL, '2 hours/level', 'none', 'no', 'This spell blesses an area with positive energy. The DC to resist positive channeled energy within this area gains a +3 sacred bonus. Every undead creature entering a consecrated area suffers minor disruption, suffering a -1 penalty on attack rolls, damage rolls, and saves. Undead cannot be created within or summoned into a consecrated area. If the consecrated area contains an altar, shrine, or other permanent fixture dedicated to your deity, pantheon, or aligned higher power, the modifiers given above are doubled (+6 sacred bonus to positive channeled energy DCs, -2 penalties for undead in the area).', 'a vial of holy water and 25 gp worth of silver dust', NULL, true, true),
  ('constricting_coils', 'Constricting Coils', 'enchantment', 'compulsion', 'mind-affecting', 5, 'divine', 'cleric 5, sorcerer/wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 round/level (D); see text', 'Will negates; see text', 'yes', 'This spell functions like hold monster, except that the target is constricted as if by the coils of a large snake, taking 1d6+6 points of bludgeoning damage each round that it fails its save. A successful save ends both the paralyzing and constriction effects.', 'a snakeskin', NULL, true, false),
  ('contact_entity', 'Contact Entity', 'evocation', NULL, NULL, 1, 'divine', 'cleric 2, medium 1, occultist 2, psychic 2, shaman 2, sorcerer/wizard 2, summoner 2, witch 2', '1 minute', '100 miles', 'up to 20 entities of 6 HD or fewer; see text', NULL, NULL, 'instantaneous', 'none', 'no', 'You send out a magical message to any eldritch entities of a particular kind within a 100-mile radius, which can be delivered to up to 20 such creatures, starting with the nearest creatures until the limit has been met. This spell can’t contact creatures with more than 6 Hit Dice. You can’t send a specific message, but this spell (and all similar contact entity spells) can be characterized as an open invitation to make contact and establish communication.', 'see text', NULL, false, false),
  ('contact_high', 'Contact High', 'transmutation', NULL, NULL, 2, 'divine', 'alchemist 2, bard 2, cleric 3, mesmerist 3, shaman 3, skald 3', '1 standard action', 'touch', 'living creatures touched (up to one per level)', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'While under the effects of a drug, you can duplicate those effects in others. You can touch another creature once per round (this requires a melee touch attack if the target is unwilling). When touched, the target begins experiencing the effects of the same drug by which you are currently affected (select one, if you are under the influence of more than one drug). The target doesn’t take any ability damage or risk addiction from the drug.', NULL, NULL, false, false),
  ('contact_nalfeshnee', 'Contact Nalfeshnee', 'divination', NULL, NULL, 6, 'divine', 'cleric 6, sorcerer/wizard 6, witch 6', '1 round', 'personal', 'you', NULL, NULL, 'concentration', NULL, NULL, 'When you cast this spell, you fall into a trance and become helpless as long as you continue concentrating.', 'powdered sapphire worth 250 gp', 'bejeweled cold iron mirror worth at least 2,000 gp', false, true),
  ('contact_other_plane', 'Contact Other Plane', 'divination', NULL, NULL, 4, 'arcane', 'alchemist 5, sorcerer/wizard 5, summoner 4, unchained summoner 5, witch 5; Bloodline harrow 5; Mystery ascetic 5, juju(PZO9436) 6, lore 5, occult 5', '10 minutes', 'personal', 'you', NULL, NULL, 'concentration', NULL, NULL, 'You send your mind to another plane of existence (an Elemental Plane or some plane farther removed) in order to receive advice and information from powers there. See the accompanying table for possible consequences and results of the attempt. The powers reply in a language you understand, but they resent such contact and give only brief answers to your questions. All questions are answered with “yes,” “no,” “maybe,” “never,” “irrelevant,” or some other one-word answer.', NULL, NULL, false, false),
  ('contagion', 'Contagion', 'necromancy', NULL, 'disease, evil', 3, 'divine', 'antipaladin 3, bloodrager 4, cleric/oracle 3, druid 3, sorcerer/wizard 4; Subdomain decay 3; Bloodline daemon 4', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous', 'Fortitude negates', 'yes', 'The subject contracts one of the following diseases: blinding sickness, bubonic plague, cackle fever, filth fever, leprosy, mindfire, red ache, shakes, or slimy doom. The disease is contracted immediately (the onset period does not apply). Use the disease’s listed frequency and save DC to determine further effects. For more information see Diseases.', NULL, NULL, false, false),
  ('contagious_flame', 'Contagious Flame', 'evocation', NULL, 'fire', 6, 'arcane', 'magus 6, sorcerer/wizard 6; Elemental School fire 6; Mystery volcano 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '3 rounds', 'none', 'yes', 'You blast several enemies with beams of fire. You may fire three rays, plus one additional ray for every four levels beyond 11th (to a maximum of five rays at 19th level). Each ray requires a ranged touch attack to hit and deals 4d6 points of fire damage.', NULL, NULL, false, false),
  ('contagious_suggestion', 'Contagious Suggestion', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 4, 'arcane', 'bard 4, medium 4, mesmerist 4, occultist 5, psychic 5, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./level)', 'one living creature', NULL, NULL, '1 hour/level or until completed (D)', NULL, NULL, 'This spell functions as per suggestion, except the target can pass on the enchantment to other targets. The target is compelled to communicate your suggestion to another creature, forcing the new target to attempt a saving throw as if it were the initial target. If a secondary target successfully saves, the suggestion effect on the initial target isn’t negated. If a secondary target fails, it is placed under the same compulsion as the initial target and can further spread the suggestion. This spell can affect a total number of Hit Dice of creatures equal to your caster level.', NULL, NULL, false, false),
  ('contagious_zeal', 'Contagious Zeal', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'divine', 'bard 2, cleric/oracle 3, inquisitor 3, psychic 3, sorcerer/wizard 3, spiritualist 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'The target gains a +2 morale bonus on attack rolls and weapon damage rolls, 1d6 temporary hit points, and a +4 morale bonus on saving throws against fear effects and to the DC of Intimidate checks attempted against her. Once per round, the target can select one other creature to gain this bonus as well.', NULL, NULL, false, false),
  ('contest_of_skill', 'Contest of Skill', 'transmutation', NULL, 'curse', 2, 'divine', 'bard 2, cleric 3, magus 2, paladin 2', '1 standard action', 'close (25 ft. plus 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'The randomness of critical hits has long vexed certain duelists in the school who consider luck to be an unwelcome addition to duels, which they view as contests of skill rather than chance.', 'a tiny gong', NULL, false, false),
  ('contingency', 'Contingency', 'evocation', NULL, NULL, 6, 'arcane', 'sorcerer/wizard 6; Bloodline astral 6; Mystery time 6', 'at least 10 minutes; see text', 'personal', 'you', NULL, NULL, '1 day/level (D) or until discharged', NULL, NULL, 'You can place another spell upon your person so that it comes into effect under some condition you dictate when casting contingency. The contingency spell and the companion spell are cast at the same time. The 10-minute casting time is the minimum total for both castings; if the companion spell has a casting time longer than 10 minutes, use that instead. You must pay any costs associated with the companion spell when you cast contingency.', 'quicksilver and an eyelash of a spell-using creature', 'ivory statuette of you worth 1,500 gp', false, true),
  ('contingent_action', 'Contingent Action', 'evocation', NULL, NULL, 3, 'arcane', 'bard 3, psychic 3, sorcerer/wizard 3', '1 minute', 'close (25 ft. + 5 ft./2 levels) EFFECT', 'one willing creature', NULL, NULL, '1 minute/level (D) or until discharged', 'Will negates (harmless)', 'Yes (harmless)', 'The target gains an extra action that becomes available when a condition which you dictate is met. At the time of casting, you dictate the condition, and the target specifies a readied action that occurs when triggered by this condition.', NULL, NULL, false, false),
  ('contingent_scroll', 'Contingent Scroll', 'evocation', NULL, NULL, 4, 'arcane', 'bard 4, sorcerer/wizard 4', '10 minutes', 'personal', 'you', NULL, NULL, '10 minutes/level (D) or until discharged', 'Will negates (harmless)', 'yes (harmless)', 'You transfer the power of a scroll to the target so that it comes into effect under some condition you dictate. Casting this spell destroys the scroll, but allows the spell in it to be triggered in a manner similar to the contingency spell. The spell on the scroll must be a spell on your spell list, it must affect the target of this spell (the target of this spell is considered the caster of the scroll), and its level must be no higher than one-fourth your caster level (maximum 5th level).', 'the scroll to be triggered; see text', 'a platinum quill worth 100 gp', false, true),
  ('contingent_venom', 'Contingent Venom', 'necromancy', NULL, 'poison', 4, 'divine', 'shaman 4, sorcerer/ wizard 4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as languid venom, but you can stipulate a specific condition or circumstance that will end the poison’s onset time and cause it to take effect. The conditions for triggering the poison can be as general or as detailed as desired, but the triggers must be visual or audible (as per magic mouth) or else based on physical contact with or consumption of a specific object, substance, or creature. This triggering condition can either result in the immediate onset of the poison, or cause the poison to take effect a number of rounds after being triggered no greater than 1 round per caster level. You must make all decisions involving triggering when you cast contingent venom, and you can’t change those decisions later.', 'herbs used in antitoxins worth 100 gp', NULL, false, true),
  ('continual_flame', 'Continual Flame', 'evocation', NULL, 'light', 2, 'divine', 'cleric/oracle 3, inquisitor 3, occultist 2, psychic 3, sorcerer/wizard 2; Subdomain day 2; Elemental School void 2', '1 standard action', 'touch', 'object touched', NULL, 'magical, heatless flame', 'permanent', 'none', 'no', 'A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn’t use oxygen. A continual flame can be covered and hidden but not smothered or quenched.', 'ruby dust worth 50 gp', NULL, false, true),
  ('control_construct', 'Control Construct', 'transmutation', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7; Elemental School metal 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one construct', NULL, NULL, 'concentration', 'none (see text); Spell resistance no', NULL, 'You wrest the control of a construct from its master. For as long as you concentrate, you can control the construct as if you were its master. You must make a Spellcraft check each round to maintain control. The DC of the Spellcraft check is (10 + the construct’s HD). If the construct’s creator or master is present and trying to control the construct, you both must make opposed Spellcraft checks each round to control the construct.', NULL, NULL, false, false),
  ('control_plants', 'Control Plants', 'transmutation', NULL, NULL, 9, 'arcane', 'druid 8; Domain plant 8; Elemental School wood 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 min./level', 'Will negates', 'no', 'This spell enables you to control the actions of one or more plant creatures for a short period of time. You command the creatures by voice and they understand you, no matter what language you speak. Even if vocal communication is impossible, the controlled plants do not attack you. At the end of the spell, the subjects revert to their normal behavior.', NULL, NULL, true, false),
  ('control_summoned_creature', 'Control Summoned Creature', 'enchantment', 'compulsion', 'mind-affecting', 3, 'divine', 'bard 3, cleric/oracle 4, sorcerer/wizard 4, summoner/unchained summoner 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one summoned creature', NULL, NULL, '1 round/level', 'Will negates; Spell resistance yes', NULL, 'You seize control of a summoned creature by disrupting the bond between it and the caster who summoned it. If the creature fails its save, you may command it as if you had summoned it. The original caster can attempt to regain control of the creature as a standard action by making an opposed Spellcraft check against you. When your spell ends, control reverts to the original summoner. If the summoning spell ends before this spell ends, the remaining duration of this spell is lost.', NULL, NULL, false, false),
  ('control_undead', 'Control Undead', 'necromancy', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7; Bloodline ghoul 7; Mystery bones 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 min./level', 'Will negates', 'yes', 'This spell enables you to control undead creatures for a short period of time. You command them by voice and they understand you, no matter what language you speak. Even if vocal communication is impossible, the controlled undead do not attack you. At the end of the spell, the subjects revert to their normal behavior.', 'a piece of bone and a piece of raw meat', NULL, false, false),
  ('control_vermin', 'Control Vermin', 'transmutation', NULL, NULL, 2, 'divine', 'cleric 3, druid 2, ranger 4, sorcerer/wizard 3, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'up to 1 HD/level of vermin, no two of which can be more than 30 ft. apart', NULL, NULL, '1 hour/level', 'Will negates', 'no', 'You and a number of allies less than or equal to your caster level designated upon casting can use Handle Animal and Ride checks to influence or control the targeted vermin as if they were animals and had animal-level intelligence.---', NULL, NULL, true, false),
  ('control_water', 'Control Water', 'transmutation', NULL, 'water', 4, 'divine', 'cleric/oracle 4, druid 4, shaman 4, sorcerer/wizard 6; Domain water 4; Bloodline aquatic 5', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'water in a volume of 10 ft./level by 10 ft./level by 2 ft./level (S)', NULL, '10 min./level (D)', 'none; see text', 'no', 'This spell has two different applications, both of which control water in different ways. The first version of this spell causes water in the area to swiftly evaporate or to sink into the ground below, lowering the water’s depth. The second version causes the water to surge and rise, increasing its overall depth and possibly flooding nearby areas.', 'a pinch of dust for lower water or a drop of water for raise water', NULL, true, false),
  ('control_weather', 'Control Weather', 'transmutation', NULL, NULL, 7, 'divine', 'cleric/oracle 7, druid 7, shaman 7, sorcerer/wizard 7, witch 7; Domain weather 7; Subdomain catastrophe 7; Elemental School air 7, water 7, wood 7; Mystery battle 7, wind 7', '10 minutes; see text', '2 miles', NULL, NULL, NULL, '4d12 hours; see text', 'none', 'no', 'You change the weather in the local area. It takes 10 minutes to cast the spell and an additional 10 minutes for the effects to manifest. You can call forth weather appropriate to the climate and season of the area you are in. You can also use this spell to cause the weather in the area to become calm and normal for the season.', NULL, NULL, false, false),
  ('control_winds', 'Control Winds', 'transmutation', NULL, 'air', 5, 'divine', 'druid 5, shaman 5; Domain air 5, weather 6; Mystery wind 5', '1 standard action', '40 ft./level', NULL, NULL, NULL, '10 min./level', 'Fortitude negates', 'no', 'You alter wind force in the area surrounding you. You can make the wind blow in a certain direction or manner, increase its strength, or decrease its strength. The new wind direction and strength persist until the spell ends or until you choose to alter your handiwork, which requires concentration. You may create an “eye” of calm air up to 80 feet in diameter at the center of the area if you so desire, and you may choose to limit the area to any cylindrical area less than your full limit.', NULL, NULL, false, false),
  ('controlled_fireball', 'Controlled Fireball', 'evocation', NULL, 'fire, ruse', 4, 'arcane', 'bloodrager 4, magus 4, occultist 4, sorcerer/wizard 4', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, '20-foot-radius spread', NULL, 'instantaneous', 'Reflex half', 'yes', 'This spell functions as fireball except you can cause the bead of fire to originate from anywhere you can see within range.', 'a ball of bat guano and sulfur', NULL, false, false),
  ('conversing_wind', 'Conversing Wind', 'transmutation', NULL, 'air', 4, 'arcane', 'bard 4, sorcerer/wizard 4 Duration 1 hour/level (D)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as whispering wind, except it can carry responses and doesn’t end after delivering its first message.', NULL, NULL, false, false),
  ('coordinated_effort', 'Coordinated Effort', 'divination', NULL, NULL, 3, 'arcane', 'bard 3, inquisitor 3; Subdomain cooperation 3; Mystery succor 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level', 'none', 'no', 'Choose a single teamwork feat that you possess. You forge a link with your allies, allowing them to gain the benefits of the chosen feat even if they do not have it themselves. You must be a part of the group qualifying for a given bonus for your allies to gain the benefits. For example, two of your allies flanking an orc would gain no benefit from your Outflank feat, but an ally flanking the orc with you would. Your allies’ positioning and actions must still meet the prerequisites listed in the teamwork feat for either of you to receive the listed bonus.', NULL, NULL, false, false),
  ('corpse_hammer', 'Corpse Hammer', 'necromancy', NULL, NULL, 4, 'arcane', 'sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'sphere of undead remains composed of 3 or more destroyed undead', '1 round/level', 'none', 'yes', 'When you cast this spell, you draw the remains of nearby destroyed undead together and fuse them into a mass of flesh and bone you can then hurl at any foes within range.', 'a leather glove coated in dried embalming herbs', NULL, false, false),
  ('corpse_lanterns', 'Corpse Lanterns', 'necromancy', NULL, 'light', 2, 'arcane', 'sorcerer/wizard 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'up to 4 lights, all within a 10-ft.-radius area', '1 minute/level (D)', 'none', 'no', 'This spell functions as dancing lights, except it summons up to four spheres of light, each of which glows a sickly pale green. These corpse lanterns shed dim light in a 20-foot radius, and do not increase the light level in areas of normal light or bright light. In dim or normal light, the radiance of corpse lanterns provides a strange contrast, giving all creatures in the area a –5 penalty on Stealth checks. In addition, the hue interferes with illusion (pattern) spells, giving all creatures in the illuminated area a +2 bonus on any saving throws against such spells. Unlike dancing lights, you may have more than one corpse lanterns spell active at a time, but you may only move one set in any given round. Moving the corpse lanterns does not require concentration. Corpse lanterns can be made permanent on an area with a permanency spell by a caster of at least 11th level for the cost of 7,500 gp.', NULL, NULL, false, false),
  ('corrosive_consumption', 'Corrosive Consumption', 'conjuration', 'creation', 'acid', 5, 'arcane', 'magus 5, sorcerer/wizard 5; Subdomain demodand (chaos, evil) 6', '1 standard action', 'touch', 'creature touched', NULL, NULL, '3 rounds', 'none; Spell resistance yes', NULL, 'With a touch, this spell causes a small, rapidly growing patch of corrosive acid to appear on the target. On the first round, the acid deals 1 point of acid damage per caster level (maximum 15). On the second round, the acid patch grows and deals 1d4 points of acid damage per caster level (maximum 15d4). On the third and final round, the acid patch covers the entire creature and deals 1d6 points of acid damage per caster level (maximum 15d6). The target can spend a full-round action to scrape off the acid, or can wash it off with at least 1 gallon of liquid to halve the damage for that round and negate the remaining rounds of the spell.', NULL, NULL, false, false),
  ('corrosive_touch', 'Corrosive Touch', 'conjuration', 'creation', 'acid', 1, 'arcane', 'bloodrager 1, magus 1, sorcerer/ wizard 1, summoner/unchained summoner 1', '1 standard action', 'touch', 'creature or object touched', NULL, NULL, 'instantaneous', 'none', 'yes', 'Your successful melee touch attack deals 1d4 points of acid damage per caster level (maximum 5d4).', NULL, NULL, false, false),
  ('corruption_resistance', 'Corruption Resistance', 'abjuration', NULL, 'chaotic, evil, good, or lawful', 2, 'divine', 'antipaladin 2, inquisitor 2, paladin 2', '1 standard action', 'touch', NULL, NULL, NULL, '10 minutes/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'You grant the touched creature limited protection from magical effects that inflict damage based on the target creature’s alignment, such as holy smite, order’s wrath, a paladin‘s smite evil attack, or an unholy weapon. Choose one alignment type: chaos, evil, good, or law. The subject takes 5 less points of damage from effects that specifically harm creatures of that alignment. The value of the protection increases to 10 points at 7th level and 15 points at 11th level. The spell protects the recipient’s equipment as well.', NULL, NULL, true, false),
  ('cosmic_ray', 'Cosmic Ray', 'evocation', NULL, NULL, 5, 'arcane', 'magus 5, sorcerer/wizard 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'ray', 'instantaneous and 1 round/level (see text)', 'Fortitude partial', 'yes', 'You fling a ray of deadly cosmic energy at the target creature.', 'a piece of meteorite', NULL, false, false),
  ('counterbalancing_aura', 'Counterbalancing Aura', 'abjuration', NULL, NULL, 8, 'divine', 'cleric 8', '1 standard action', '20 ft.', 'one creature/level in a 20-ft.-radius burst centered on you', NULL, NULL, '1 round/level', 'see text', 'yes', 'An oscillating bronze glow surrounds the targets, protecting them from attacks, granting them resistance to spells cast by neutral creatures, and sickening or nauseating neutral creatures that strike the targets. This abjuration has four effects.', NULL, 'a set of scales worth 500 gp', false, true)
